import{n as e,t}from"./helpers-0sYvox5E.js";var n=[t({id:`backup-archive-001`,building:`backup-archive`,postGuide:[`backup-hourly-frequency`],postGuideKey:[`backup-hourly-frequency`],bullets:[`4.1-K5`],d:1,stem:`A company takes a nightly snapshot of the Amazon EBS volume that holds its order database. The business now says it can tolerate losing at most one hour of data after a failure. Which change meets this requirement at the LOWEST cost?`,correct:[`Schedule hourly snapshots by using AWS Backup or Amazon Data Lifecycle Manager`,`How often backups run determines the achievable recovery point, and both services can automate snapshot creation on a schedule.`],wrong:[[`Keep the nightly snapshots and extend their retention period to 90 days`,`Retention changes how long snapshots are kept and not how often they are taken, so up to a day of data could still be lost.`],[`Keep the nightly snapshots and copy each one to a second AWS Region`,`A copy protects against a Regional failure and does not shorten the interval between snapshots, so the recovery point stays at one day.`],[`Keep the nightly snapshots and add a full copy of the volume to Amazon S3 each week`,`A weekly copy adds a restore point only once a week, which is further from the one-hour target than the nightly snapshot.`]],slot:0,evidence:[`dr-options|How often you run your backup will determine your achievable recovery point (which should align to meet your RPO).`,`ebs-snapshots|For data resiliency and disaster recovery, it is your responsibility to create EBS snapshots on a regular basis, or to set up automatic snapshot creation by using Automate backups with Amazon Data Lifecycle Manager or AWS Backup.`]}),t({id:`backup-archive-002`,building:`backup-archive`,bullets:[`4.1-K5`],d:2,stem:`A company runs a database on Amazon EC2 with a 2 TB Amazon EBS volume, and about 2 percent of the blocks change each day. The company needs a restore point for each of the last 30 days. Which backup design has the LOWEST storage cost?`,correct:[`Take a snapshot of the volume every day and keep each one for 30 days`,`EBS snapshots are incremental, so after the first one each snapshot stores only the blocks that changed since the previous snapshot.`],wrong:[[`Copy the entire volume contents to a new Amazon S3 object each night with a script and keep 30 copies`,`Every copy is a full 2 TB image, so storage grows by the whole volume each day instead of by the changed blocks.`],[`Move each snapshot to the EBS Snapshots Archive tier right after it is created and keep it for 30 days`,`Archived snapshots are always full snapshots, and the archive tier has a 90-day minimum period that is billed even if a snapshot is deleted earlier.`],[`Take a snapshot every day and delete the previous snapshot after each new one completes`,`Only one restore point would exist at a time, so the requirement for a restore point for each of the last 30 days is not met.`]],slot:1,evidence:[`ebs-snapshots|incremental backup, which means that we save only the blocks on the volume that have changed since the most recent snapshot.`,`ebs-archive-considerations|Archived snapshots are always full snapshots.`,`ebs-archive-considerations|If you delete or permanently restore an archived snapshot before the minimum archive period of 90 days, you are billed for remaining days in the archive tier, rounded to the nearest hour.`]}),e({id:`backup-archive-003`,building:`backup-archive`,bullets:[`4.1-K5`],d:2,stem:`A company runs an Amazon RDS database that it will retire at the end of the month. Auditors want the company to be able to restore the data to any point in time within a 7-day window, including for the 7 days after the DB instance is deleted. The company wants to avoid paying for a running DB instance or for custom scripts. Which TWO actions meet these requirements MOST cost-effectively? (Choose two.)`,correct:[[`Set the backup retention period of the DB instance to 7 days`,`RDS keeps automated backups for the retention period you specify and lets you recover to any point in time within it.`],[`Choose to retain automated backups when deleting the DB instance`,`Retained automated backups are saved for the full retention period after the instance is deleted.`]],wrong:[[`Take only a final DB snapshot when deleting the DB instance`,`A final snapshot restores the data as it was at one moment, not to any point in time in the 7-day window.`],[`Keep the DB instance running for 7 more days after the retirement date`,`The company would keep paying for a running DB instance, which the requirements say to avoid.`],[`Run a script that takes a manual DB snapshot every day until the end of the month`,`It needs custom scripts and gives one restore point per day rather than any point in time.`]],slots:[1,3],evidence:[`rds-automated-backups|RDS saves the automated backups of your DB instance according to the backup retention period that you specify.`,`rds-automated-backups|If necessary, you can recover your DB instance to any point in time during the backup retention period.`,`rds-automated-backups|If you choose to retain automated backups when you delete a DB instance, the automated backups are saved for the full retention period.`]}),t({id:`backup-archive-004`,postGuide:[`backup-ebs-cold-storage`],building:`backup-archive`,bullets:[`4.1-S6`],d:3,stem:`A company takes a daily snapshot of a 1 TB Amazon EBS volume and keeps each snapshot for 30 days. About 5 percent of the blocks change each day, and restores must be possible within a few hours. An engineer wants to move every snapshot older than 7 days to the EBS Snapshots Archive tier to save cost. Which approach is MOST cost-effective?`,correct:[`Keep all snapshots in the standard tier and let the retention setting delete them after 30 days`,`Standard-tier snapshots are incremental and restore quickly, while archiving would add a 90-day minimum period and full-size snapshots.`],wrong:[[`Archive each snapshot manually 7 days after it is created and delete it on day 30`,`Deleting an archived snapshot before the 90-day minimum archive period is billed for the remaining days, and archived snapshots are full snapshots that are larger.`],[`Use an AWS Backup plan that moves backups to cold storage after 8 days and deletes them after 30 days in total`,`Cold storage requires a total retention period of at least 90 days, so a 30-day plan cannot use it.`],[`Archive every snapshot right after it is created and restore one only when needed`,`Restoring an archived snapshot can take up to 72 hours, which does not meet the requirement for restores within a few hours.`]],slot:3,evidence:[`ebs-archive-considerations|The minimum archive period is 90 days.`,`ebs-archive-considerations|If you delete or permanently restore an archived snapshot before the minimum archive period of 90 days, you are billed for remaining days in the archive tier, rounded to the nearest hour.`,`ebs-archive-considerations|It can take up to 72 hours to restore an archived snapshot from the archive tier to the standard tier, depending on the size of the snapshot.`,`backup-create-plan|To use cold storage, you must have a total retention period of 90 days or greater.`]}),t({id:`backup-archive-005`,building:`backup-archive`,bullets:[`4.1-K5`,`4.1-S6`],d:2,stem:`A company uses an AWS Backup plan to take a monthly backup of its Amazon EFS file systems. Each backup must be kept for two years and is rarely restored. The company wants the LOWEST storage cost for the long retention with the LEAST operational overhead. Which lifecycle setting meets these requirements?`,correct:[`Move backups to cold storage after 30 days and set the total retention period to 730 days`,`Cold storage is a lower-cost tier for long-kept backups, and it needs a total retention period of 90 days or greater, which 730 days satisfies.`],wrong:[[`Move backups to cold storage after 30 days and set the total retention period to 60 days`,`The backups must be kept for two years, so a 60-day retention period is too short, and cold storage needs a total retention period of 90 days or greater.`],[`Keep every backup in warm storage for the full 730 days and do not use cold storage`,`Backups that are rarely restored can use the cheaper cold tier, so leaving two years of backups warm pays more than needed.`],[`Run a script on an instance that copies each backup to Amazon S3 Glacier Deep Archive`,`The script must be written and maintained, which conflicts with the least operational overhead, and it bypasses the central backup plan.`]],slot:2,evidence:[`aws-backup-plan-options|Depending on how long you choose to store your backup, you may wish to transition your backup to a lower-cost tier called cold storage.`,`backup-create-plan|To use cold storage, you must have a total retention period of 90 days or greater.`]}),t({id:`backup-archive-006`,building:`backup-archive`,bullets:[`4.1-S6`],d:2,stem:`An application stores closed-account statements as files on an Amazon EBS volume attached to an Amazon EC2 instance. The statements must be kept for seven years, are almost never read, and auditors request individual files with a day or two of notice. The EBS volume is growing and the company wants the LOWEST cost. Which solution meets these requirements?`,correct:[`Move the statement files to Amazon S3 and store them in S3 Glacier Deep Archive`,`Deep Archive is designed for archive data accessed less than once a year, and individual files can be restored in 9 to 48 hours.`],wrong:[[`Take daily snapshots of the EBS volume and keep them for seven years`,`Snapshots protect the live volume, but the statements would stay on the growing volume, and retrieving one file means restoring a whole snapshot.`],[`Archive an EBS snapshot of the volume in the Snapshots Archive tier and keep the volume running`,`The statements would still occupy the growing volume, and a single file requires a restore of the whole snapshot that can take up to 72 hours.`],[`Move the statement files to S3 Glacier Instant Retrieval`,`It is designed for archive data accessed about once a quarter with millisecond access, which the auditors with a day of notice do not need.`]],slot:0,evidence:[`s3-storage-classes|S3 Glacier Deep Archive (DEEP_ARCHIVE) Long-lived archive data accessed less than once a year with retrieval times of hours`,`s3-glacier-classes|S3 Glacier Instant Retrieval 90 days Quarterly Milliseconds No S3 Glacier Flexible Retrieval 90 days Semi-annually Minutes to 12 hours Yes S3 Glacier Deep Archive 180 days Annually 9 to 48 hours Yes`,`ebs-archive-considerations|It can take up to 72 hours to restore an archived snapshot from the archive tier to the standard tier, depending on the size of the snapshot.`]}),e({id:`backup-archive-007`,building:`backup-archive`,bullets:[`4.1-S6`],d:3,stem:`A company has two needs. First, daily backups of its Amazon EBS volumes, Amazon RDS databases and Amazon EFS file systems must follow one policy. Second, monthly statement PDFs in Amazon S3 must be kept for ten years, are read less than once a year, and can wait up to three days for retrieval. Which TWO solutions meet these needs MOST cost-effectively? (Choose two.)`,correct:[[`An AWS Backup plan that is applied to the EBS, RDS and EFS resources`,`Backup plans define the requirements once and apply them to resources across the AWS services that the company uses.`],[`An S3 Lifecycle rule that transitions the statement PDFs to S3 Glacier Deep Archive`,`Deep Archive is designed for archive data accessed less than once a year, with 9 to 48 hours retrieval that fits three days.`]],wrong:[[`A separate native backup setup for each service, with scripts for the EBS volumes and EFS file systems`,`The company would manage three configurations and scripts rather than one policy.`],[`AWS Storage Gateway as a Tape Gateway with virtual tapes for the statement PDFs`,`The statements are objects in Amazon S3 and no backup application writes to tape, so a gateway adds components without a benefit.`],[`An S3 Lifecycle rule that transitions the statement PDFs to S3 Glacier Instant Retrieval`,`It is designed for archive data accessed about once a quarter with millisecond access, which is more than the statements need.`]],slots:[2,4],evidence:[`backup-what-is|Use these backup plans to define your backup requirements and then apply them to the AWS resources that you want to protect across the AWS services that you use.`,`s3-storage-classes|S3 Glacier Deep Archive (DEEP_ARCHIVE) Long-lived archive data accessed less than once a year with retrieval times of hours`,`sgw-tape|Tape Gateway provides cloud-backed virtual tape storage.`]}),t({id:`backup-archive-008`,building:`backup-archive`,bullets:[`4.1-S6`],d:1,stem:`A company is closing a project. It must keep one final point-in-time copy of a 500 GB Amazon EBS volume for three years for compliance, expects to restore it rarely if ever, and can wait days for a restore. After the copy is stored, the volume will be deleted. Which solution has the LOWEST cost?`,correct:[`Archive a snapshot of the volume in the Amazon EBS Snapshots Archive tier`,`The archive tier is for low-cost, long-term storage of rarely accessed snapshots, such as the only snapshot of a volume at the end of a project.`],wrong:[[`Keep the volume detached and keep a snapshot in the standard tier`,`The company would keep paying for the volume as well as the standard-tier snapshot, which is not needed once a snapshot is stored.`],[`Keep a snapshot of the volume in the EBS Snapshot standard tier only`,`It works, but the archive tier exists for snapshots kept 90 days or longer and rarely accessed, so the standard tier costs more.`],[`Copy the snapshot to a second AWS Region and keep the copy in the standard tier`,`It adds a second copy and stays in the standard tier, which costs more than the archive tier for a snapshot kept 90 days or longer and rarely accessed.`]],slot:1,evidence:[`ebs-snapshot-archive|Archiving the only snapshot of a volume, such as end-of-project snapshots`,`ebs-snapshot-archive|for snapshots that you plan to store for 90 days or longer and that you rarely need to access.`,`ebs-snapshots|You can't access your snapshots using the Amazon S3 console or the Amazon S3 API.`]}),t({id:`backup-archive-009`,building:`backup-archive`,bullets:[`4.1-S6`],d:2,tags:[`mock-reserve`],stem:`A company runs an on-premises database server that uses iSCSI block volumes. The application needs low-latency access to the entire 5 TB dataset from local disks, and the company wants point-in-time backups of that data stored in AWS without changing the application. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Deploy an AWS Storage Gateway Volume Gateway that uses stored volumes`,`Stored volumes keep the entire dataset on premises for low-latency access and asynchronously back up point-in-time snapshots to Amazon S3.`],wrong:[[`Deploy a Volume Gateway that uses cached volumes`,`Cached volumes keep the primary data in AWS and only frequently accessed data locally, so the entire dataset is not available at local latency.`],[`Deploy an Amazon S3 File Gateway and move the database files to its file share`,`It offers file shares rather than iSCSI block volumes, so the application would have to change.`],[`Deploy a Tape Gateway and have the server write its data to virtual tapes`,`It presents virtual tapes to backup software and does not give the database local block volumes.`]],slot:3,evidence:[`sgw-volume|Stored volumes – If you need low-latency access to your entire dataset, first configure your on-premises gateway to store all your data locally.`,`sgw-volume|Then asynchronously back up point-in-time snapshots of this data to Amazon S3.`]})],r=[t({id:`block-warehouse-001`,building:`block-warehouse`,bullets:[`4.1-K6`],d:1,stem:`A company keeps 10 TB of infrequently accessed data on a non-boot data volume of an Amazon EC2 instance. The data is read sequentially a few times a year, and the company wants the LOWEST storage cost. Which Amazon EBS volume type should the company use?`,correct:[`Cold HDD (sc1)`,`Cold HDD is throughput-oriented storage for infrequently accessed data where the lowest storage cost is important.`],wrong:[[`General Purpose SSD (gp3)`,`It is the lowest cost SSD type, but the data is rarely read and does not need SSD performance.`],[`Provisioned IOPS SSD (io2)`,`It targets I/O-intensive workloads that need sustained IOPS, which this rarely read data does not.`],[`Throughput Optimized HDD (st1)`,`It suits frequently accessed streaming workloads such as big data and logs, not data that is rarely read.`]],slot:0,evidence:[`ebs-volume-types|Throughput-oriented storage for data that is infrequently accessed Scenarios where the lowest storage cost is important`]}),t({id:`block-warehouse-002`,building:`block-warehouse`,bullets:[`4.1-K6`],d:2,stem:`A company launches a fleet of Amazon EC2 web servers. Each server needs a root volume for the operating system, and the company wants the LOWEST cost option that can serve as a boot volume. Which Amazon EBS volume type meets these requirements?`,correct:[`General Purpose SSD (gp3)`,`gp3 is the lowest cost SSD volume type, is recommended for most workloads, and supports use as a boot volume.`],wrong:[[`Cold HDD (sc1), because it has the lowest storage cost of the volume types`,`HDD-backed volumes cannot be used as boot volumes.`],[`Throughput Optimized HDD (st1), because the operating system reads files sequentially`,`HDD-backed volumes cannot be used as boot volumes, whatever the access pattern.`],[`Provisioned IOPS SSD (io2) Block Express, because it has the most consistent latency`,`It can boot an instance, but it is built for I/O-intensive databases that need sub-millisecond latency, which web servers do not.`]],slot:1,evidence:[`ebs-volume-types|Amazon EBS Multi-attach Not supported Boot volume Not supported`,`ebs-volume-types|Transactional workloadsVirtual desktopsMedium-sized, single-instance databasesLow-latency interactive applicationsBoot volumesDevelopment and test environments`,`ebs-gp|General Purpose SSD (gp3) volumes are the latest generation of General Purpose SSD volumes, and the lowest cost SSD volume offered by Amazon EBS.`]}),t({id:`block-warehouse-003`,building:`block-warehouse`,bullets:[`4.1-K6`],d:3,tags:[`trap:instance-store-vs-ebs`],stem:`A video company runs batch jobs on Amazon EC2. Each job writes about 1 TB of intermediate scratch data that is deleted when the job ends and can be recreated by rerunning the job. The company wants the LOWEST storage cost for this scratch data and does not need it to survive a stop or termination. Which solution meets these requirements?`,correct:[`Use the instance store volumes that come with an instance type that includes local disks`,`Instance store suits temporary scratch data and its volumes are included in the usage cost of the instance, with no extra charge.`],wrong:[[`Attach a Provisioned IOPS SSD (io2) volume to each instance and delete it after the job`,`Each volume is a separately provisioned and billed resource, and the scratch data needs no persistence beyond the job.`],[`Attach a General Purpose SSD (gp3) volume and take a snapshot every hour during each job`,`This adds a billed volume and snapshot storage to protect data that can simply be recreated.`],[`Mount an Amazon EFS file system on every instance and remove the files after each job`,`EFS adds a billed shared file system for data that only one instance uses and that does not need to be shared or kept.`]],slot:2,evidence:[`instance-store|Instance store is ideal for temporary storage of information that changes frequently, such as buffers, caches, scratch data, and other temporary content.`,`instance-store|Instance store volumes are included as part of the usage cost of the instance.`,`instance-store-lifetime|However, the data does not persist if the instance is stopped, hibernated, or terminated.`]}),t({id:`block-warehouse-004`,building:`block-warehouse`,bullets:[`4.1-S2`],d:1,stem:`A Linux Amazon EC2 instance supports an application that cannot be stopped. Its Amazon EBS data volume is almost full, and the company wants to add capacity with the LEAST downtime. Which solution meets these requirements?`,correct:[`Increase the volume size with Amazon EBS Elastic Volumes and then extend the file system`,`Elastic Volumes can grow a volume without detaching it or restarting the instance, and the file system is then extended to use the new size.`],wrong:[[`Stop the instance, detach the volume, and attach a larger volume created from a snapshot`,`Stopping the instance and detaching the volume causes the downtime the company wants to avoid.`],[`Take a snapshot, delete the volume, and create a larger volume from the snapshot`,`Deleting the volume while the application is running interrupts it, and the application cannot be stopped.`],[`Shut down the application during the weekend and run a restore from a backup onto larger storage`,`A planned shutdown is still downtime, and the application cannot be stopped.`]],slot:3,evidence:[`ebs-modify|If your instance supports Elastic Volumes, you can do so without detaching the volume or restarting the instance.`,`ebs-extend-fs|After you increase the size of an EBS volume, you must extend the partition and file system to the new, larger size.`]}),t({id:`block-warehouse-005`,building:`block-warehouse`,bullets:[`4.1-S2`],d:2,stem:`A company provisioned a 4 TiB Amazon EBS data volume for a database, but only 300 GiB is used and growth is slow. The company wants to reduce the provisioned size to cut storage cost. Which solution meets this requirement?`,correct:[`Create a smaller volume, copy the data to it with an application-level tool, and delete the large volume`,`The volume size cannot be decreased, but you can create a smaller volume and migrate the data to it with a tool such as rsync.`],wrong:[[`Use Amazon EBS Elastic Volumes to reduce the size of the volume while it stays attached`,`Elastic Volumes can increase the size, but you cannot decrease the volume size.`],[`Change the volume type to Cold HDD (sc1) so that the provisioned size shrinks to fit the data`,`Changing the type does not reduce the provisioned size of the volume.`],[`Take a snapshot of the volume and delete the unused space from the snapshot to shrink the volume`,`Deleting data does not reduce the size of a volume, so the provisioned size and its charge stay the same.`]],slot:0,evidence:[`ebs-modify|You can't decrease the volume size.`,`ebs-modify|However, you can create a smaller volume and then migrate your data to it using an application-level tool such as rsync (Linux instances) or robocopy (Windows instances).`]}),e({id:`block-warehouse-006`,building:`block-warehouse`,bullets:[`4.1-S2`,`4.1-S4`],d:3,stem:`A company is moving a relational database to Amazon RDS. It needs 200 GiB today, and growth is unpredictable. A forecast says that it could reach several terabytes within two years. The company wants to avoid an outage from running out of space and does not want to pay for capacity it does not yet use, with the LEAST operational overhead. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Provision the storage that the database needs now instead of the forecast maximum`,`Sizing for the current need avoids paying for capacity that is unused for a long time.`],[`Enable RDS storage autoscaling and set a maximum storage threshold`,`RDS scales storage up automatically when free space runs low, up to the limit that you set, so no one has to react.`]],wrong:[[`Provision the several terabytes forecast for two years from now on the first day`,`This pays for capacity that is unused for a long time, which the company does not want.`],[`Create a CloudWatch alarm that pages an engineer to resize the storage by hand`,`This relies on a manual response and risks an outage, where autoscaling acts on its own.`],[`Move to a larger DB instance class whenever free space becomes low`,`The instance class sets compute and memory capacity and is not how database storage is increased.`]],slots:[0,3],evidence:[`rds-storage-autoscaling|If your workload is unpredictable, you can enable storage autoscaling for an Amazon RDS DB instance.`,`rds-storage-autoscaling|With storage autoscaling enabled, when Amazon RDS detects that you are running out of free database space it automatically scales up your storage.`,`rds-storage-autoscaling|The maximum storage threshold is the limit that you set for autoscaling the DB instance.`]}),t({id:`block-warehouse-007`,building:`block-warehouse`,bullets:[`4.1-S4`],d:2,stem:`A company runs a fleet of Linux Amazon EC2 instances in several Availability Zones that must share the same files. The total size of the files is unpredictable and can both grow and shrink. The company does not want to provision or resize storage and wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Store the files in an Amazon EFS file system mounted on all of the instances`,`EFS grows and shrinks automatically as files are added and removed, and the instances in all of the zones can share it without provisioning capacity.`],wrong:[[`Attach one large General Purpose SSD (gp3) volume to every instance and synchronize them`,`Each volume has a provisioned size to manage and the copies must be kept in sync, which adds overhead.`],[`Attach a Provisioned IOPS SSD (io2) volume with Multi-Attach to all of the instances`,`Multi-Attach works only for instances in the same Availability Zone, and the size is still provisioned.`],[`Create a Throughput Optimized HDD (st1) volume sized for the largest expected data set`,`It is attached to one instance in one zone, and capacity still has to be provisioned and resized.`]],slot:1,evidence:[`efs-what-is|Amazon EFS is built to scale on demand to petabytes without disrupting applications, growing and shrinking automatically as you add and remove files.`,`efs-what-is|Amazon Elastic File System (Amazon EFS) provides serverless, fully elastic file storage so that you can share file data without provisioning or managing storage capacity and performance.`,`ebs-multi-attach|Multi-Attach enabled volumes can be attached to up to 16 instances built on the Nitro System that are in the same Availability Zone.`]}),t({id:`block-warehouse-008`,building:`block-warehouse`,bullets:[`4.1-S4`],d:2,stem:`A photo application on Amazon EC2 keeps user uploads on a 2 TiB General Purpose SSD (gp3) volume. Uploads grow unpredictably, and engineers resize the volume by hand every few weeks. The developers can change the application to call an object storage API, and the company wants to stop managing capacity with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Store the uploads in Amazon S3, which holds any amount of data without capacity to provision`,`S3 stores any amount of data, so there is no volume size to forecast or increase as uploads grow.`],wrong:[[`Provision a single 16 TiB gp3 volume so that resizing is not needed for a long time`,`This pays for capacity that is not used yet, and the volume still has a fixed size that will eventually need to be changed.`],[`Replace the volume with a Cold HDD (sc1) volume of the same size to lower the cost`,`A different volume type still has a provisioned size that engineers have to monitor and increase.`],[`Attach an additional gp3 volume each time the current one fills and spread the uploads across them`,`This keeps manual capacity management and makes the application track which volume holds each upload.`]],slot:2,evidence:[`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`,`ebs-modify|You can't decrease the volume size.`]}),e({id:`block-warehouse-009`,building:`block-warehouse`,bullets:[`4.1-K6`],d:3,tags:[`mock-reserve`],stem:`A company attaches two non-boot data volumes to Amazon EC2 instances. Volume one holds 12 TB of log data that is scanned sequentially every day and must deliver 400 MiB/s of throughput per volume. Volume two holds 10 TB of compliance data that is read a few times a year. Which TWO volume choices meet these requirements at the LOWEST storage cost? (Choose two.)`,correct:[[`Use Throughput Optimized HDD (st1) for the log data`,`st1 suits log processing and large streaming workloads, and its maximum throughput per volume covers 400 MiB/s.`],[`Use Cold HDD (sc1) for the compliance data`,`sc1 is for infrequently accessed data where the lowest storage cost is important.`]],wrong:[[`Use Cold HDD (sc1) for the log data`,`sc1 has a lower maximum throughput per volume than st1, so it cannot deliver the required 400 MiB/s.`],[`Use Provisioned IOPS SSD (io2) Block Express for the compliance data`,`It is built for I/O-intensive databases, and paying for it for rarely read data is not the lowest cost.`],[`Use General Purpose SSD (gp3) for both volumes to keep one volume type`,`Using SSD for the rarely read compliance data does not give the lowest storage cost.`]],slots:[1,4],evidence:[`ebs-volume-types|Big data Data warehouses Log processing`,`ebs-volume-types|Throughput-oriented storage for data that is infrequently accessed Scenarios where the lowest storage cost is important`,`ebs-volume-types|Volume size 125 GiB - 16 TiB Max IOPS per volume (1 MiB I/O) 500 250 Max throughput per volume 500 MiB/s 250 MiB/s`]})],i=[t({id:`capacity-meter-001`,postGuide:[`dynamodb-price-cut-2024`],building:`capacity-meter`,bullets:[`4.3-K5`],d:1,tags:[`placement-eligible`],stem:`A company's order-tracking service uses an Amazon DynamoDB table in provisioned capacity mode. The consumed capacity has been steady for a year and is expected to stay at the same level for the next year. Finance wants a lower rate for this capacity without any change to the application. Which action is the MOST cost-effective?`,correct:[`Purchase DynamoDB reserved capacity for the steady provisioned read and write capacity`,`Capacity used up to the amount of reserved provisioned capacity that was purchased is charged at the reserved capacity rate.`],wrong:[[`Switch the table to on-demand capacity mode so that it is billed for each request`,`The workload is steady and predictable, which is what provisioned capacity suits, and on-demand mode has no reserved rate.`],[`Change the table to the DynamoDB Standard-IA table class to lower the throughput charges`,`Standard-IA has higher throughput costs and suits tables where storage is the dominant cost, which is not stated here.`],[`Put a DAX cluster in front of the table to take over the steady read and write traffic`,`DAX only reduces read capacity for eventually consistent reads; writes still go through to the table and consume write capacity, and the cluster adds its own charges.`]],slot:0,evidence:[`dynamodb-pricing|Each hour, if the amount of capacity used is less than or equal to the total reserved provisioned capacity you’ve purchased, all capacity will be charged at the reserved capacity rate.`,`trusted-advisor-cost-checks|Checks your Amazon DynamoDB usage patterns and provides recommendations for potential cost savings through reserved capacity purchases.`,`dynamodb-pricing|During billing, capacity usage is first compared to your active reserved capacity to minimize costs.`]}),t({id:`capacity-meter-002`,building:`capacity-meter`,bullets:[`4.3-K5`],d:2,tags:[`placement-eligible`],stem:`A DynamoDB table in provisioned capacity mode holds items that average 6 KB. The application performs 200 eventually consistent reads per second against the table. The company wants to provision the smallest read capacity that avoids throttling. How much read capacity should the company provision?`,correct:[`200 read capacity units`,`A 6 KB item needs 2 units for a strongly consistent read, which rounds up from 6 KB divided by 4 KB, and an eventually consistent read needs half, so 1 unit per read.`],wrong:[[`400 read capacity units`,`This counts each read as strongly consistent, which uses twice the units of the eventually consistent reads the application performs.`],[`300 read capacity units`,`This uses 1.5 units per read from 6 KB divided by 4 KB without rounding up and without halving for eventually consistent reads.`],[`100 read capacity units`,`This halves the reads but assumes one unit covers two reads of a 6 KB item, which is true only for items up to 4 KB.`]],slot:1,evidence:[`dynamodb-provisioned|For an item up to 4 KB, one read capacity unit (RCU) represents one strongly consistent read operation per second, or two eventually consistent read operations per second.`,`dynamodb-provisioned|To determine this number, divide the item size of the operation by 4 KB.`,`dynamodb-provisioned|Then, round up to the nearest whole number, as shown in the following example: 3 KB / 4 KB = 0.75 or 1 read capacity unit`]}),t({id:`capacity-meter-003`,postGuide:[`dynamodb-price-cut-2024`],building:`capacity-meter`,bullets:[`4.3-K5`],d:2,tags:[`placement-eligible`],stem:`A DynamoDB table in provisioned capacity mode has its capacity fixed at the level of the evening peak. Traffic follows a predictable daily curve, and consumed capacity is far below the provisioned capacity for most of the day. The company wants to stop paying for unused capacity and still avoid throttling at the peak. Which solution is the MOST cost-effective?`,correct:[`Enable DynamoDB auto scaling with minimum and maximum capacity and a target utilization`,`Auto scaling raises capacity to handle increases and lowers it when the workload decreases, so the company stops paying for unused capacity.`],wrong:[[`Set the provisioned capacity permanently to the average level of consumption over the day`,`Capacity at the average level would throttle requests during the evening peak.`],[`Add a DAX cluster so that the table needs less provisioned capacity for both reads and writes`,`DAX serves cached eventually consistent reads and does not reduce write capacity, and the cluster itself adds cost.`],[`Change the table to the DynamoDB Standard-IA table class to lower the cost of the unused capacity`,`The table class changes storage and throughput rates but does not lower capacity automatically when traffic drops.`]],slot:2,evidence:[`dynamodb-provisioned|When the workload decreases, DynamoDB auto scaling can decrease the throughput so that you don't pay for unused provisioned capacity.`,`dynamodb-provisioned|You'll be charged based on the hourly read and write capacity you have provisioned, not how much of that provisioned capacity you actually consumed.`]}),e({id:`capacity-meter-004`,postGuide:[`dynamodb-price-cut-2024`],building:`capacity-meter`,bullets:[`4.3-K5`],d:3,tags:[`placement-eligible`],stem:`A company's Amazon DynamoDB table uses on-demand capacity mode and the Standard table class. Read and write traffic has been steady and forecastable for two years and is expected to stay at the same level for the next year. The throughput charges are the dominant cost of the table. Which TWO actions, taken together, reduce the cost of the table the MOST? (Choose two.)`,correct:[[`Switch the table to provisioned capacity mode with read and write capacity sized from the forecast`,`AWS points to provisioned capacity for steady workloads whose capacity can be reliably forecast.`],[`Purchase reserved capacity for the steady read and write capacity the table will provision`,`On top of provisioned mode, provisioned capacity used up to the reserved amount is charged at the lower reserved capacity rate.`]],wrong:[[`Change the table to the DynamoDB Standard-IA table class`,`Standard-IA has higher throughput costs and suits tables where storage, not throughput, is the dominant cost.`],[`Enable Time to Live and store an expiration timestamp in each item`,`TTL removes expired items to trim storage, but the dominant cost here is throughput and the data volume is not the problem.`],[`Add a replica table in a second Region and read from both tables`,`A replica adds a second copy of the data and replicated write charges, which raises the cost instead of lowering it.`]],slots:[1,3],evidence:[`dynamodb-capacity|You can choose to use provisioned capacity if you have steady workloads with predictable growth, and if you can reliably forecast capacity requirements for your application.`,`dynamodb-pricing|Each hour, if the amount of capacity used is less than or equal to the total reserved provisioned capacity you’ve purchased, all capacity will be charged at the reserved capacity rate.`,`dynamodb-table-classes|The DynamoDB Standard table class offers lower throughput costs than DynamoDB Standard-IA and is the most cost-effective option for tables where throughput is the dominant cost.`]}),t({id:`capacity-meter-005`,building:`capacity-meter`,bullets:[`4.3-K3`],d:2,tags:[`placement-eligible`],stem:`A catalog service reads individual product items by key from a DynamoDB table in provisioned capacity mode. A few popular products are read repeatedly all day, eventually consistent reads are acceptable, and the provisioned read capacity is high only to serve these repeated reads. The company does not want to rewrite its data access code. Which change reduces cost the MOST?`,correct:[`Add a DAX cluster and lower the provisioned read capacity of the table`,`DAX is API-compatible with DynamoDB and, for repeated reads, reduces the read capacity units that must be purchased.`],wrong:[[`Increase the provisioned read capacity so that the popular products are read without delay`,`More read capacity raises the cost, while the repeated reads could be served from a cache.`],[`Add an Amazon ElastiCache cluster and write cache lookup logic into the application`,`ElastiCache needs application code to check and fill the cache, which the company wants to avoid.`],[`Change the table to the DynamoDB Standard-IA table class for the popular products`,`Standard-IA suits tables where storage is the dominant cost and has higher throughput charges, which does not fit a read-heavy table.`]],slot:3,evidence:[`dax|For read-heavy or bursty workloads, DAX provides increased throughput and potential operational cost savings by reducing the need to overprovision read capacity units.`,`dax|Or, you can offload the activity from your application to a DAX cluster, and reduce the number of read capacity units that you need to purchase otherwise.`,`dax|DAX reduces operational and application complexity by providing a managed service that is API-compatible with DynamoDB.`]}),t({id:`capacity-meter-006`,building:`capacity-meter`,bullets:[`4.3-K3`,`4.3-K5`],d:3,tags:[`placement-eligible`],stem:`A read-heavy service uses a DynamoDB table in provisioned capacity mode, and read capacity is the dominant cost. Every read is currently strongly consistent. Product owners confirm that catalog browsing reads, most of the traffic, can tolerate slightly old data, while checkout reads must always return the latest data. Which change reduces cost the MOST and meets both needs?`,correct:[`Use eventually consistent reads for browsing, keep strongly consistent reads for checkout, and lower the provisioned read capacity`,`An eventually consistent read uses half of the capacity of a strongly consistent read, and checkout keeps the latest data.`],wrong:[[`Send all reads through a DAX cluster and lower the provisioned read capacity of the table`,`DAX passes strongly consistent reads through to DynamoDB, so checkout reads would still use full capacity and the cluster adds cost.`],[`Use eventually consistent reads for every request and lower the provisioned read capacity`,`Checkout reads could return old data, which breaks the requirement that they always return the latest data.`],[`Change the table to the DynamoDB Standard-IA table class and keep every read strongly consistent`,`Standard-IA has higher throughput costs and suits tables where storage dominates, so a read-heavy table would cost more.`]],slot:0,evidence:[`dynamodb-provisioned|Read capacity units are based on strongly consistent read operations, which consume twice as many database resources as eventually consistent reads.`,`dax-concepts|If the request specifies strongly consistent reads, DAX passes the request through to DynamoDB.`,`dynamodb-table-classes|The DynamoDB Standard table class offers lower throughput costs than DynamoDB Standard-IA and is the most cost-effective option for tables where throughput is the dominant cost.`]}),t({id:`capacity-meter-007`,building:`capacity-meter`,bullets:[`4.3-K3`],d:2,tags:[`placement-eligible`],stem:`A company's application reads product descriptions from Amazon RDS through an Amazon ElastiCache cache that uses lazy loading with a time to live of 20 seconds. The descriptions change about once a day, and the business accepts descriptions that are up to an hour old. Most requests still miss the cache and reach the database, which drives up the database cost. Which change reduces the database reads the MOST with the LEAST change to the application?`,correct:[`Raise the time to live of the cache entries to match the staleness the business accepts`,`An entry that has not expired is a cache hit, so a longer time to live means far fewer expired entries and far fewer reads from the database.`],wrong:[[`Switch to write-through with no time to live so that every written description stays in the cache`,`This changes the application code on every write path and fills the cache with descriptions nobody requests, which wastes cache resources.`],[`Add a larger DB instance class to absorb the reads from the cache misses`,`This pays for more database capacity and leaves the same number of cache misses.`],[`Remove the cache and send every request to the database`,`Every request would then reach the database, which increases the read load and cost.`]],slot:1,evidence:[`elasticache-strategies|A cache hit occurs when data is in the cache and isn't expired: Your application requests data from the cache.`,`elasticache-strategies|A cache miss occurs when data isn't in the cache or is expired: Your application requests data from the cache.`,`elasticache-strategies|Cache churn. Most data is never read, which is a waste of resources.`]}),t({id:`capacity-meter-008`,postGuide:[`dynamodb-price-cut-2024`],building:`capacity-meter`,bullets:[`4.3-K5`],d:1,tags:[`placement-eligible`],stem:`A company runs 20 DynamoDB tables for internal tools. Each table is used for a few minutes a day by a small team and has no traffic the rest of the time. Usage is hard to forecast. Which capacity configuration is the MOST cost-effective?`,correct:[`On-demand capacity mode for each table`,`With on-demand mode there is no charge for throughput while a table has zero traffic, and the company pays only for the requests it makes.`],wrong:[[`Provisioned capacity mode with a small fixed capacity on each table`,`Provisioned capacity is billed for every hour by what is provisioned, even when the tables are idle.`],[`Provisioned capacity mode with reserved capacity purchased for each table`,`Reserved capacity commits to paying for capacity that these mostly idle tables would not use.`],[`Provisioned capacity mode with auto scaling and a DAX cluster for each table`,`Auto scaling still keeps minimum capacity billed, and a DAX cluster per table adds charges for tools used a few minutes a day.`]],slot:2,evidence:[`dynamodb-ondemand|If you are driving zero traffic to your table, then with on-demand, you are not charged for any throughput.`,`dynamodb-provisioned|You'll be charged based on the hourly read and write capacity you have provisioned, not how much of that provisioned capacity you actually consumed.`]}),t({id:`capacity-meter-009`,building:`capacity-meter`,bullets:[`4.3-K6`],d:2,stem:`AWS Lambda functions update orders in an Amazon RDS for MySQL DB instance. During traffic spikes, thousands of short-lived invocations each open a connection and the database logs "too many connections" errors, although its CPU use stays low. The company wants to fix the errors MOST cost-effectively. Which solution meets this requirement?`,correct:[`Create an Amazon RDS Proxy for the DB instance and have the functions connect through it`,`The proxy pools and shares connections, so many short-lived function connections use a small number of connections to the database.`],wrong:[[`Move the DB instance to a larger instance class so that it can hold more connections`,`The CPU is low, so this pays for compute that the workload does not need only to hold connections.`],[`Add a read replica and have the functions send their order updates to the replica`,`A read replica accepts only read-only connections, so the order updates cannot be written to it.`],[`Add an Amazon ElastiCache cache and have the functions write their updates to the cache first`,`A cache does not pool database connections, and the updates would still have to reach the database.`]],slot:3,evidence:[`rds-proxy-planning|Any DB instance that encounters "too many connections" errors is a good candidate for associating with a proxy.`,`rds-proxy-planning|The proxy enables applications to open many client connections, while the proxy manages a smaller number of long-lived connections to the DB instance .`,`rds-proxy-planning|AWS Lambda functions can also be good candidates for using a proxy.`]}),e({id:`capacity-meter-010`,building:`capacity-meter`,bullets:[`4.3-K6`,`4.3-K8`],d:2,tags:[`trap:multi-az-vs-read-replicas`],stem:`An Amazon RDS for MySQL DB instance serves an order application and nightly reports. By day, many short-lived application connections reach the connection limit, and during reporting, heavy read-only queries slow the application. The company wants to fix both problems without moving to a larger DB instance class. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Place Amazon RDS Proxy between the application and the DB instance`,`The proxy pools connections so the database is not sized only to hold the many client connections.`],[`Create a read replica and route the reporting queries to it`,`Routing queries to a read replica reduces the load on the primary DB instance.`]],wrong:[[`Add a Multi-AZ standby replica and run the reporting queries on it`,`A standby replica protects availability and cannot serve read traffic.`],[`Configure automatic scaling of read replicas on the DB instance for the reports`,`Amazon RDS does not support autoscaling of read replicas, so the replicas must be added by hand.`],[`Move the DB instance to a larger instance class and raise its connection limit`,`The company wants to avoid a larger DB instance class, which also costs more.`]],slots:[2,4],evidence:[`rds-proxy-planning|The proxy enables applications to open many client connections, while the proxy manages a smaller number of long-lived connections to the DB instance .`,`rds-read-replicas|You can reduce the load on your primary DB instance by routing queries from your applications to the read replica.`,`rds-read-replicas|Unlike a read replica, a standby replica can't serve read traffic.`]}),e({id:`capacity-meter-011`,building:`capacity-meter`,bullets:[`4.3-K6`,`4.3-K8`],d:3,tags:[`trap:aurora-vs-rds`],stem:`A company runs an Amazon Aurora MySQL-Compatible cluster. AWS Lambda functions open many short-lived connections, which produces connection errors on the writer, and dashboard users add heavy read load only during business hours. The company does not want to pay for idle reader instances overnight. Which TWO actions meet these requirements MOST cost-effectively? (Choose two.)`,correct:[[`Create an Amazon RDS Proxy for the cluster and connect the functions through it`,`The proxy lets the functions open many connections while it keeps a smaller number open to the database.`],[`Configure Aurora Auto Scaling to add Aurora Replicas for the dashboards and remove them when the load drops`,`Aurora Auto Scaling removes unnecessary replicas so the company does not pay for unused DB instances.`]],wrong:[[`Run the maximum number of Aurora Replicas all day and night so that dashboards never wait`,`The replicas sit idle overnight, and the company is paying for unused DB instances.`],[`Convert the cluster to Amazon RDS for MySQL and add read replicas by hand each morning`,`RDS does not autoscale read replicas, so they must be added and removed by hand, which is more effort.`],[`Increase the DB instance class of the writer so that it holds more connections`,`A larger writer costs more all day to hold connections, and the dashboard reads still hit the writer.`]],slots:[0,3],evidence:[`rds-proxy-planning|AWS Lambda functions can also be good candidates for using a proxy.`,`aurora-autoscaling|When the connectivity or workload decreases, Aurora Auto Scaling removes unnecessary Aurora Replicas so that you don't pay for unused provisioned DB instances.`,`rds-read-replicas|RDS doesn't support autoscaling of read replicas, which is the automatic add or removing of read replicas as read demand changes.`]}),t({id:`capacity-meter-012`,building:`capacity-meter`,bullets:[`4.3-K8`],d:2,stem:`A company is adding one read replica of an Amazon RDS for MySQL DB instance in the same AWS Region to offload reporting queries. Finance asks which charges the new replica will add. Which estimate is the MOST accurate?`,correct:[`The replica is billed like a standard DB instance of its instance class, and replication within the Region adds no data transfer charge`,`Read replicas are billed as standard DB instances at the DB instance class rate, and same-Region replication transfer is not charged.`],wrong:[[`The replica adds nothing because it shares the storage and instance of the source DB instance`,`A read replica is a separate DB instance, so it is billed as one.`],[`The replica is billed like a standard DB instance, and data transfer between source and replica in the Region is also charged`,`The data transfer incurred in replicating data within the same Region is not charged.`],[`The replica is billed at a flat discounted rate that does not depend on its instance class`,`Replicas are billed at the same rates as the DB instance class used for the replica, so a larger class costs more.`]],slot:0,evidence:[`rds-read-replicas|Read replicas are billed as standard DB instances at the same rates as the DB instance class used for the replica.`,`rds-read-replicas|You aren't charged for the data transfer incurred in replicating data between the source DB instance and a read replica within the same AWS Region.`]}),t({id:`capacity-meter-013`,building:`capacity-meter`,bullets:[`4.3-K3`],d:2,tags:[`mock-reserve`],stem:`A company caches player scores in Amazon ElastiCache with a write-through strategy, so the cache never returns old scores. When the company adds a cache node to scale out, the new node is empty, and reads for existing scores find nothing in the cache. The company wants fresh data and fewer misses on new nodes without preloading every score. Which change is the MOST cost-effective?`,correct:[`Add lazy loading to the write-through strategy, so a miss reads the database and fills the cache`,`A miss on an empty node is filled from the database on first request, and write-through keeps the entries current afterwards.`],wrong:[[`Replace write-through with lazy loading alone`,`With lazy loading alone the cache can return stale scores after a write, which breaks the no-old-scores rule.`],[`Run a job that loads every score from the database into each new node`,`This fills the node with all scores, including the many that are never read, and wastes cache resources.`],[`Remove the cache and read every score from the database`,`Every read would reach the database, which raises the database load and cost.`]],slot:1,evidence:[`elasticache-strategies|Missing data. If you spin up a new node, whether due to a node failure or scaling out, there is missing data.`,`elasticache-strategies|You can minimize this by implementing lazy loading with write-through.`,`elasticache-strategies|Data in the cache is never stale.`]}),t({id:`capacity-meter-014`,building:`capacity-meter`,bullets:[`4.3-K6`],d:2,tags:[`mock-reserve`],stem:`A company's application sends sudden bursts of new connections to an Amazon RDS for PostgreSQL DB instance. The company wants the database protected from being oversubscribed, with connection requests that cannot be served right away queued or throttled, and without moving to a larger DB instance class. Which solution meets these requirements?`,correct:[`Amazon RDS Proxy with a limit on the number of database connections it creates`,`The proxy controls the connections created and queues or throttles application connections that cannot be served right away, and it rejects requests that exceed the limits you set.`],wrong:[[`A Multi-AZ standby replica that takes the extra connections when the primary is full`,`A Multi-AZ DB instance deployment has one standby that provides failover support but does not serve read traffic, so it does not absorb connection bursts.`],[`A read replica that the application uses whenever the primary refuses a connection`,`A read replica is a read-only copy of the DB instance, so it does not manage connections to the primary, and the application would need custom code to use it.`],[`A larger DB instance class that holds more connections at all times`,`The DB instance class determines the computation and memory capacity of a DB instance, and the company wants to avoid moving to a larger class.`]],slot:2,evidence:[`rds-proxy|To protect a database against oversubscription, you can control the number of database connections that are created.`,`rds-proxy|RDS Proxy queues or throttles application connections that can't be served immediately from the connection pool.`,`rds-proxy|If connection requests exceed the limits you specify, RDS Proxy rejects application connections (that is, it sheds load).`,`rds-multi-az|A Multi-AZ DB instance deployment has one standby DB instance that provides failover support, but doesn't serve read traffic.`,`rds-read-replicas|A read replica is a read-only copy of a DB instance.`,`rds-instance-class|The DB instance class determines the computation and memory capacity of an Amazon RDS DB instance.`]})],a=[t({id:`cold-cellar-001`,building:`cold-cellar`,bullets:[`4.1-K10`,`4.1-S8`],d:1,tags:[`trap:s3-storage-classes`],stem:`A hospital must keep scanned patient records in Amazon S3 for ten years. The records are accessed less than once a year, and staff can wait a day or two for a record when one is needed. Which S3 storage class provides the LOWEST storage cost for these records?`,correct:[`S3 Glacier Deep Archive, which is designed for archive data accessed less than once a year`,`Deep Archive retrieval takes 9 to 48 hours, which the staff can accept, and it is the class designed for data accessed less than once a year.`],wrong:[[`S3 Glacier Flexible Retrieval, which is designed for archives accessed about once a year`,`It is built for retrieval in minutes to hours, a capability the hospital does not need; the class designed for data accessed less than once a year is Deep Archive.`],[`S3 Glacier Instant Retrieval, which is designed for archive data accessed once a quarter`,`It provides millisecond retrieval for data read about once a quarter, which the hospital does not need for records read less than once a year.`],[`S3 Standard-IA, which is designed for infrequently accessed data read about once a month`,`It is designed for data read about once a month with millisecond access, and records read less than once a year do not need that.`]],slot:2,evidence:[`s3-storage-classes|S3 Glacier Deep Archive (DEEP_ARCHIVE) Long-lived archive data accessed less than once a year with retrieval times of hours`,`s3-glacier-classes|S3 Glacier Instant Retrieval 90 days Quarterly Milliseconds No S3 Glacier Flexible Retrieval 90 days Semi-annually Minutes to 12 hours Yes S3 Glacier Deep Archive 180 days Annually 9 to 48 hours Yes`]}),t({id:`cold-cellar-002`,building:`cold-cellar`,bullets:[`4.1-S8`],d:2,tags:[`placement-eligible`,`trap:s3-storage-classes`],stem:`A photo-sharing website keeps user-uploaded images in Amazon S3 Standard. Some photos are viewed every day for months and others are never viewed again, and the company cannot predict which. The company wants lower storage cost with no retrieval fees and no age-based rules to maintain. Which solution is MOST cost-effective?`,correct:[`Store the images in S3 Intelligent-Tiering so that S3 moves each object between access tiers based on use`,`Intelligent-Tiering suits unknown or changing access patterns, moves unaccessed objects to cheaper tiers automatically, and has no retrieval fees.`],wrong:[[`Add a lifecycle rule that moves all images to S3 Standard-IA 30 days after upload and keeps them there`,`Standard-IA charges a per-GB retrieval fee, so photos that are still viewed daily would incur retrieval fees, which the company wants to avoid.`],[`Add a lifecycle rule that moves all images to S3 Glacier Flexible Retrieval 30 days after upload and keeps them there`,`Retrieval takes minutes to hours and requires a restore first, which does not suit photos that users may open at any time.`],[`Add a lifecycle rule that moves all images to S3 One Zone-IA 30 days after upload and keeps them there`,`It still charges retrieval fees, and it keeps the only copy of the photos in one Availability Zone that is not resilient to the loss of that zone.`]],slot:0,evidence:[`s3-storage-classes|S3 Intelligent-Tiering is the ideal storage class when you want to optimize storage costs for data that has unknown or changing access patterns.`,`s3-storage-classes|There are no retrieval fees for S3 Intelligent-Tiering.`]}),t({id:`cold-cellar-003`,building:`cold-cellar`,bullets:[`4.1-S8`],d:3,tags:[`placement-eligible`,`trap:s3-storage-classes`],stem:`An online store keeps a 400 KB thumbnail for every product image under the thumbs/ prefix of an Amazon S3 bucket. The thumbnails can be regenerated from the original images, which are stored separately, so losing them in a single Availability Zone failure is acceptable. After the first 30 days a thumbnail is requested about once a month, but each request must still be served in milliseconds. Which solution has the LOWEST storage cost and meets these requirements?`,correct:[`A lifecycle rule for the thumbs/ prefix that moves thumbnails to S3 One Zone-IA after 30 days`,`One Zone-IA gives millisecond access to recreatable, infrequently accessed data and is less expensive than Standard-IA because it keeps one copy in one Availability Zone.`],wrong:[[`A lifecycle rule for the thumbs/ prefix that moves thumbnails to S3 Standard-IA after 30 days`,`It also gives millisecond access, but it stores the data across several Availability Zones, a resilience the regenerable thumbnails do not need and One Zone-IA avoids paying for.`],[`A lifecycle rule for the thumbs/ prefix that moves thumbnails to S3 Glacier Flexible Retrieval after 30 days`,`Objects are archived and need a restore that takes minutes to hours, so requests could not be served in milliseconds.`],[`Store the thumbnails in S3 Intelligent-Tiering and let S3 pick the access tier for each object`,`Intelligent-Tiering is designed for unknown or changing access patterns and adds a per-object monitoring and automation fee, but this access pattern is known.`]],slot:1,evidence:[`s3-storage-classes|S3 One Zone-IA (ONEZONE_IA) Recreatable, infrequently accessed data (once a month) with millisecond access`,`s3-storage-classes|S3 One Zone-IA (ONEZONE_IA) – Amazon S3 stores the object data in only one Availability Zone, which makes it less expensive than S3 Standard-IA.`,`s3-storage-classes|For a small monthly object monitoring and automation fee, S3 Intelligent-Tiering monitors access patterns and automatically moves objects that have not been accessed to lower-cost access tiers.`,`s3-storage-classes|S3 Intelligent-Tiering is the ideal storage class when you want to optimize storage costs for data that has unknown or changing access patterns.`]}),t({id:`cold-cellar-004`,building:`cold-cellar`,bullets:[`4.1-K7`],d:1,stem:`A company stores monthly report files in an Amazon S3 bucket. The reports are rarely opened after 90 days, so the company wants them moved to a lower-cost storage class automatically, with the LEAST operational overhead and no custom code. Which solution meets these requirements?`,correct:[`Create an S3 Lifecycle rule that transitions objects to the cheaper class 90 days after creation`,`Transition actions define when objects move to another storage class, and S3 performs the move without code to run.`],wrong:[[`Configure S3 Replication to copy objects older than 90 days into a second bucket that uses the cheaper class`,`Replication copies new objects as they are written and does not age objects into another class, and the originals would stay in the first bucket.`],[`Run an AWS Lambda function on an Amazon EventBridge schedule to copy old reports into the cheaper class`,`This works, but the company would write and maintain the code, which conflicts with the requirement for no custom code and the least overhead.`],[`Enable S3 Storage Class Analysis on the bucket and move the objects by hand when it recommends a change`,`Storage Class Analysis only gives recommendations and does not move objects, so the company would still do the moving manually.`]],slot:3,evidence:[`s3-lifecycle|Transition actions – These actions define when objects transition to another storage class.`,`s3-analytics|Storage class analysis only provides recommendations for Standard to Standard IA classes.`]}),t({id:`cold-cellar-005`,building:`cold-cellar`,bullets:[`4.1-K7`,`4.1-S9`],d:3,tags:[`placement-eligible`,`trap:s3-storage-classes`],stem:`A company writes website access logs to the logs/ prefix of an Amazon S3 bucket. Analysts query the logs every day for the first 30 days. After that the logs are read about once a quarter for investigations that must return data in milliseconds. A policy requires the logs to be deleted after 400 days. Which lifecycle configuration meets these requirements MOST cost-effectively?`,correct:[`A rule for the logs/ prefix that transitions objects to S3 Glacier Instant Retrieval after 30 days and expires them after 400 days`,`Glacier Instant Retrieval is the class for archive data accessed once a quarter with millisecond access, and the expiration action deletes the logs on schedule.`],wrong:[[`A rule for the logs/ prefix that transitions objects to S3 Glacier Deep Archive after 30 days and expires them after 400 days`,`Deep Archive retrieval takes 9 to 48 hours, so investigations that need data in milliseconds could not be served.`],[`A rule for the logs/ prefix that transitions objects to S3 Standard-IA after 30 days and expires them after 400 days`,`It meets the retrieval need, but Standard-IA is designed for data read about once a month, while quarterly reads match Glacier Instant Retrieval.`],[`A rule for the logs/ prefix that transitions objects to S3 Intelligent-Tiering on day 0, with no expiration action`,`Nothing in the rule deletes the logs after 400 days, so the deletion policy would have to be met by another manual process.`]],slot:2,evidence:[`s3-storage-classes|S3 Glacier Instant Retrieval (GLACIER_IR) Long-lived, archive data accessed once a quarter with millisecond access`,`s3-lifecycle|Expiration actions – These actions define when objects expire. Amazon S3 deletes expired objects on your behalf.`,`s3-glacier-classes|S3 Glacier Instant Retrieval 90 days Quarterly Milliseconds No S3 Glacier Flexible Retrieval 90 days Semi-annually Minutes to 12 hours Yes S3 Glacier Deep Archive 180 days Annually 9 to 48 hours Yes`]}),t({id:`cold-cellar-006`,building:`cold-cellar`,bullets:[`4.1-K10`,`4.1-S9`],d:2,tags:[`placement-eligible`,`trap:s3-storage-classes`],stem:`A data team writes daily export files to the exports/ prefix of an Amazon S3 bucket. The files are read heavily for three days and are deleted 10 days after creation. An engineer proposes a lifecycle transition to a colder storage class on day 3 to save cost. Which approach is MOST cost-effective?`,correct:[`Keep the files in S3 Standard and use an expiration action at day 10`,`The colder classes charge for a minimum storage duration when an object is deleted early, so a short-lived object is cheapest left in Standard.`],wrong:[[`Transition the files to S3 Standard-IA on day 3 and expire them on day 10`,`Deleting an object before the end of the 30-day minimum storage duration is charged as 30 days, so the early deletion erases the savings.`],[`Transition the files to S3 Glacier Instant Retrieval on day 3 and expire them on day 10`,`This class has a 90-day minimum storage duration, so deleting at day 10 is charged for the full minimum period.`],[`Transition the files to S3 Glacier Deep Archive on day 3 and expire them on day 10`,`This class has a 180-day minimum storage duration, so deleting at day 10 is charged for the full minimum period.`]],slot:1,evidence:[`s3-storage-classes|If you delete an object before the end of the 30-day minimum storage duration period, you are charged for 30 days.`,`s3-glacier-classes|If you delete, overwrite, or transition the object to a different storage class before the minimum, you are charged for the remainder of that duration.`,`s3-storage-classes|S3 Glacier Instant Retrieval (GLACIER_IR) Long-lived, archive data accessed once a quarter with millisecond access 99.999999999% 99.9% >= 3 90 days 128 KB`]}),t({id:`cold-cellar-007`,building:`cold-cellar`,bullets:[`4.1-S5`],d:2,tags:[`placement-eligible`],stem:`A company hosts a static website from an Amazon S3 bucket that has S3 Versioning enabled. Each deployment overwrites the site files, and the company needs previous versions for only 14 days to allow a rollback. Older noncurrent versions keep accumulating. Which lifecycle configuration solves this with the LEAST operational overhead?`,correct:[`A rule with a NoncurrentVersionExpiration action set to 14 days`,`The noncurrent-version expiration action is the lifecycle action that permanently deletes noncurrent versions, and the live site files are not touched.`],wrong:[[`A rule with an Expiration action that deletes objects 14 days after they are created`,`Expiration applies only to the current version and, in a versioned bucket, adds a delete marker, which would take the live site files down.`],[`A rule with an AbortIncompleteMultipartUpload action set to 14 days`,`It only cleans up multipart uploads that never completed and has no effect on the noncurrent versions of completed deployments.`],[`S3 Storage Class Analysis on the bucket, with the old versions removed by hand after each report`,`It only provides recommendations for moving data from Standard to Standard-IA and does not delete anything, so cleanup stays manual.`]],slot:3,evidence:[`s3-lifecycle-rules|NoncurrentVersionExpiration action element – Use this action to direct Amazon S3 to permanently delete noncurrent versions of objects.`,`s3-lifecycle-rules|The Expiration action applies only to the current version (it has no impact on noncurrent object versions).`,`s3-lifecycle-expire|Versioning-enabled bucket – If the current object version is not a delete marker, Amazon S3 adds a delete marker with a unique version ID.`]}),t({id:`cold-cellar-008`,building:`cold-cellar`,bullets:[`4.1-S5`],d:2,tags:[`placement-eligible`],stem:`Mobile users upload large video files to an Amazon S3 bucket by using multipart upload. Many uploads are abandoned part way, and the bucket bill keeps growing from parts of uploads that never completed. The company wants to stop this cost with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`An S3 Lifecycle rule with an AbortIncompleteMultipartUpload action set to 7 days`,`The abort action sets a maximum number of days that multipart uploads may remain in progress, and AWS recommends it to minimize storage costs.`],wrong:[[`An S3 Lifecycle rule with an expiration action that deletes objects 7 days after creation`,`Object expiration lifecycle configurations do not remove incomplete multipart uploads, and it would also delete finished videos.`],[`An AWS Lambda function on an Amazon EventBridge schedule that lists and aborts old multipart uploads`,`This can work, but it adds code to write and maintain, while the built-in lifecycle action does the same with no code.`],[`S3 Storage Class Analysis on the bucket, filtered to the prefix that receives the uploads`,`It only gives recommendations for moving objects from Standard to Standard-IA and does not remove incomplete uploads.`]],slot:0,evidence:[`s3-lifecycle-rules|AbortIncompleteMultipartUpload action element – Use this element to set a maximum time (in days) that you want to allow multipart uploads to remain in progress.`,`s3-lifecycle-rules|Object expiration lifecycle configurations don't remove incomplete multipart uploads.`,`s3-mpu-abort|As a best practice, we recommend that you configure a lifecycle rule by using the AbortIncompleteMultipartUpload action to minimize your storage costs.`]}),e({id:`cold-cellar-009`,building:`cold-cellar`,bullets:[`4.1-K7`,`4.1-S5`],d:2,tags:[`placement-eligible`,`trap:s3-storage-classes`],stem:`A company keeps financial records under the records/ prefix of an Amazon S3 bucket. The records are used often for 60 days, then read about once a year, and a restore time of a few hours is acceptable. They must be kept seven years and then deleted automatically. Which TWO lifecycle actions in one rule for the records/ prefix meet these requirements MOST cost-effectively? (Choose two.)`,correct:[[`A transition action that moves the records to S3 Glacier Flexible Retrieval 60 days after creation`,`Glacier Flexible Retrieval is designed for archive data accessed once a year with retrieval in minutes to hours.`],[`An expiration action that deletes the records seven years after creation`,`The expiration action makes S3 delete the records on the company's behalf when the retention period ends.`]],wrong:[[`A transition action that moves the records to S3 One Zone-IA 60 days after creation`,`One Zone-IA keeps data in a single Availability Zone, which is risky for the only copy of financial records, and it targets data read about monthly.`],[`A NoncurrentVersionExpiration action that deletes noncurrent versions after seven years`,`It affects only noncurrent versions, so current records would never be deleted at the end of the retention period.`],[`A transition action that moves the records to S3 Glacier Instant Retrieval 60 days after creation`,`It provides millisecond retrieval for data read about once a quarter, a capability the company does not need for records read once a year.`]],slots:[0,3],evidence:[`s3-storage-classes|S3 Glacier Flexible Retrieval (GLACIER) Long-lived archive data accessed once a year with retrieval times of minutes to hours`,`s3-lifecycle|Expiration actions – These actions define when objects expire. Amazon S3 deletes expired objects on your behalf.`,`s3-lifecycle-rules|The Expiration action applies only to the current version (it has no impact on noncurrent object versions).`]}),t({id:`cold-cellar-010`,postGuide:[`s3-lifecycle-default-min-size`],postGuideKey:[`s3-lifecycle-default-min-size`],building:`cold-cellar`,bullets:[`4.1-K10`,`4.1-S8`],d:3,tags:[`placement-eligible`,`trap:s3-storage-classes`],stem:`An Amazon S3 bucket holds 6 million event files of about 12 KB each and a set of 200 MB report archives. A lifecycle rule moves every object to S3 Standard-IA after 30 days. Weeks later the archives are in Standard-IA, but every 12 KB event file is still in S3 Standard and no error was reported. The company wants lower storage cost for the event data without paying transition request charges that exceed the savings. Which solution is the MOST cost-effective?`,correct:[`Combine the event files into larger objects before storing them, and let the lifecycle rule transition the larger objects`,`By default, lifecycle does not transition objects smaller than 128 KB, and aggregating many small objects into fewer large ones reduces overhead costs.`],wrong:[[`Change the lifecycle rule so that it moves the event files to S3 Glacier Flexible Retrieval instead`,`The default behavior prevents objects smaller than 128 KB from being transitioned to any storage class, so the files would still stay in S3 Standard.`],[`Add an object size filter that allows the 12 KB files to be transitioned, and keep the 6 million files as separate objects`,`A transition request is charged for each object, so 6 million transitions can exceed the savings, and transitioning objects under 128 KB is not recommended.`],[`Upload the event files directly to S3 Intelligent-Tiering so that S3 moves them to the cheaper access tiers`,`Objects smaller than 128 KB are not monitored and are not eligible for auto-tiering, so the files would not reach the cheaper tiers.`]],slot:2,evidence:[`s3-lifecycle-transitions|Amazon S3 applies a default behavior to S3 Lifecycle configurations that prevents objects smaller than 128 KB from being transitioned to any storage class.`,`s3-lifecycle-transitions|Also consider aggregating many small objects into a smaller number of large objects to reduce overhead costs.`,`s3-lifecycle-transitions|We don't recommend transitioning objects less than 128 KB because you are charged a transition request for each object.`,`s3-storage-classes|If the size of an object is less than 128 KB, it is not monitored and not eligible for auto-tiering.`]}),t({id:`cold-cellar-011`,building:`cold-cellar`,bullets:[`4.1-S9`],d:2,stem:`A company stores 50 TB of user documents in S3 Standard under many prefixes. Nobody knows how old the documents under each prefix are when they stop being read. Before writing a lifecycle rule that moves data to S3 Standard-IA, the company wants a data-driven recommendation for the prefixes. Which solution meets this requirement?`,correct:[`Enable Amazon S3 Storage Class Analysis with a filter for each prefix and review its report`,`Storage Class Analysis analyzes storage access patterns to help decide when to move Standard data to Standard-IA, and it can filter by prefix.`],wrong:[[`Use AWS Cost Explorer to group the bucket cost by prefix and read the access age from the chart`,`Cost Explorer reports spend and does not analyze how often objects under a prefix are read, so it gives no age recommendation.`],[`Create an AWS Budgets budget on the bucket and review the alerts that it sends`,`A budget alerts when cost passes a threshold and does not analyze the access patterns of objects.`],[`Move all documents to S3 Intelligent-Tiering and wait for it to adjust the tiers`,`It tiers objects automatically and does not produce an age recommendation, so the company would not learn what rule to write.`]],slot:1,evidence:[`s3-storage-classes|To help you optimize costs between S3 Standard and S3 Standard-IA you can use Amazon S3 analytics – Storage Class Analysis.`,`s3-analytics|Or, you can configure filters to group objects together for analysis by common prefix (that is, objects that have names that begin with a common string), by object tags, or by both prefix and tags.`]}),t({id:`cold-cellar-012`,building:`cold-cellar`,bullets:[`4.1-S8`],d:2,tags:[`mock-reserve`,`trap:s3-storage-classes`],stem:`A company uses S3 Cross-Region Replication to keep a second copy of its documents in another Region. The replica copies are rarely read, must answer in milliseconds if they are ever needed, and can be re-created from the source bucket. Which storage class for the replica copies has the LOWEST cost and meets these requirements?`,correct:[`S3 One Zone-IA, which is used for object replicas when configuring Cross-Region Replication`,`Replicas can be re-created from the source, so a single Availability Zone is acceptable, and One Zone-IA is less expensive than Standard-IA.`],wrong:[[`S3 Standard-IA, which is recommended for the primary or only copy of data that cannot be re-created`,`It stores the data across several Availability Zones, a resilience that replicas that can be re-created do not need.`],[`S3 Glacier Flexible Retrieval, which is designed for archives retrieved in minutes to hours`,`Replicas must answer in milliseconds, and archived objects must be restored first, which takes minutes to hours.`],[`S3 Glacier Deep Archive, which is designed for data accessed less than once a year`,`Retrieval takes 9 to 48 hours, which fails the millisecond requirement for a replica that may be needed.`]],slot:0,evidence:[`s3-storage-classes|S3 One Zone-IA (ONEZONE_IA) – Use if you can re-create the data if the Availability Zone fails, for object replicas when configuring S3 Cross-Region Replication (CRR).`,`s3-storage-classes|S3 Standard-IA (STANDARD_IA) – Use for your primary or only copy of data that can't be re-created.`]}),t({id:`cold-cellar-013`,building:`cold-cellar`,bullets:[`4.1-S5`],d:3,tags:[`mock-reserve`],stem:`A company stores project files in one Amazon S3 bucket, and the files have no common key prefix. Only objects that teams tag with archive set to true must move to S3 Glacier Flexible Retrieval 90 days after creation. All other objects must stay in S3 Standard. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`One lifecycle rule with a tag filter for archive=true and a 90-day transition action`,`A lifecycle filter can select objects by one or more object tags, so only tagged objects are transitioned.`],wrong:[[`One lifecycle rule with a key prefix filter that matches the project name and a 90-day transition action`,`The files have no common prefix, so a prefix filter cannot select the tagged objects.`],[`One lifecycle rule with no filter and a 90-day transition action, with untagged objects copied back by hand`,`A rule without a filter applies to all objects, so untagged objects would be moved and need manual correction.`],[`One lifecycle rule with a filter on the tag archive and a 90-day AbortIncompleteMultipartUpload action`,`That action only cleans up multipart uploads in progress and does not move completed objects to Glacier Flexible Retrieval.`]],slot:3,evidence:[`s3-lifecycle-rules|You can specify a filter by using the object size, the object key prefix, one or more object tags, or a combination of filters.`,`s3-lifecycle-rules|A filter that identifies the objects to which the rule applies.`]})],o=[t({id:`counting-house-001`,building:`counting-house`,bullets:[`4.2-K1`],d:1,stem:`A company runs production, test and analytics workloads in three separate standalone AWS accounts. Compute usage in the three accounts is steady, and the company wants one Savings Plans commitment whose discount applies to the usage in all three accounts, without moving any workload. Which solution meets this requirement with the LEAST effort?`,correct:[`Add the three accounts to one AWS Organizations organization and buy the plan in one of them`,`Consolidated billing combines usage across the accounts of the organization and shares Savings Plans discounts among them.`],wrong:[[`Buy a separate Savings Plan in each of the three accounts and size each one for its own account`,`Each plan covers only the usage of its own account, so a plan that is larger than its account's usage leaves part of the commitment unused.`],[`Create IAM roles that let the three accounts use the account that holds the Savings Plan`,`Roles grant access to resources and do not share a billing discount between accounts.`],[`Apply the same cost allocation tags to the instances in all three accounts`,`Cost allocation tags categorize and report costs and do not move a discount from one account to another.`]],slot:1,evidence:[`consolidated-billing|This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`,`cost-alloc-tags|After you activate cost allocation tags, AWS uses the cost allocation tags to organize your resource costs on your cost allocation report, to make it easier for you to categorize and track your AWS costs.`]}),t({id:`counting-house-002`,building:`counting-house`,bullets:[`4.2-K1`],d:3,stem:`A company has already activated its user-defined Team tag for cost allocation. For Amazon EC2 instances that are launched from now on in the US East (N. Virginia) Region (us-east-1), finance also wants Cost Explorer to show the cost grouped by who created each instance, and it does not want people to type this information on each instance. Which action meets this requirement with the LEAST operational overhead?`,correct:[`Activate the AWS-generated createdBy cost allocation tag in the billing console`,`The createdBy tag is applied by AWS and tracks who created a resource, and it must be activated separately from user-defined tags.`],wrong:[[`Ask each engineer to add a user-defined Owner tag with their name to every new instance`,`This relies on people typing the value on each instance, which the company wants to avoid, and untagged instances would be missed.`],[`Group the costs by the Service dimension in Cost Explorer`,`It breaks costs down by AWS service, and it carries no information about who created an instance.`],[`Enable consolidated billing for the accounts in AWS Organizations`,`Consolidated billing combines usage and shares discounts, and it does not record who created a resource.`]],slot:0,evidence:[`cost-alloc-tags|You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`,`cost-alloc-tags|The createdBy tag tracks who created the resource.`,`aws-generated-tags|The AWS-generated tag createdBy is a tag that AWS defines and applies to supported AWS resources for cost allocation purposes.`]}),t({id:`counting-house-003`,building:`counting-house`,bullets:[`4.2-K2`],d:1,stem:`A company has run on Amazon EC2 On-Demand Instances for a year and wants to buy a Savings Plan. The finance team wants a recommendation for the hourly commitment, based on the company's own historical usage, with the LEAST effort. Which solution meets these requirements?`,correct:[`Use AWS Cost Explorer to view the recommended Savings Plans commitment`,`Cost Explorer shows recommended Savings Plans commitments and the historical usage that they are based on, and the plan can be purchased from it.`],wrong:[[`Create an AWS Budgets Savings Plans coverage budget`,`A budget tracks utilization and coverage of plans that already exist and does not recommend a commitment to buy.`],[`Publish an AWS Cost and Usage Report to Amazon S3 and calculate the commitment by hand`,`The report holds the most detailed usage data, but the finance team would compute the recommendation itself.`],[`Activate cost allocation tags on every instance and read the tag report`,`Tags categorize costs by label and do not produce a recommended commitment.`]],slot:3,evidence:[`savings-plans|To get started, use AWS Cost Explorer to view your recommended Savings Plans commitment, refresh Savings Plans recommendations, purchase Savings Plans, manage your Savings Plans, and view your historical AWS usage.`,`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`]}),t({id:`counting-house-004`,building:`counting-house`,bullets:[`4.2-K2`],d:2,stem:`A company bought Compute Savings Plans for its steady workloads. Some workloads were later moved to a different service, and the company wants to be notified automatically when the share of its commitment that is actually used falls too low. Which solution meets this requirement with the LEAST operational overhead?`,correct:[`Create an AWS Budgets budget that monitors Savings Plans utilization and sends an alert`,`AWS Budgets can monitor aggregate utilization and coverage metrics for Savings Plans and alert when they cross the threshold set.`],wrong:[[`Check the Savings Plans recommendations in AWS Cost Explorer each month`,`Recommendations show what additional commitment to buy and do not notify anyone when utilization of an existing plan drops.`],[`Turn on cost allocation tags for the workloads that moved`,`Tags categorize costs and do not measure how much of a commitment is used.`],[`Deliver the Cost and Usage Report to Amazon S3 and have an analyst query it every week`,`The report holds detailed data, but the weekly query is manual and does not send a notification.`]],slot:1,evidence:[`budgets-managing|You can use AWS Budgets to monitor your aggregate utilization and coverage metrics for your Reserved Instances (RIs) or Savings Plans.`,`savings-plans|To get started, use AWS Cost Explorer to view your recommended Savings Plans commitment, refresh Savings Plans recommendations, purchase Savings Plans, manage your Savings Plans, and view your historical AWS usage.`]}),t({id:`counting-house-005`,building:`counting-house`,bullets:[`4.2-K1`,`4.2-K4`],d:3,tags:[`trap:savings-plans-ri-spot`],stem:`A company has six AWS accounts in one AWS Organizations organization. Over the next year it will move some steady Amazon EC2 workloads to other instance families and shift some containers to AWS Fargate. It wants one one-year commitment that discounts the usage of all six accounts with the GREATEST flexibility. Which solution meets these requirements?`,correct:[`Buy a Compute Savings Plan in the management account`,`Compute Savings Plans apply regardless of instance family and also to Fargate usage, and consolidated billing shares the plan across the accounts.`],wrong:[[`Buy an EC2 Instance Savings Plan for the current instance family in the management account`,`It commits to a specific instance family in one Region and does not cover the Fargate usage or a move to another family.`],[`Buy Standard Reserved Instances for the current instance configurations in each account`,`Reserved Instances commit to a consistent instance configuration, cannot be exchanged, and do not apply to Fargate.`],[`Run all the steady workloads on Spot Instances in each account`,`Spot capacity can be interrupted, so it is not a commitment and does not suit steady production workloads.`]],slot:2,evidence:[`savings-plans-types|They also apply to your Fargate and Lambda usage.`,`savings-plans-types|With Compute Savings Plans, you can move a workload from c5 to m5, shift your usage from EU (Ireland) to EU (London), or migrate your application from Amazon EC2 to Amazon ECS using Fargate at any time.`,`consolidated-billing|This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`]}),e({id:`counting-house-006`,building:`counting-house`,bullets:[`4.2-K4`],d:2,tags:[`trap:savings-plans-ri-spot`],stem:`A company renders video in a nightly batch job made of thousands of independent tasks. Each task takes about ten minutes, writes its result to Amazon S3, and can be run again without harm. The company wants to run the workers at the LOWEST cost. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Run the worker instances as Amazon EC2 Spot Instances`,`Spot Instances use spare capacity at less than the On-Demand price and suit applications that are flexible about timing and can be interrupted.`],[`Return unfinished tasks to the work queue when the two-minute Spot interruption notice arrives`,`The notice warns two minutes before EC2 stops or terminates the instance, so an interrupted task can be run again elsewhere.`]],wrong:[[`Buy three-year Standard Reserved Instances for the worker fleet`,`Reserved Instances involve making a commitment to a consistent instance configuration, including instance type and Region, for a term of 1 or 3 years, and the stem describes a nightly batch of restartable tasks, not a steady workload.`],[`Run the workers on Dedicated Hosts`,`Dedicated Hosts pay for a physical host that is fully dedicated to your instances and bring per-socket or per-core licenses, which the job does not need.`],[`Reserve the worker capacity with an On-Demand Capacity Reservation in one Availability Zone`,`Capacity Reservations are charged at the On-Demand rate whether or not instances run in them, which does not lower the cost.`]],slots:[0,3],evidence:[`ec2-spot|Spot Instances are a cost-effective choice if you can be flexible about when your applications run and if your applications can be interrupted.`,`ec2-spot-notices|A Spot Instance interruption notice is a warning that is issued two minutes before Amazon EC2 stops or terminates your Spot Instance.`,`ec2-capacity-reservation-billing|Capacity Reservations are charged at the equivalent On-Demand rate whether you run instances in reserved capacity or not, including any applicable regional surcharge for Dedicated Instances.`,`ec2-purchasing|making a commitment to a consistent instance configuration, including instance type and Region, for a term of 1 or 3 years.`,`ec2-purchasing|Pay for a physical host that is fully dedicated to running your instances, and bring your existing per-socket, per-core, or per-VM software licenses to reduce costs.`]}),t({id:`counting-house-007`,building:`counting-house`,bullets:[`4.2-K4`],d:2,tags:[`trap:savings-plans-ri-spot`],stem:`A retailer expects a two-week sales event and must be sure that a fixed number of Amazon EC2 instances can be launched in one specific Availability Zone during it. The company does not want a one-year or three-year commitment. Which purchasing option meets these requirements?`,correct:[`An On-Demand Capacity Reservation in that Availability Zone, cancelled after the event`,`A Capacity Reservation reserves capacity in a specific Availability Zone for any duration, with no term commitment, and can be cancelled at any time.`],wrong:[[`A regional Reserved Instance for the instance type`,`A regional Reserved Instance does not reserve capacity, and it carries a term of one or three years.`],[`A Compute Savings Plan sized for the event usage`,`Savings Plans do not provide capacity reservations, and the plan carries a commitment of one or three years.`],[`A zonal Reserved Instance in that Availability Zone with a one-year term and partial upfront payment`,`It reserves capacity in the Availability Zone, but it carries a one-year commitment that the company does not want for a two-week need.`]],slot:0,evidence:[`ec2-capacity-reservations|Amazon EC2 Capacity Reservations allow you to reserve compute capacity for your Amazon EC2 instances in a specific Availability Zone for any duration.`,`ec2-capacity-reservations|If you request a Capacity Reservation for immediate use, the Capacity Reservation becomes available for use immediately and there is no term commitment.`,`ec2-ri-scope|A regional Reserved Instance does not reserve capacity.`,`savings-plans-vs-ri|Savings Plans doesn't provide capacity reservations, but you can allocate On-Demand Capacity Reservation (ODCR) for your needs and your Savings Plans will apply.`]}),e({id:`counting-house-008`,building:`counting-house`,bullets:[`4.2-K2`,`4.2-K4`],d:2,tags:[`trap:savings-plans-ri-spot`],stem:`A company wants to cover its steady Amazon EC2 usage with Savings Plans. It wants to size the first purchase from its own usage history, and after the purchase it wants to track what share of its usage the plans cover. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Use AWS Cost Explorer to view the recommended Savings Plans commitment before purchasing`,`Cost Explorer shows your recommended Savings Plans commitment, which you can customize before you purchase your Savings Plan, and lets you view your historical AWS usage.`],[`Create an AWS Budgets coverage budget for Savings Plans`,`AWS Budgets monitors aggregate utilization and coverage metrics for Savings Plans.`]],wrong:[[`Activate cost allocation tags on the instances and review the tag report`,`Cost allocation tags only organize costs by label on the cost allocation report, so they do not recommend a commitment or measure coverage.`],[`Use consolidated billing in AWS Organizations as the way to measure coverage`,`Under consolidated billing the management account might reallocate discounts such as Savings Plans discounts, and it is not a coverage report or a recommendation.`],[`Query the Cost and Usage Report in Amazon S3 by hand to decide and to track coverage`,`The report contains the most comprehensive set of cost and usage data, but doing both jobs by hand is more operational work than the two managed tools.`]],slots:[1,4],evidence:[`savings-plans|To get started, use AWS Cost Explorer to view your recommended Savings Plans commitment, refresh Savings Plans recommendations, purchase Savings Plans, manage your Savings Plans, and view your historical AWS usage.`,`savings-plans|You can customize the recommendation to meet your needs and then purchase your Savings Plan.`,`budgets-managing|You can use AWS Budgets to monitor your aggregate utilization and coverage metrics for your Reserved Instances (RIs) or Savings Plans.`,`cost-alloc-tags|After you activate cost allocation tags, AWS uses the cost allocation tags to organize your resource costs on your cost allocation report, to make it easier for you to categorize and track your AWS costs.`,`consolidated-billing|The management account might reallocate the additional volume discounts, Reserved Instance, or Savings Plans discounts that your account receives.`,`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`]}),t({id:`counting-house-009`,building:`counting-house`,bullets:[`4.2-K4`],d:2,tags:[`mock-reserve`,`trap:savings-plans-ri-spot`],stem:`A company must run a database engine that is licensed per socket, and it wants to bring its existing licenses to AWS to reduce the cost of running it on Amazon EC2. Which EC2 purchasing option BEST meets this requirement?`,correct:[`Dedicated Hosts, which accept existing per-socket and per-core software licenses`,`A Dedicated Host is a physical host fully dedicated to the company's instances, and existing per-socket licenses can be used on it.`],wrong:[[`Spot Instances spread across a large pool of instance types and Availability Zones`,`Spot Instances use spare capacity and can be interrupted, and they do not provide a dedicated physical host for per-socket licenses.`],[`Compute Savings Plans with a three-year term and all upfront payment`,`Savings Plans commit to a usage amount and do not give the company a physical host to which socket-based licenses apply.`],[`On-Demand Capacity Reservations in one Availability Zone for the full length of the project`,`Capacity Reservations reserve capacity and give no billing discount, and they do not give the company a dedicated physical host.`]],slot:3,evidence:[`ec2-purchasing|Dedicated Hosts – Pay for a physical host that is fully dedicated to running your instances, and bring your existing per-socket, per-core, or per-VM software licenses to reduce costs.`,`ec2-capacity-reservations|No billing discount.`]})],s=[t({id:`db-cost-desk-001`,building:`db-cost-desk`,bullets:[`4.3-K1`],d:2,stem:`A company tags each Amazon RDS DB instance with a Team tag and has activated Team as a cost allocation tag. Finance cannot assign the storage cost of manual DB snapshots to teams because the snapshots carry no tags. The company wants every new snapshot to carry its source DB instance tags with the LEAST ongoing effort. Which solution meets this requirement?`,correct:[`Turn on copying of tags to snapshots for each DB instance`,`Tags on a DB instance are then copied to its snapshots, so the snapshots appear under the Team tag in cost reports without manual steps.`],wrong:[[`Add the Team tag to each snapshot by hand after the snapshot is created`,`Every new snapshot would need a manual step, which is not the least ongoing effort.`],[`Create a Cost and Usage Report and group the snapshot line items by the Team tag`,`A report can group by tags only where tags exist, and the snapshots still carry none.`],[`Create an AWS Budgets cost budget for each team that covers all of its DB instance hours`,`A budget alerts on spend and does not assign untagged snapshot storage to teams.`]],slot:0,evidence:[`rds-tagging|When you create or restore a DB instance, you can specify that the tags from the DB instance are copied to snapshots of the DB instance.`,`rds-tagging|You can also use these tags to track costs by grouping expenses for similarly tagged resources.`,`cost-alloc-tags|You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`]}),t({id:`db-cost-desk-002`,building:`db-cost-desk`,bullets:[`4.3-K1`],d:1,stem:`A company runs databases in four AWS accounts that are billed separately. Reserved DB instances bought in one account are only partly used there, while the other accounts run matching DB instances at on-demand rates. The company wants one bill and wants the unused discount to benefit the other accounts, with the LEAST effort. Which solution meets these requirements?`,correct:[`Join the accounts to one organization in AWS Organizations and use consolidated billing`,`Consolidated billing combines usage across the accounts and shares Reserved Instance discounts, and the management account pays one bill.`],wrong:[[`Buy matching reserved DB instances in each of the three other accounts so that every account has its own reservation`,`The company would pay for extra reservations while the existing discount stays partly unused.`],[`Create a Cost and Usage Report in each account and share the reports with finance`,`Reports describe cost and usage but do not move discounts between accounts or merge the bills.`],[`Create an AWS Budgets reservation budget in each of the four accounts`,`A budget monitors utilization and alerts, but it does not share discounts or combine the bills.`]],slot:1,evidence:[`consolidated-billing|Every organization in AWS Organizations has a management account that pays the charges of all the member accounts.`,`consolidated-billing|Combined usage – You can combine the usage across all accounts in the organization.`,`consolidated-billing|This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`]}),t({id:`db-cost-desk-003`,building:`db-cost-desk`,bullets:[`4.3-K2`],d:1,stem:`A finance lead wants to see how spending on Amazon RDS and Amazon Aurora changed month by month over the past year, in a graph, and wants a forecast for the coming months. The lead does not want to build any data pipeline. Which AWS tool meets these requirements with the LEAST effort?`,correct:[`AWS Cost Explorer filtered to the database services`,`Cost Explorer lets you view and analyze costs and usage for up to the last 13 months and forecast future spend without extra setup.`],wrong:[[`AWS Cost and Usage Report delivered to an Amazon S3 bucket and queried with Amazon Athena`,`This needs a delivery, queries and a charting step to build, which is far more effort than an existing graphing tool.`],[`AWS Budgets with a monthly cost budget and alert thresholds`,`Budgets alerts when spending approaches a limit and is not a month-by-month graph of the past year.`],[`AWS Organizations with consolidated billing turned on for all accounts`,`Consolidated billing combines charges and shares discounts but does not itself graph or forecast costs.`]],slot:2,evidence:[`ce-what-is|AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`,`ce-what-is|You can view data for up to the last 13 months, forecast how much you're likely to spend for the next 18 months, and get recommendations for what Reserved Instances to purchase.`]}),t({id:`db-cost-desk-004`,building:`db-cost-desk`,bullets:[`4.3-K2`],d:3,stem:`A finance engineer must load Amazon RDS cost data into the company's own reporting tool each day. The data must be broken down by the hour, by individual database resource, and by a Project tag, and it must land in an Amazon S3 bucket that the company owns so that the tool can process it automatically. Which AWS tool meets these requirements?`,correct:[`AWS Cost and Usage Report delivered to the S3 bucket`,`The report holds the most comprehensive cost and usage data, publishes to a bucket the company owns, and breaks costs down by hour, by product resource and by tags.`],wrong:[[`AWS Cost Explorer with filters for Amazon RDS and a grouping by the Project tag`,`Cost Explorer is for viewing and analyzing costs in the console, and it does not deliver files to a bucket for another tool to process.`],[`AWS Budgets with a cost budget that is filtered to the Project tag`,`A budget tracks spend against a limit and alerts, and it does not deliver hourly resource-level data to a bucket.`],[`AWS Organizations consolidated billing with a member account for each project`,`Consolidated billing combines charges for the accounts and does not produce hourly, resource-level files in a bucket.`]],slot:3,evidence:[`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`,`cur-what-is|You can use Cost and Usage Reports to publish your AWS billing reports to an Amazon Simple Storage Service (Amazon S3) bucket that you own.`,`cur-what-is|You can receive reports that break down your costs by the hour, day, or month, by product or product resource, or by tags that you define yourself.`]}),t({id:`db-cost-desk-005`,building:`db-cost-desk`,bullets:[`4.3-K2`],d:3,tags:[`trap:savings-plans-ri-spot`],stem:`A company runs steady production databases on Amazon RDS for Oracle. The company expects to keep the same DB engine, DB instance class and Region for the next three years. It wants to commit to this database usage to lower its bill. Which commitment is the MOST cost-effective?`,correct:[`Reserved DB instances for the current RDS for Oracle instance type, with a three-year term`,`A reserved DB instance is a billing discount applied to matching on-demand DB instance usage, and the steady usage on a fixed engine, class and Region matches it.`],wrong:[[`Compute Savings Plans`,`Compute Savings Plans apply to Amazon EC2, AWS Fargate and AWS Lambda usage, not to Amazon RDS DB instances.`],[`Spot Instances for the DB instances`,`Spot capacity can be interrupted, and production databases that must stay available cannot run on interruptible capacity.`],[`No commitment, with On-Demand pricing and an AWS Budgets alert on database spend`,`The steady database usage would stay at On-Demand rates, and a budget only warns about spend and does not lower it.`]],slot:0,evidence:[`rds-reserved|Reserved DB instances provide you with a significant discount compared to on-demand DB instance pricing.`,`rds-reserved|Reserved DB instances are not physical instances, but rather a billing discount applied to the use of certain on-demand DB instances in your account.`,`savings-plans-types|They also apply to your Fargate and Lambda usage.`]}),e({id:`db-cost-desk-006`,building:`db-cost-desk`,bullets:[`4.3-K1`,`4.3-K2`],d:3,stem:`A company has 12 AWS accounts in one organization in AWS Organizations. Each team runs Amazon RDS and Amazon Aurora databases in its own account and puts a Team tag on them. Finance wants one view of database spend per team across all accounts, with the LEAST manual work. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Activate the Team tag as a cost allocation tag`,`A tag must be activated before it can appear in Cost Explorer or on a cost allocation report.`],[`Use Cost Explorer in the management account, filter to the database services, and group by the Team tag`,`Consolidated billing lets the management account track charges across the accounts, and Cost Explorer can filter and group by a tag.`]],wrong:[[`Create a Cost and Usage Report in every member account and merge the files by hand each month`,`The merging is manual work, which the company wants to minimize.`],[`Ask each team to compile its database spend into a spreadsheet at the end of each month`,`This relies on manual work by twelve teams instead of tags and a cost tool.`],[`Create a Reserved Instance utilization budget in each member account`,`A utilization budget monitors how well a reservation is used and does not show spend per team.`]],slots:[0,3],evidence:[`cost-alloc-tags|You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`,`consolidated-billing|Easy tracking – You can track the charges across multiple accounts and download the combined cost and usage data.`,`ce-filtering|Tag A label that you can use to track the costs associated with specific areas or entities within your business.`]}),e({id:`db-cost-desk-007`,building:`db-cost-desk`,bullets:[`4.3-K2`],d:2,stem:`A company wants two automatic protections for its database spending. First, an email when the forecast spend on Amazon RDS for the month is going to pass a set limit. Second, a daily check of how much of its usage its Savings Plans cover, with an alert when coverage drops below a target. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create an AWS Budgets cost budget filtered to Amazon RDS with an alert on forecasted spend`,`AWS Budgets can alert on forecasted spend before it accrues, so the team hears about a likely overrun in advance.`],[`Create an AWS Budgets Savings Plans coverage budget with a daily period and an alert threshold`,`AWS Budgets can monitor the coverage of Savings Plans with a daily coverage budget that sends an alert when coverage drops below the target.`]],wrong:[[`Review an AWS Cost Explorer report every morning to look for changes`,`This is a manual daily review, not an automatic alert.`],[`Create a Cost and Usage Report and review the delivered files once a week`,`The files are raw data that no one is alerted about, and a weekly review is not a daily check.`],[`Create an AWS Budgets usage budget for Amazon EC2 instance hours`,`EC2 usage is not database spend or Savings Plans coverage of databases.`]],slots:[2,4],evidence:[`budgets-managing|You can choose to be alerted for both actual (after accruing) and forecasted (before accruing) spends.`,`budgets-managing|You can use AWS Budgets to monitor your aggregate utilization and coverage metrics for your Reserved Instances (RIs) or Savings Plans.`,`budgets-managing|Setting a daily utilization or coverage budget to track your RI or Savings Plans.`,`budgets-managing|Savings Plans coverage budgets: Define a coverage threshold and get alerted when the percentage of your eligible usage covered by Savings Plans falls below this level`]}),t({id:`db-cost-desk-008`,building:`db-cost-desk`,bullets:[`4.3-K2`],d:2,stem:`A company has run 25 Amazon RDS DB instances at steady load on On-Demand pricing for a year. It wants a recommendation, based on its own usage, of which reserved DB instances to buy, without building its own analysis. Which AWS tool should the company use?`,correct:[`AWS Cost Explorer, which analyzes past usage and recommends Reserved Instances to purchase`,`Cost Explorer can analyze costs and usage and give recommendations for which Reserved Instances to purchase.`],wrong:[[`AWS Budgets, which tracks spend against limits and sends alerts about costs`,`Budgets alerts on thresholds and can monitor existing reservations but does not recommend which reservations to buy.`],[`AWS Cost and Usage Report, which delivers the raw usage and cost data to Amazon S3`,`The report is raw data that the company would have to analyze itself, which it wants to avoid.`],[`AWS Organizations consolidated billing, which shares discounts across accounts`,`Consolidated billing shares existing discounts and gives no recommendation about what to buy.`]],slot:1,evidence:[`ce-what-is|You can view data for up to the last 13 months, forecast how much you're likely to spend for the next 18 months, and get recommendations for what Reserved Instances to purchase.`,`budgets-managing|Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`]}),t({id:`db-cost-desk-009`,building:`db-cost-desk`,bullets:[`4.3-K1`],d:2,tags:[`mock-reserve`],stem:`Accounts A, B and C belong to one organization with consolidated billing. Account A bought reserved DB instances for one DB instance type in one Region. Account A runs fewer matching DB instances than it reserved, while accounts B and C run matching DB instances in that Region at on-demand rates. Which usage receives the unused discount?`,correct:[`Matching DB instance usage in accounts B and C, because the organization shares Reserved Instance discounts`,`Consolidated billing shares Reserved Instance discounts across the accounts, and the discount applies to matching instance type and Region.`],wrong:[[`Only usage in account A, because a reservation is always limited to the account that bought it`,`Consolidated billing shares Reserved Instance discounts across the member accounts, so it is not limited to account A.`],[`DB instance usage in accounts B and C in any Region, whatever the instance type`,`The discount of a reserved DB instance is tied to instance type and Region, so mismatched usage is not covered.`],[`Only usage in accounts B and C that runs in the same Availability Zone as the reservation of account A, and no usage elsewhere`,`The discount is tied to instance type and Region, and nothing in the description limits it to one Availability Zone.`]],slot:2,evidence:[`consolidated-billing|This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`,`rds-reserved|Discounts for reserved DB instances are tied to instance type and AWS Region.`]})],c=[t({id:`distribution-office-001`,building:`distribution-office`,bullets:[`4.2-K3`],d:1,stem:`A company will run a nightly analytics batch on Amazon EC2. No users wait for the results, no law restricts where the data may be stored, and every required service is offered in several AWS Regions. Which approach to selecting the Region is the MOST cost-effective?`,correct:[`Deploy in the Region that offers the lowest prices for the services the batch uses`,`Resource pricing differs between Regions, and AWS advises using Regions with lower prices when there are no data privacy, security or business obligations.`],wrong:[[`Deploy in the Region closest to the company headquarters to give the lowest network latency`,`No users wait for the results, so lower latency adds nothing, and prices still differ between Regions.`],[`Deploy in the Region that has the largest number of Availability Zones available to the account`,`The number of zones does not address the price of the services, which is the only differentiator here.`],[`Deploy in the Region where the company already stores its oldest backups from earlier projects`,`The batch has no requirement to sit near old backups, so price is left unconsidered.`]],slot:0,evidence:[`waf-region-cost|Each AWS Region operates within local market conditions, and resource pricing is different in each Region due to differences in the cost of land, fiber, electricity, and taxes, for example.`,`waf-region-cost|Use Regions that provide lower prices for AWS services to deploy your workloads if you have no obligations in data privacy, security and business requirements.`]}),t({id:`distribution-office-002`,building:`distribution-office`,bullets:[`4.2-S4`],d:2,stem:`A software team uses an Amazon RDS for PostgreSQL DB instance and several Amazon EC2 instances for a test environment only from Monday morning to Friday evening. The data in the database must be kept over the weekend. Which action is the MOST cost-effective?`,correct:[`Stop the DB instance and the EC2 instances on Friday evening and start them again on Monday morning`,`No DB instance hours or EC2 instance usage are charged while the resources are stopped, and the stored data is kept.`],wrong:[[`Delete the DB instance every Friday evening and create a new empty one on Monday morning`,`The data in the database would not be kept over the weekend.`],[`Convert the DB instance to a Multi-AZ deployment so that a standby handles the weekend`,`A standby adds a second copy to pay for and does nothing to stop charges while nobody uses the environment.`],[`Leave all the resources running and buy a Compute Savings Plan to cover the EC2 instances`,`The weekend hours of the database and instances are still paid for, although nobody uses the environment.`]],slot:1,evidence:[`rds-stop|While the instance is stopped, you're not charged for DB instance hours.`,`rds-stop|While your DB instance is stopped, you are charged for provisioned storage (including Provisioned IOPS).`,`ec2-lifecycle|You are not charged for usage or data transfer fees for your instance when it is stopped.`]}),t({id:`distribution-office-003`,building:`distribution-office`,bullets:[`4.2-K3`,`4.2-S4`],d:2,stem:`A company is deploying an order-processing system. The production database must keep running automatically if the Availability Zone that hosts it fails. A staging copy of the system is used only for release testing, and a few minutes of downtime after a failure is acceptable there. Which design is the MOST cost-effective?`,correct:[`Run the production database as a Multi-AZ DB instance deployment and the staging database as a Single-AZ DB instance`,`Production gets a synchronous standby in a different Availability Zone, while staging avoids paying for redundancy that its availability needs do not require.`],wrong:[[`Run both the production database and the staging database as Multi-AZ DB instance deployments so that both environments are configured identically`,`Staging would pay for a standby that its relaxed availability needs do not require.`],[`Run both databases as Single-AZ DB instances and restore from automated backups after a failure`,`Production would not fail over automatically when its Availability Zone fails.`],[`Run production as a Single-AZ DB instance with a read replica in another Region and staging as Multi-AZ`,`Production would not fail over automatically, and staging would pay for a standby it does not need.`]],slot:2,evidence:[`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`,`waf-cost-demand|The economic benefits of just-in-time supply should be balanced against the need to provision to account for resource failures, high availability, and provision time.`]}),t({id:`distribution-office-004`,building:`distribution-office`,bullets:[`4.2-K6`],d:1,stem:`A hospital must process medical-imaging data inside its own data center to meet local latency and data-handling rules. IT staff want the same APIs, tools and services such as Amazon EC2 that they use in the AWS Region, and they want AWS to operate the infrastructure. Which service BEST meets these requirements?`,correct:[`AWS Outposts installed in the hospital data center`,`Outposts extends AWS infrastructure, services, APIs and tools to customer premises, with AWS operating the capacity as part of an AWS Region.`],wrong:[[`AWS Local Zones in the nearest large city`,`A Local Zone places resources close to population centers but not in the hospital data center, so the data would not be processed on site.`],[`AWS Wavelength Zones in the mobile carrier network`,`Wavelength puts compute at the edge of carrier networks, not inside the hospital data center.`],[`Amazon EC2 instances in the nearest Region reached over a dedicated network connection`,`The imaging data would be processed in the Region rather than locally inside the data center.`]],slot:3,evidence:[`outposts-what-is|AWS Outposts is a fully managed service that extends AWS infrastructure, services, APIs, and tools to customer premises.`,`outposts-what-is|AWS operates, monitors, and manages this capacity as part of an AWS Region.`]}),t({id:`distribution-office-005`,building:`distribution-office`,bullets:[`4.2-K5`],d:2,stem:`A company is building an augmented-reality app for smartphones on a mobile carrier's 5G network. The app needs the lowest possible latency between the phones and its Amazon EC2 servers, and the servers must still reach AWS services such as Amazon S3 in the parent Region. Which solution BEST meets these requirements?`,correct:[`Extend the VPC to a Wavelength Zone and run the servers on EC2 instances in that zone`,`Wavelength deploys AWS compute at the edge of communications service providers' networks, and servers there can reach services in the parent Region.`],wrong:[[`Install AWS Outposts in the data center of the company and run the servers there`,`The phones connect through the carrier network, and Outposts sits on the company's premises rather than at the carrier edge.`],[`Run the servers in an AWS Local Zone near a large population center`,`A Local Zone sits near population and industry centers, not at the edge of the carrier network that the phones use.`],[`Serve the app through Amazon CloudFront edge locations with the servers in the parent Region as origin`,`CloudFront caches content at edge locations, but the live app servers would still run in the Region, away from the carrier network.`]],slot:0,evidence:[`wavelength-what-is|Wavelength deploys standard AWS compute and storage services to the edge of communications service providers' (CSP) networks.`,`wavelength-what-is|You can extend a virtual private cloud (VPC) to one or more Wavelength Zones.`]}),t({id:`distribution-office-006`,building:`distribution-office`,bullets:[`4.2-K5`],d:2,stem:`A software vendor distributes large installer files that are identical for every user from Amazon EC2 instances behind an Application Load Balancer in one Region. Downloads peak after each release, and the vendor keeps adding instances to cope. Customers are spread worldwide. The vendor wants to reduce the load on the origin and shorten downloads without running servers in more Regions. Which solution is the MOST cost-effective?`,correct:[`Serve the files through Amazon CloudFront with the load balancer as the origin`,`CloudFront delivers cached content from edge locations with the lowest latency and goes to the origin only when the file is not already cached.`],wrong:[[`Deploy the instance fleet and load balancer in more Regions and use latency-based routing`,`The vendor would run full fleets in more Regions, which is exactly what it wants to avoid.`],[`Move the instances to AWS Wavelength Zones in carrier networks`,`Wavelength serves mobile devices on carrier networks, and the fleet would still serve every download.`],[`Move the instances to an AWS Local Zone and keep serving every download from them`,`Customers are worldwide, and every download would still hit the instances instead of a cache.`]],slot:1,evidence:[`cloudfront-what-is|If the content is already in the edge location with the lowest latency, CloudFront delivers it immediately.`,`cloudfront-what-is|CloudFront delivers your content through a worldwide network of data centers called edge locations.`]}),e({id:`distribution-office-007`,building:`distribution-office`,bullets:[`4.2-K3`,`4.2-S4`],d:3,stem:`A company runs production and QA copies of a web application. Each is an Auto Scaling group of Amazon EC2 instances behind an Application Load Balancer, spread across three Availability Zones with a minimum of six instances. QA is used only from 08:00 to 18:00 on weekdays, and the QA team accepts that QA is unavailable until repaired if one Availability Zone fails. Production must keep its current availability. Which TWO changes lower the cost of QA MOST cost-effectively without changing production? (Choose two.)`,correct:[[`Add scheduled actions to the QA group that lower its desired capacity outside weekday working hours`,`Scheduled actions increase or decrease desired capacity at specific times, so QA stops running instances nobody uses.`],[`Run the QA group in one Availability Zone with a smaller minimum size`,`QA does not need capacity provisioned for a zone failure, so it can drop the redundancy that production still needs.`]],wrong:[[`Apply the same single-zone, smaller configuration to the production group`,`Production must keep its current availability, which needs instances in more than one Availability Zone.`],[`Add a warm standby copy of QA in a second Region for disaster recovery`,`QA needs no disaster recovery, and the standby adds a second environment to pay for.`],[`Raise the QA minimum size to nine so that each zone has spare capacity`,`QA accepts an outage in one zone, so spare capacity only adds cost.`]],slots:[0,2],evidence:[`asg-scheduled|You create scheduled actions that increase or decrease your group's desired capacity at specific times.`,`waf-cost-demand|The economic benefits of just-in-time supply should be balanced against the need to provision to account for resource failures, high availability, and provision time.`,`asg-what-is|You can specify multiple Availability Zones for your Auto Scaling group, and Amazon EC2 Auto Scaling balances your instances evenly across the Availability Zones as the group scales.`]}),t({id:`distribution-office-008`,building:`distribution-office`,bullets:[`4.2-K6`],d:3,stem:`A company runs a latency-sensitive application on AWS Outposts in its own data center. The servers on the Outpost must talk to instances and services in the parent Region over private IP addresses. The company wants one VPC and one set of route tables and security groups for both locations, with the LEAST new network components. Which solution meets these requirements?`,correct:[`Create a subnet on the Outpost in the existing Region VPC and launch the on-premises servers into that subnet`,`Instances in Outpost subnets communicate with instances in the Region over private IP addresses within the same VPC.`],wrong:[[`Create a separate VPC for the Outpost servers and connect it to the Region VPC with an AWS Transit Gateway attachment`,`This builds a second VPC and extra connections, so route tables and security groups are not shared in one VPC.`],[`Place the servers in an AWS Local Zone and extend the Region VPC to that zone`,`A Local Zone is not in the company data center, so the servers would no longer run on the Outpost.`],[`Give the Outpost servers public IP addresses and let them reach the Region over the internet`,`Traffic would use public addresses rather than private IP addresses, which the company requires.`]],slot:2,evidence:[`outposts-what-is|Instances in Outpost subnets communicate with other instances in the AWS Region using private IP addresses, all within the same VPC.`,`local-zones|AWS Local Zones places compute, storage, database, and other select AWS resources close to large population and industry centers.`]}),e({id:`distribution-office-009`,building:`distribution-office`,bullets:[`4.2-K5`,`4.2-K6`],d:3,stem:`A company needs to place three components. A factory-floor controller must process data on site at very low latency while using the same APIs as the Region. Game servers must have the lowest latency to phones on a mobile carrier's 5G network. Marketing videos that are the same for every viewer go to viewers worldwide. Which TWO placements are the MOST cost-effective? (Choose two.)`,correct:[[`Run the factory-floor controller on AWS Outposts at the factory`,`Outposts runs AWS infrastructure on customer premises with the same programming interfaces, for lower latency and local data processing.`],[`Run the game servers in an AWS Wavelength Zone`,`Wavelength puts AWS compute at the edge of communications service providers' networks for low latency to mobile devices.`]],wrong:[[`Deliver the marketing videos from servers in AWS Wavelength Zones`,`Wavelength serves devices on carrier networks and does not cache the videos for viewers worldwide.`],[`Run the factory-floor controller in an AWS Local Zone in the nearest large city`,`A Local Zone is not on the factory premises, so the data would not be processed on site.`],[`Run the game servers on AWS Outposts at the factory`,`The phones connect through the carrier network, not through the factory's premises.`]],slots:[1,4],evidence:[`outposts-what-is|By providing local access to AWS managed infrastructure, AWS Outposts enables customers to build and run applications on premises using the same programming interfaces as in AWS Regions, while using local compute and storage resources for lower latency and local data processing needs.`,`wavelength-what-is|Wavelength deploys standard AWS compute and storage services to the edge of communications service providers' (CSP) networks.`,`wavelength-what-is|AWS Wavelength enables developers to build applications that require edge computing infrastructure to deliver low latency to mobile devices and end users or increase the resiliency of their existing edge applications.`]}),t({id:`distribution-office-010`,building:`distribution-office`,bullets:[`4.2-K3`],d:2,tags:[`mock-reserve`],stem:`A customer-facing web tier runs on Amazon EC2 instances in a single Availability Zone, and an outage in that zone would take the application offline. The company must stay available if one Availability Zone fails but has no requirement to survive the loss of a whole Region. Which solution is the MOST cost-effective?`,correct:[`Run the instances in an Auto Scaling group across two Availability Zones behind an Application Load Balancer`,`The group balances instances across the zones, so the application keeps serving from the other zone, with no second Region to pay for.`],wrong:[[`Run a full second copy of the application in another Region with DNS failover`,`A whole second Region is more redundancy than the requirement calls for and costs a second environment.`],[`Keep the instances in one zone on a larger instance type and take hourly Amazon EBS snapshots of every volume for recovery`,`If the zone fails, the instances are still unavailable until someone restores them elsewhere.`],[`Move the instances to Spot Instances in the same Availability Zone`,`The instances would still all sit in one zone, so a zone failure still takes the application offline.`]],slot:3,evidence:[`asg-what-is|You can specify multiple Availability Zones for your Auto Scaling group, and Amazon EC2 Auto Scaling balances your instances evenly across the Availability Zones as the group scales.`,`global-infra|We call each group of logical data centers an Availability Zone.`]})],l=[t({id:`elastic-mint-001`,building:`elastic-mint`,bullets:[`4.2-K8`,`4.2-S3`],d:1,tags:[`placement-eligible`],stem:`A company's photo app creates a thumbnail whenever a user uploads a picture to Amazon S3. Uploads arrive in unpredictable bursts, and some hours have no uploads at all. Each thumbnail takes a few seconds to create, and the company does not want to pay for idle compute. Which solution is the MOST cost-effective?`,correct:[`Run the thumbnail code as an AWS Lambda function that Amazon S3 invokes for each uploaded picture`,`Lambda is priced per request and execution duration and runs code without servers to provision, so hours without uploads cost nothing for compute.`],wrong:[[`Run the code on an Amazon EC2 instance that polls the bucket, and buy a Compute Savings Plan for that instance`,`The instance runs and is billed through the hours with no uploads, so idle compute is still paid for.`],[`Run the code in an Amazon ECS service on AWS Fargate that keeps two tasks running at all times`,`Fargate bills from the moment a task starts until it terminates, so two always-running tasks are paid for during idle hours.`],[`Run the code on an EC2 Auto Scaling group that has a minimum size of two instances behind a load balancer`,`The minimum of two instances stays running and billed even when no pictures arrive, and a load balancer adds a further component to pay for.`]],slot:0,evidence:[`lambda-pricing|Lambda Event Functions are priced per request and execution duration.`,`lambda-welcome|With Lambda, you can run code without provisioning or managing servers.`,`fargate-pricing|from the time you start to download your container image until the Amazon ECS Task or Amazon EKS`]}),t({id:`elastic-mint-002`,building:`elastic-mint`,bullets:[`4.2-K8`,`4.2-S3`],d:2,tags:[`placement-eligible`],stem:`A company converts customer-uploaded videos with software packaged as a container image. Conversions start a few times each day and each one takes about 40 minutes. The company does not want to manage servers or a cluster of instances. Which solution is the MOST cost-effective?`,correct:[`Start each conversion as an Amazon ECS task on AWS Fargate when a video arrives`,`Fargate runs containers without servers or clusters to manage, and it bills from the time a task starts until the task terminates, so a 40-minute conversion is billed only for that run.`],wrong:[[`Run each conversion in a standard AWS Lambda function with the function timeout set to 40 minutes`,`A standard Lambda function times out at 15 minutes at most, so the 40-minute conversions cannot finish.`],[`Keep a fleet of Amazon EC2 instances running in an ECS cluster and place the conversion tasks on it`,`The company would have to manage and pay for the cluster of instances between conversions, which it wants to avoid.`],[`Keep one EC2 instance running around the clock under a Savings Plan and run the conversions on it`,`The company would manage a server and pay for it during the long gaps between conversions.`]],slot:1,evidence:[`lambda-quotas|Code can run for up to 15 minutes in a single invocation`,`lambda-quotas|Function timeout 900 seconds (15 minutes).`,`fargate-ecs|AWS Fargate is a technology that you can use with Amazon ECS to run containers without having to manage servers or clusters of Amazon EC2 instances.`,`fargate-pricing|from the time you start to download your container image until the Amazon ECS Task or Amazon EKS`]}),e({id:`elastic-mint-003`,building:`elastic-mint`,bullets:[`4.2-K8`,`4.2-S1`],d:2,tags:[`placement-eligible`,`trap:alb-nlb-gwlb`],stem:`A company runs an online store as one application on a fleet of large Amazon EC2 instances. Only the product-search function is busy during sales, yet the whole fleet must be scaled to cope. The company wants each function to scale on its own without managing servers, and wants all functions reachable through one endpoint that routes requests by URL path. Which TWO actions meet these requirements MOST cost-effectively? (Choose two.)`,correct:[[`Split the application into services that run as containers on Amazon ECS with AWS Fargate, each with its own ECS service auto scaling`,`Each service scales to its own demand and adds or removes tasks to reduce cost at low utilization, and Fargate removes server management.`],[`Put one Application Load Balancer in front with listener rules that send each URL path to the target group of its service`,`An Application Load Balancer routes requests to different target groups based on the content of the request, so one endpoint serves every service.`]],wrong:[[`Move the whole application to a larger EC2 instance type with more memory and CPU`,`The application would still scale as one unit, so the quiet functions are paid for at the larger size.`],[`Add scheduled scaling actions for sale days to the Auto Scaling group of the existing fleet`,`The whole application would still scale together, so the idle functions are scaled up along with search.`],[`Create a Network Load Balancer and give each function its own listener port for clients to use`,`A Network Load Balancer works at layer 4 and cannot route by URL path, so clients would have to choose ports instead.`]],slots:[1,4],evidence:[`microservices|Microservices allow each service to be independently scaled to meet demand for the application feature it supports.`,`ecs-autoscaling|You can use these and other CloudWatch metrics to scale out your service (add more tasks) to deal with high demand at peak times, and to scale in your service (run fewer tasks) to reduce costs during periods of low utilization.`,`alb-intro|You can configure listener rules to route requests to different target groups based on the content of the application traffic.`]}),t({id:`elastic-mint-004`,building:`elastic-mint`,bullets:[`4.2-K9`],d:2,tags:[`placement-eligible`],stem:`A company's web tier runs in an Amazon EC2 Auto Scaling group. Traffic follows a repeating pattern that differs from day to day, and a new instance needs about ten minutes to initialize, so users see slow responses at the start of every peak. The company does not want to write and maintain a schedule for each day. Which solution is the MOST cost-effective way to have capacity ready before each peak?`,correct:[`Add a predictive scaling policy so that the group forecasts load from its history and launches instances before the peak`,`Predictive scaling analyses historical load to detect daily or weekly patterns and suits applications that take a long time to initialize, without schedules.`],wrong:[[`Add a target tracking policy on average CPU utilization so that the group scales out when load rises`,`Target tracking reacts only after load arrives, and the ten-minute initialization leaves users with slow responses at the start of each peak.`],[`Raise the minimum size of the group to the peak capacity so that instances are always ready`,`The group would pay for peak capacity during every off-peak hour, which is not cost-effective.`],[`Create scheduled actions for each day of the week with the expected desired capacity for that day`,`Scheduled actions work, but the company would have to write and maintain a schedule for each day, which it wants to avoid.`]],slot:2,evidence:[`asg-predictive|In general, if you have regular patterns of traffic increases and applications that take a long time to initialize, you should consider using predictive scaling.`,`asg-predictive|Predictive scaling works by analyzing historical load data to detect daily or weekly patterns in traffic flows.`]}),t({id:`elastic-mint-005`,building:`elastic-mint`,bullets:[`4.2-K9`],d:1,stem:`A company runs a stateless application in an Amazon EC2 Auto Scaling group. The company wants the group to keep average CPU utilization near a chosen value by adding instances under load and removing them when load falls, with the SIMPLEST configuration. Which scaling policy should the company use?`,correct:[`A target tracking scaling policy on average CPU utilization`,`Target tracking keeps the metric near the target value and helps maintain high utilization without manual intervention.`],wrong:[[`A step scaling policy with CloudWatch alarms that the team creates and tunes for each size change`,`Step scaling needs the team to create and manage the alarms and step adjustments, which is more setup than a target value.`],[`Scheduled scaling actions that change the desired capacity at set hours of the day`,`Scheduled actions follow the clock and do not react to the actual CPU utilization of the group.`],[`Manual changes to the desired capacity whenever an engineer receives a CloudWatch alarm notification`,`Manual changes are not a scaling policy and add ongoing operational work instead of the simplest setup.`]],slot:3,evidence:[`asg-target-tracking|This allows your application to maintain optimal performance and high utilization for your EC2 instances for better cost efficiency without manual intervention.`,`asg-step|With step scaling and simple scaling, you create and manage the CloudWatch alarms that invoke the scaling process.`]}),t({id:`elastic-mint-006`,building:`elastic-mint`,bullets:[`4.2-K9`,`4.2-S2`],d:3,tags:[`placement-eligible`],stem:`A data-science team is launching one new Amazon EC2 On-Demand Instance for an in-memory analysis application. The application needs about 20 minutes to load its working set into memory every time it starts, and the team uses it only during working hours. The team wants to stop paying for instance usage overnight and still resume the application with its in-memory state each morning. Which solution is the MOST cost-effective?`,correct:[`Launch the instance with hibernation enabled and an encrypted root volume that can hold the memory, then hibernate it nightly`,`Hibernation saves the memory to the EBS root volume and resumes the running processes later, and no instance usage is charged while it is stopped.`],wrong:[[`Stop the instance each evening and start it again each morning, expecting the application to continue where it left off`,`Stopping does not save the memory contents, so the application would spend another 20 minutes loading its working set.`],[`Keep the instance running overnight and buy a Compute Savings Plan to lower the hourly cost`,`The team would still pay for instance usage overnight, which it wants to avoid.`],[`Create an AMI each evening, terminate the instance, and launch a new instance from the AMI each morning`,`A new instance boots fresh from the AMI, so the in-memory state is lost and the 20-minute load starts again.`]],slot:0,evidence:[`ec2-hibernate|Hibernation saves the contents from the instance memory (RAM) to your Amazon Elastic Block Store (Amazon EBS) root volume.`,`ec2-hibernate|You're not charged for instance usage for a hibernated instance when it is in the stopped state or for data transfer when the contents of the RAM are transferred to the EBS root volume.`,`ec2-hibernate-prereq|You can enable hibernation support for an On-Demand Instance or a Spot Instance when you launch it.`]}),t({id:`elastic-mint-007`,building:`elastic-mint`,bullets:[`4.2-S1`],d:2,tags:[`placement-eligible`,`trap:alb-nlb-gwlb`],stem:`A company runs a market-data service that uses a custom binary protocol over TCP. Millions of requests per second arrive from client programs, and the protocol is not HTTP. The company wants to spread the connections across its EC2 instances in several Availability Zones. Which load balancer should the company use?`,correct:[`A Network Load Balancer with a TCP listener and the instances registered in a target group`,`A Network Load Balancer works at the fourth layer, handles millions of requests per second, and supports TCP target groups for non-HTTP protocols.`],wrong:[[`An Application Load Balancer with a listener on the service port and the instances in a target group`,`An Application Load Balancer functions at the application layer and forwards requests on HTTP fields such as the host header, so it does not fit a custom binary protocol over TCP.`],[`A Gateway Load Balancer with the instances registered as its targets`,`A Gateway Load Balancer enables you to deploy, scale and manage virtual appliances such as firewalls, so it does not front a client-facing TCP service.`],[`An Amazon CloudFront distribution that uses the instances as a custom origin`,`CloudFront gets your files from origin servers, such as an Amazon S3 bucket or your own HTTP server, so it is a content delivery service and does not carry a custom TCP protocol to the instances.`]],slot:1,evidence:[`nlb-intro|Network Load Balancer functions at the fourth layer of the Open Systems Interconnection (OSI) model.`,`nlb-intro|It can handle millions of requests per second.`,`alb-intro|An Application Load Balancer functions at the application layer, the seventh layer of the Open Systems Interconnection (OSI) model.`,`alb-intro|You can configure rules for your listener that forward requests based on the host field in the HTTP header.`,`gwlb-intro|Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`,`cloudfront-what-is|CloudFront delivers your content through a worldwide network of data centers called edge locations.`,`cloudfront-what-is|You specify origin servers, like an Amazon S3 bucket or your own HTTP server, from which CloudFront gets your files`]}),t({id:`elastic-mint-008`,building:`elastic-mint`,bullets:[`4.2-S1`],d:3,tags:[`placement-eligible`,`trap:alb-nlb-gwlb`],stem:`A company must inspect all traffic that enters and leaves several VPCs with a third-party intrusion detection system delivered as virtual appliances on Amazon EC2 instances. The appliance fleet must grow and shrink with traffic, all packets of one flow must reach the same appliance, and route tables must point at a single entry and exit point instead of individual appliances. Which load balancer BEST meets these requirements?`,correct:[`A Gateway Load Balancer that distributes traffic to an Auto Scaling group of the appliance instances`,`A Gateway Load Balancer combines a transparent network gateway with load distribution, scales the appliances with demand, and keeps flow stickiness to one appliance.`],wrong:[[`An Application Load Balancer with listener rules that forward requests to the appliance instances`,`An Application Load Balancer routes HTTP requests by their content and is not a transparent single entry and exit point for all traffic.`],[`A Network Load Balancer whose target group holds the appliance instances`,`A Network Load Balancer spreads TCP and UDP connections across targets but is not the transparent gateway that appliances need.`],[`One appliance instance per VPC, with route tables pointing at it and a standby instance for failover`,`A single appliance per VPC cannot grow and shrink with traffic and gives no load distribution across a fleet.`]],slot:2,evidence:[`gwlb-intro|It combines a transparent network gateway (that is, a single entry and exit point for all traffic) and distributes traffic while scaling your virtual appliances with the demand.`,`gwlb-intro|It maintains flow stickiness to a specific target appliance using 5-tuple (default), 3-tuple, or 2-tuple.`,`gwlb-intro|Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`]}),t({id:`elastic-mint-009`,building:`elastic-mint`,bullets:[`4.2-S2`],d:2,tags:[`placement-eligible`],stem:`A company runs a stateless web application on one Amazon EC2 instance. The instance is overloaded during a daily peak of about three hours and mostly idle the rest of the day. Changing the instance size requires stopping the instance, and the company cannot accept downtime during the peak. Which solution is the MOST cost-effective?`,correct:[`Put the instances in an Auto Scaling group behind an Application Load Balancer and add instances only during the peak`,`Horizontal scaling adds and removes instances as demand changes, so no instance has to be stopped and the extra capacity is paid for only during the peak.`],wrong:[[`Change the instance to a larger instance type and keep it running all day so that the peak is covered without extra instances`,`The larger rate is paid for all day, including the idle hours, and the type change also requires stopping the instance.`],[`Run a second instance of the same size around the clock and place both behind a load balancer`,`The second instance runs through the idle hours too, and nothing removes the extra capacity when the peak ends.`],[`Buy Reserved Instances for a larger instance type that can handle the peak and resize the instance`,`The resize still requires stopping the instance, and the commitment pays for peak-sized capacity all day.`]],slot:3,evidence:[`ec2-resize-ebs|Considerations You must stop your instance before you can change its instance type.`,`ec2-resize|When you change the instance type, you'll start paying the rate of the new instance type.`,`asg-what-is|If you specify scaling policies, then Amazon EC2 Auto Scaling can launch or terminate instances as demand on your application increases or decreases.`]}),e({id:`elastic-mint-010`,building:`elastic-mint`,bullets:[`4.2-S3`],d:3,stem:`A company is choosing compute for three workloads. A webhook handler runs for under a second per call and is called a few times per hour. A video-rendering batch runs for 40 minutes per job, can restart from a checkpoint, and can run at any time of night. A payment service runs continuously and cannot tolerate interruptions. Which TWO placements are the MOST cost-effective? (Choose two.)`,correct:[[`Run the webhook handler as an AWS Lambda function`,`Lambda is priced per request and execution duration, so a handler that is called a few times per hour has almost no idle cost.`],[`Run the rendering batch on Amazon EC2 Spot Instances and restart from the checkpoint after an interruption`,`The batch is flexible about when it runs and can be interrupted, which is when Spot Instances are a cost-effective choice.`]],wrong:[[`Run the rendering batch as standard AWS Lambda functions`,`A standard Lambda function times out at 15 minutes at most, so the 40-minute jobs cannot finish.`],[`Run the webhook handler on an EC2 instance that stays running all month`,`The instance is billed through every idle moment between the few calls per hour.`],[`Run the payment service on Spot Instances`,`Spot Instances can be interrupted, and the payment service cannot tolerate interruptions.`]],slots:[0,3],evidence:[`lambda-pricing|Lambda Event Functions are priced per request and execution duration.`,`lambda-quotas|Code can run for up to 15 minutes in a single invocation`,`lambda-quotas|Function timeout 900 seconds (15 minutes).`,`ec2-spot|Spot Instances are a cost-effective choice if you can be flexible about when your applications run and if your applications can be interrupted.`]}),t({id:`elastic-mint-011`,building:`elastic-mint`,bullets:[`4.2-K9`,`4.2-S2`],d:3,stem:`An Auto Scaling group runs an application whose instances take a long time to boot because they write a large amount of data to disk at startup. Scale-out events leave users waiting. The company wants to shorten scale-out time with the LOWEST additional cost. Which solution meets these requirements?`,correct:[`Add a warm pool of pre-initialized instances to the group and keep the pooled instances in the Stopped state`,`A warm pool lowers latency for long boot times, and stopped pooled instances cost only for their volumes and attached Elastic IP addresses.`],wrong:[[`Add a warm pool of pre-initialized instances and keep the pooled instances in the Running state`,`Running pooled instances are billed for compute while they wait, which AWS says is highly discouraged to avoid unnecessary charges.`],[`Raise the minimum and desired capacity so that extra in-service instances are always available`,`The extra instances are in service and billed all the time, which costs more than a pool of stopped instances.`],[`Lower the CPU target of the target tracking policy so that scale-out starts at a lower load`,`New instances still boot slowly from scratch, and the group runs more capacity than needed at lower load levels.`]],slot:0,evidence:[`asg-warm-pools|A warm pool gives you the ability to decrease latency for your applications that have exceptionally long boot times, for example, because instances need to write massive amounts of data to disk.`,`asg-warm-pools|Keeping instances in a Stopped state is an effective way to minimize costs.`,`asg-warm-pools|Keeping instances in a Running state inside the warm pool is also possible, but is highly discouraged to avoid incurring unnecessary charges.`]}),t({id:`elastic-mint-012`,building:`elastic-mint`,bullets:[`4.2-K8`,`4.2-S3`],d:2,tags:[`mock-reserve`],stem:`A company runs the development and test environments of an API on AWS Lambda. Provisioned concurrency is configured on every function to avoid cold starts, but developers say cold starts are acceptable in these environments. The company wants to lower the Lambda bill without changing code. Which action is the MOST cost-effective?`,correct:[`Remove the provisioned concurrency configuration from the development and test functions`,`Provisioned concurrency incurs additional charges, and removing it from functions that tolerate cold starts stops those charges.`],wrong:[[`Remove the reserved concurrency settings from the development and test functions`,`There is no charge for configuring reserved concurrency, so removing it does not lower the bill.`],[`Move the functions to Amazon ECS tasks on AWS Fargate that run continuously`,`Continuously running tasks are billed while they run, and moving them means repackaging code as containers.`],[`Replace each function with an Amazon EC2 instance that stays running for the environment`,`The instances would be billed through idle hours and need servers to be managed, which does not lower cost.`]],slot:1,evidence:[`lambda-concurrency|There is no charge for configuring reserved concurrency for an Event Function.`,`lambda-concurrency|Configuring provisioned concurrency incurs charges to your AWS account.`]}),t({id:`elastic-mint-013`,building:`elastic-mint`,bullets:[`4.2-S1`],d:2,tags:[`mock-reserve`,`trap:alb-nlb-gwlb`],stem:`A company runs four low-traffic HTTP services in one VPC, and each service has its own Application Load Balancer. Clients reach the services by host names such as orders.example.com and billing.example.com. The company wants to reduce the number of load balancers while keeping routing by host name. Which solution meets these requirements with the LEAST change?`,correct:[`Replace them with one Application Load Balancer that has host-header listener rules, each forwarding to its own target group`,`An Application Load Balancer can route requests by the host name of each request, so one load balancer can front all four services.`],wrong:[[`Replace them with one Network Load Balancer that has a separate listener on a different port for each service, so that each host name maps to a port`,`A Network Load Balancer works at layer 4, so clients would have to use ports instead of host names to choose a service.`],[`Replace them with one Gateway Load Balancer that has each service registered as a target`,`A Gateway Load Balancer deploys and scales virtual appliances and does not route requests by host name.`],[`Keep the four Application Load Balancers and place an Amazon CloudFront distribution in front of them`,`The number of load balancers stays the same, so the requirement to reduce them is not met.`]],slot:2,evidence:[`alb-rule-conditions|host-header Route based on the host name of each request.`,`alb-intro|You can configure rules for your listener that forward requests based on the host field in the HTTP header.`]})],u=[t({id:`engine-exchange-001`,postGuide:[`dms-schema-conversion`],building:`engine-exchange`,bullets:[`4.3-K7`],d:1,stem:`A company runs a MySQL database in its own data center and wants to move it to Amazon RDS for MySQL. The application must keep using the source database until the day of the cutover, and the company wants to keep the same database engine. Which solution meets these requirements with the LEAST effort?`,correct:[`Use AWS DMS to migrate the data to RDS for MySQL and replicate ongoing changes until the cutover`,`The engine stays the same, which AWS DMS supports, and it can replicate ongoing changes to keep the source and the target in sync until cutover.`],wrong:[[`Convert the schema to PostgreSQL with DMS Schema Conversion and then load the data with AWS DMS`,`Schema conversion is for migrating to a different engine; the company is keeping MySQL, so this adds work and changes the engine.`],[`Stop the application, export a one-time dump of the source database, and import it into RDS for MySQL`,`A one-time dump copies the data once and stops the application, so the source cannot keep serving users until the cutover.`],[`Use AWS DataSync to copy the database files from the data center to the RDS DB instance storage`,`DataSync copies files between storage systems; it does not load data into a running database or replicate changes.`]],slot:0,evidence:[`dms-what-is|Conversely, if you want to migrate away from old infrastructure but continue to use the same database engine, AWS DMS also supports that process.`,`dms-what-is|You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`]}),e({id:`engine-exchange-002`,postGuide:[`dms-schema-conversion`],postGuideKey:[`dms-schema-conversion`],building:`engine-exchange`,bullets:[`4.3-K7`,`4.3-S5`],d:2,stem:`A company runs an Oracle database on premises. It wants to move the database to Amazon Aurora PostgreSQL-Compatible to stop paying for the Oracle licences. The schema contains tables, views and stored procedures. Which TWO steps are required to migrate the schema and the data with the LEAST custom work? (Choose two.)`,correct:[[`Use DMS Schema Conversion to assess and convert the Oracle schema and apply the converted code to the Aurora cluster`,`Moving to a different engine needs the source schema converted to the target engine first.`],[`After the converted code is applied, use AWS DMS to migrate the data from the Oracle database`,`AWS DMS migrates the data once the converted schema exists on the target, and can keep replicating changes.`]],wrong:[[`Export the Oracle tables to CSV files and load them into Aurora PostgreSQL with the PostgreSQL COPY command`,`This moves rows only; the views and stored procedures are not converted, so the team would write that code by hand.`],[`Rewrite the views and stored procedures by hand in PostgreSQL syntax, then use AWS DMS to migrate the data`,`The data step works, but hand-writing the schema code is the custom work that DMS Schema Conversion avoids.`],[`Run AWS DMS alone and let it rewrite the Oracle stored procedures as PostgreSQL code`,`AWS DMS moves data; converting code objects to a new engine is the job of schema conversion.`]],slots:[1,3],evidence:[`dms-what-is|To migrate to a different database engine, you can use DMS Schema Conversion.`,`dms-what-is|After you convert your source schemas and apply the converted code to your target database, you can use AWS DMS to migrate your data.`]}),t({id:`engine-exchange-003`,building:`engine-exchange`,bullets:[`4.3-S2`],d:2,stem:`A company runs Oracle Database Enterprise Edition on premises, and the application depends on Enterprise Edition features. The company owns active Oracle licences, with Software Update License and Support, that it may use in the cloud. It is moving to Amazon RDS for Oracle and wants to avoid buying licences again. Which licensing option is the MOST cost-effective?`,correct:[`Use the Bring Your Own License model and run the DB instance on Oracle Enterprise Edition`,`BYOL lets the company use its existing Oracle Database licences on RDS and supports Enterprise Edition.`],wrong:[[`Use the License Included model and run the DB instance on Oracle Enterprise Edition`,`The License Included model is supported only on Standard Edition 2, so it cannot run the Enterprise Edition features the application needs.`],[`Use the License Included model and run the DB instance on Oracle Standard Edition 2`,`This edition lacks the Enterprise Edition features the application depends on, and the company would pay for a licence it already owns.`],[`Migrate to Amazon Aurora PostgreSQL-Compatible and keep the Oracle application code unchanged`,`Aurora PostgreSQL is a different engine, so the Oracle features and code would have to be converted, which is not a licensing option.`]],slot:1,evidence:[`rds-oracle-licensing|In the BYOL model, you can use your existing Oracle Database licenses to deploy databases on Amazon RDS.`,`rds-oracle-licensing|Amazon RDS supports the BYOL model only for Oracle Database Enterprise Edition (EE) and Oracle Database Standard Edition 2 (SE2).`,`rds-oracle-licensing|The License Included model is only supported on Amazon RDS for Oracle Database Standard Edition 2 (SE2).`]}),t({id:`engine-exchange-004`,building:`engine-exchange`,bullets:[`4.3-S2`],d:3,stem:`A company is launching a production application on Oracle Database Standard Edition 2. It owns no Oracle licences, does not want to buy or track them, and needs the database to fail over automatically to a second Availability Zone. Which solution meets these requirements with the LEAST licensing effort?`,correct:[`Amazon RDS for Oracle Standard Edition 2 with the License Included model and a Multi-AZ deployment`,`AWS holds the licence in this model, so nothing is bought separately, and RDS supports Multi-AZ for Oracle failover.`],wrong:[[`Amazon RDS for Oracle Standard Edition 2 with Bring Your Own License and a Multi-AZ deployment`,`BYOL needs licences the company does not own, and a Multi-AZ deployment needs a licence for both the primary and the standby DB instance.`],[`Amazon RDS for Oracle Enterprise Edition with the License Included model and a Multi-AZ deployment`,`The License Included model is supported only on Standard Edition 2, so Enterprise Edition cannot be used with it.`],[`Oracle Database installed on Amazon EC2 instances in two Availability Zones with the company's own failover scripts`,`The company would still have to obtain Oracle licences itself and build and operate the failover, which is more effort.`]],slot:2,evidence:[`rds-oracle-licensing|In the License Included model, you don't need to purchase Oracle Database licenses separately.`,`rds-oracle-licensing|If you use the Bring Your Own License model, you must have a license for both the primary DB instance and the standby DB instance in a Multi-AZ deployment.`,`rds-oracle-licensing|Amazon RDS supports Multi-AZ deployments for Oracle as a high-availability, failover solution.`]}),t({id:`engine-exchange-005`,building:`engine-exchange`,bullets:[`4.3-S2`],d:2,stem:`A company is building a shopping-cart service that reads and writes each cart by its cart ID. The service has no joins or multi-table transactions, and its traffic grows from a few users to millions. The company wants a fully managed database that scales without capacity management at the LOWEST operational cost. Which database engine should the company choose?`,correct:[`Amazon DynamoDB`,`DynamoDB is a serverless, fully managed NoSQL database with single-digit millisecond performance at any scale, which fits key-based cart access without servers to size.`],wrong:[[`Amazon Aurora MySQL-Compatible Edition with a large writer instance`,`A relational engine suits joins and transactions the service does not need, and the company would size and pay for the instances.`],[`Amazon RDS for PostgreSQL in a Multi-AZ deployment`,`The company would choose and manage a DB instance size, and a relational engine is not needed for key-based access.`],[`MySQL installed on Amazon EC2 instances in an Auto Scaling group`,`The company would patch, replicate and scale the database itself, which is the highest operational cost of the four.`]],slot:3,evidence:[`dynamodb-what-is|Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale.`,`dynamodb-what-is|For example, DynamoDB delivers consistent single-digit millisecond performance for a shopping cart use case, whether you have 10 or 100 million users.`]}),t({id:`engine-exchange-006`,postGuide:[`dms-schema-conversion`],postGuideKey:[`dms-schema-conversion`],building:`engine-exchange`,bullets:[`4.3-K7`,`4.3-S5`],d:3,stem:`A company runs Microsoft SQL Server on premises, and the licence costs are high. Developers are willing to adjust application code. The company wants to move to Amazon Aurora PostgreSQL-Compatible, keep the source database in use while the data is copied, and avoid writing its own conversion tools. Which approach is the MOST cost-effective way to meet these requirements?`,correct:[`Convert and apply the schema with DMS Schema Conversion, then run AWS DMS to load the data and replicate changes until the cutover`,`The engine changes, so the schema is converted first, and DMS then migrates the data and keeps source and target in sync.`],wrong:[[`Export the SQL Server tables to CSV files, load them into Aurora PostgreSQL with COPY, and rewrite the views and procedures by hand`,`This is a one-time copy with no ongoing replication, so the source and target drift apart, and all code conversion is custom work.`],[`Run AWS DMS with a full load only, and ask developers to recreate the views and stored procedures by hand`,`Without schema conversion the developers write the conversion by hand, and a full load alone leaves the source out of sync after the copy.`],[`Convert the schema with DMS Schema Conversion, stop the application, and copy the data once with a database export and import`,`The source database would be unavailable during the copy, which fails the requirement to keep it in use while the data is copied.`]],slot:0,evidence:[`dms-what-is|AWS DMS supports fully heterogeneous data migrations between the supported engines.`,`dms-what-is|This service automatically assesses and converts your source schemas to a new target engine.`,`dms-what-is|You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`]}),t({id:`engine-exchange-007`,building:`engine-exchange`,bullets:[`4.3-S5`],d:2,stem:`A company migrates a production PostgreSQL database to Amazon RDS for PostgreSQL. The migration runs for several weeks while it replicates ongoing changes, and it must keep running without manual intervention if an Availability Zone fails. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`AWS DMS with a Multi-AZ replication instance and a continuous replication task`,`AWS DMS provisions and maintains a synchronous standby replica of the replication instance in another Availability Zone and can replicate ongoing changes.`],wrong:[[`AWS DMS with a replication instance in a single Availability Zone, restarted by hand after a failure`,`A failure of that zone stops the replication until someone intervenes, which conflicts with the no-manual-intervention requirement.`],[`A scheduled script on an Amazon EC2 instance that dumps the database and restores it on the target`,`The company would write and operate the script, and a periodic dump does not replicate ongoing changes.`],[`AWS DataSync tasks that copy the database files from the source server to the target`,`DataSync copies files between storage systems; it does not load data into a running managed database or replicate changes.`]],slot:1,evidence:[`dms-replication-instance|By using a replication instance, you can get high availability and failover support with a Multi-AZ deployment when you choose the Multi-AZ option.`,`dms-replication-instance|In a Multi-AZ deployment, AWS DMS automatically provisions and maintains a synchronous standby replica of the replication instance in a different Availability Zone.`,`dms-what-is|You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`]}),t({id:`engine-exchange-008`,building:`engine-exchange`,bullets:[`4.3-K7`,`4.3-S2`],d:1,stem:`A company's application runs on MySQL today, and its code and tools are written for MySQL. The company wants a managed relational database that the existing code, tools and applications can keep using, without moving to a non-relational model. Which service BEST meets these requirements?`,correct:[`Amazon Aurora MySQL-Compatible`,`Aurora is compatible with MySQL, so the code, tools and applications used with existing MySQL databases can be used with it.`],wrong:[[`Amazon DynamoDB`,`DynamoDB is a non-relational service, so the MySQL queries and tools would need to be rewritten.`],[`Amazon DocumentDB`,`DocumentDB is a document database service, not a relational one, so the SQL-based code and tools would not carry over.`],[`Amazon Redshift`,`Redshift is a data warehouse for analytics, not a drop-in relational database for the existing MySQL application.`]],slot:2,evidence:[`aurora-overview|The code, tools, and applications you use today with your existing MySQL and PostgreSQL databases can be used with Aurora.`,`aurora-overview|Amazon Aurora (Aurora) is a fully managed relational database engine that's compatible with MySQL and PostgreSQL.`]}),t({id:`engine-exchange-009`,building:`engine-exchange`,bullets:[`4.3-S5`],d:2,tags:[`mock-reserve`],stem:`A company keeps an on-premises PostgreSQL database of closed orders that no application queries any more. Auditors may ask for the data, and the company wants to keep it on low-cost storage instead of a running database. Which solution moves the data with the LEAST custom code?`,correct:[`Use AWS DMS to migrate the tables to Amazon S3`,`AWS DMS can move data to low-cost storage platforms such as Amazon S3, so no custom extraction code is needed.`],wrong:[[`Create an Amazon RDS for PostgreSQL DB instance and keep the data there for auditors`,`A running DB instance keeps charging for compute and storage, though no application queries the data.`],[`Create an Amazon Aurora PostgreSQL cluster and stop it when the auditors are not asking`,`This still keeps a database cluster whose storage is billed, and it is a database rather than low-cost storage.`],[`Write an AWS Lambda function that queries every table and writes the rows to Amazon S3`,`This is custom code to write, test and run for large tables, which the company wants to avoid.`]],slot:3,evidence:[`dms-what-is|Or it can help you move to the managed data warehouse service provided by Amazon Redshift, NoSQL platforms like Amazon DynamoDB, or low-cost storage platforms like Amazon Simple Storage Service (Amazon S3).`]})],d=[t({id:`haul-hybrid-customs-001`,building:`haul-hybrid-customs`,bullets:[`4.1-K8`,`4.1-S7`],d:1,stem:`A company's trading partners deliver daily files to the company over SFTP. The company wants the files stored in Amazon S3 and wants a managed solution with the LEAST operational overhead. Which service should the company use?`,correct:[`AWS Transfer Family with an SFTP server endpoint that stores the files in the S3 bucket`,`Transfer Family offers fully managed support for transferring files over SFTP directly into and out of AWS storage services.`],wrong:[[`AWS DataSync with a task that copies from the partners' systems into the S3 bucket`,`DataSync copies data between storage systems and AWS storage; it does not give partners an SFTP endpoint to upload to.`],[`AWS Storage Gateway with an S3 File Gateway that the partners mount`,`A file gateway offers file system protocols to on-premises applications, not an SFTP server for outside partners.`],[`An Amazon EC2 instance that runs an SFTP server and copies each uploaded file to the bucket`,`This works, but the company must patch, scale, and operate the server, which adds the overhead it wants to avoid.`]],slot:0,evidence:[`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`,`datasync-what-is|DataSync works with the following on-premises storage systems: Network File System (NFS) Server Message Block (SMB) Hadoop Distributed File Systems (HDFS) Object storage`]}),t({id:`haul-hybrid-customs-002`,building:`haul-hybrid-customs`,bullets:[`4.1-K8`],d:2,stem:`A company keeps backups on a physical tape library that is expensive to maintain. The backup software must keep writing to virtual tapes, and the company wants the backups archived durably in the cloud at the LOWEST cost without changing the backup software. Which solution meets these requirements?`,correct:[`Deploy an AWS Storage Gateway Tape Gateway that archives virtual tapes to S3 Glacier Deep Archive`,`Tape Gateway provides cloud-backed virtual tape storage and lets you cost-effectively and durably archive backup data in S3 Glacier.`],wrong:[[`Deploy an S3 File Gateway and change the backup software to write files to a share`,`The backup software is not supposed to change, and a file gateway offers file shares rather than virtual tapes.`],[`Use AWS DataSync to copy the tape contents into an Amazon EFS file system every night`,`The backup software would have to change from tapes to files, and EFS is not an archive tier for backups.`],[`Create AWS Transfer Family SFTP endpoints and have the backup software upload its tape images each night`,`The software writes to virtual tapes and does not upload over SFTP, and the enabled endpoints would be billed while they run.`]],slot:1,evidence:[`sgw-tape|With Tape Gateway, you can cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`,`sgw-tape|Tape Gateway provides cloud-backed virtual tape storage.`]}),t({id:`haul-hybrid-customs-003`,building:`haul-hybrid-customs`,bullets:[`4.1-S7`,`4.1-S3`],d:2,stem:`A company must copy 60 TB of data from an on-premises NFS server to Amazon S3 once, over its existing internet connection, within a few weeks. The company does not want to order a new network circuit, wants the data verified after the copy, and wants the LOWEST cost with little operational overhead. Which solution meets these requirements?`,correct:[`Run an AWS DataSync task from an on-premises agent to the S3 bucket over the existing connection`,`DataSync prepares, transfers, and verifies the data, and charges a flat per-gigabyte fee with no upfront costs and no minimum charges.`],wrong:[[`Order an AWS Direct Connect connection and copy the data with a script over it`,`A Direct Connect connection is a new circuit the company does not want, and a script does not verify the data.`],[`Set up an AWS Transfer Family SFTP server endpoint and have an administrator upload the files by hand`,`The server endpoint is billed while its protocols are enabled, and the manual uploads add effort and give no verification.`],[`Deploy an S3 File Gateway and copy the files into the share by hand`,`A gateway is for continuing hybrid access to the data, not for a one-time bulk copy that is verified.`]],slot:2,evidence:[`datasync-how|How DataSync transfers files, objects, and directories During a task execution, DataSync prepares, transfers, and verifies your data.`,`datasync-pricing|You pay a flat, per-gigabyte fee for the amount of data transferred between your storage locations.`,`datasync-pricing|With DataSync, there are no upfront costs and no minimum charges.`]}),t({id:`haul-hybrid-customs-004`,building:`haul-hybrid-customs`,bullets:[`4.1-S3`],d:2,tags:[`trap:direct-connect-vs-vpn`],stem:`A small branch office must send a few gigabytes of files each day, encrypted, to private subnets in a VPC. The office already has an internet connection and has no need for dedicated bandwidth. Which solution meets these requirements at the LOWEST cost?`,correct:[`An AWS Site-to-Site VPN connection over the existing internet connection`,`Site-to-Site VPN supports IPsec VPN connections between the office and the VPC and needs no new physical circuit.`],wrong:[[`An AWS Direct Connect dedicated connection from the office to a Direct Connect location`,`It links the network over a fiber-optic cable to a Direct Connect location, a physical circuit, and AWS Direct Connect is not encrypted by default.`],[`Two AWS Direct Connect connections at different locations for resilience`,`This adds more physical circuits than a small daily transfer needs and is not encrypted by default.`],[`Amazon S3 Transfer Acceleration on a bucket in the Region of the VPC`,`It speeds uploads to an S3 bucket but does not create an encrypted connection to private subnets.`]],slot:3,evidence:[`s2s-vpn|Site-to-Site VPN supports Internet Protocol security (IPsec) VPN connections.`,`dx-what-is|Direct Connect links your internal network to a Direct Connect location over a standard Ethernet fiber-optic cable.`,`dx-encryption|AWS Direct Connect does not encrypt your traffic that is in transit by default.`]}),t({id:`haul-hybrid-customs-005`,building:`haul-hybrid-customs`,bullets:[`4.1-S1`],d:1,stem:`A company's devices produce 40 million tiny records each day, and an application uploads each record to Amazon S3 as its own object. The company wants to reduce the request charges of the uploads. Which design change is MOST cost-effective?`,correct:[`Combine many records into larger objects before uploading them`,`Ingesting objects with PUT requests is charged per request, so fewer, larger objects mean fewer billed requests.`],wrong:[[`Enable S3 Transfer Acceleration on the bucket and keep uploading each record`,`It speeds long-distance transfers and might add data transfer charges, and the request count stays the same.`],[`Upload each record with multipart upload to improve the throughput`,`Multipart upload is for large objects, and it would add more requests for each tiny record.`],[`Change the storage class of the bucket to S3 Intelligent-Tiering`,`The storage class does not reduce the number of upload requests, and objects below 128 KB are not eligible for auto-tiering.`]],slot:0,evidence:[`s3-pricing|There are per-request ingest charges when using PUT, COPY, or lifecycle rules to move data into any S3 storage class.`,`s3-storage-classes|If the size of an object is less than 128 KB, it is not monitored and not eligible for auto-tiering.`,`s3-transfer-acceleration|When you use Transfer Acceleration, additional data transfer charges might apply.`]}),e({id:`haul-hybrid-customs-006`,building:`haul-hybrid-customs`,bullets:[`4.1-S1`],d:2,stem:`A company uploads 4 GB files to Amazon S3 over a network that drops connections. Uploads often fail near the end and restart from the beginning, and abandoned partial uploads keep adding storage cost. Which TWO actions fix the failures and control the cost with the LEAST operational overhead? (Choose two.)`,correct:[[`Upload the files with multipart upload so that only a failed part is retransmitted`,`Parts are uploaded independently and in parallel, and a failed part can be retransmitted without restarting the whole upload.`],[`Add a bucket lifecycle rule that aborts incomplete multipart uploads after a number of days`,`A lifecycle rule with the AbortIncompleteMultipartUpload action stops uploads that are not completed, which minimizes storage costs.`]],wrong:[[`Upload each file in a single PUT request and retry the whole request on failure`,`A failure still restarts the entire 4 GB upload, so the problem remains.`],[`Enable S3 Transfer Acceleration to avoid any network errors during the uploads`,`It speeds long-distance transfers and might add charges; it does not stop a dropped connection from restarting a single request.`],[`Switch the bucket to S3 One Zone-IA so that partial uploads are not billed`,`A storage class does not change the billing of the parts of an in-progress multipart upload.`]],slots:[1,2],evidence:[`s3-multipart|Quick recovery from any network issues – Smaller part size minimizes the impact of restarting a failed upload due to a network error.`,`s3-multipart|Throughout its lifetime, you are billed for all storage, bandwidth, and requests for this multipart upload and its associated parts.`,`s3-mpu-abort|As a best practice, we recommend that you configure a lifecycle rule by using the AbortIncompleteMultipartUpload action to minimize your storage costs.`]}),t({id:`haul-hybrid-customs-007`,building:`haul-hybrid-customs`,bullets:[`4.1-S1`,`4.1-S3`],d:3,stem:`Customers on several continents upload large video files to one centralized Amazon S3 bucket in a single Region. Their uploads are slow over long distances and cannot use all of their available bandwidth. The company wants faster uploads with the LEAST operational overhead and accepts additional data transfer charges. Which solution meets these requirements?`,correct:[`Enable S3 Transfer Acceleration on the bucket and have customers use the accelerated endpoint`,`It speeds transfers over long distances to a centralized bucket by routing uploads through CloudFront edge locations.`],wrong:[[`Create a bucket in every customer Region and replicate each one into the central bucket`,`Every extra bucket and replication setup adds storage, cost, and management compared with one bucket setting.`],[`Order an AWS Direct Connect connection for each customer location`,`The customers are individual internet users, and a physical connection per location is impractical and costly.`],[`Install an AWS DataSync agent on every customer device to push the files`,`DataSync agents are set up for storage systems, and deploying and managing them for every customer adds overhead.`]],slot:1,evidence:[`s3-transfer-acceleration|Your customers upload to a centralized general purpose bucket from all over the world.`,`s3-transfer-acceleration|You can't use all of your available bandwidth over the internet when uploading to Amazon S3.`,`s3-transfer-acceleration|When you use Transfer Acceleration, additional data transfer charges might apply.`]}),e({id:`haul-hybrid-customs-008`,building:`haul-hybrid-customs`,bullets:[`4.1-K8`,`4.1-S7`],d:3,stem:`A company is moving data to Amazon S3 in two ways. Research data on an on-premises NFS server must be copied to a bucket each night. Suppliers must also deliver files over FTPS directly into the bucket. The company wants the LEAST operational overhead. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Use AWS DataSync to copy the NFS data to the bucket on a schedule`,`DataSync transfers file data between on-premises NFS storage and AWS storage services.`],[`Use AWS Transfer Family with a server endpoint that has FTPS enabled and stores files in the bucket`,`Transfer Family offers fully managed support for transferring files over FTPS directly into AWS storage services.`]],wrong:[[`Use AWS Database Migration Service to migrate the NFS data and the supplier files`,`DMS migrates databases and other data stores, not files from an NFS server or from FTPS clients.`],[`Use an AWS Storage Gateway Tape Gateway to receive the supplier files`,`Tape Gateway provides virtual tape storage for backups, not an FTPS endpoint for suppliers.`],[`Run an FTP server on an Amazon EC2 instance and use it for both transfers`,`The company would patch and operate the server, and it still would not copy the NFS data on a schedule.`]],slots:[0,3],evidence:[`datasync-what-is|DataSync works with the following on-premises storage systems: Network File System (NFS) Server Message Block (SMB) Hadoop Distributed File Systems (HDFS) Object storage`,`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`,`dms-what-is|AWS Database Migration Service (AWS DMS) is a cloud service that makes it possible to migrate relational databases, data warehouses, NoSQL databases, and other types of data stores.`]}),t({id:`haul-hybrid-customs-009`,building:`haul-hybrid-customs`,bullets:[`4.1-S7`],d:3,stem:`A company copies about 400 GB of changed files each night from an on-premises NFS server to an Amazon EFS file system. The office network is shared with business applications during the day, so the copy must be limited in how much bandwidth it uses. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Use AWS DataSync with a recurring, bandwidth-limited task that has the EFS file system as the destination`,`DataSync supports EFS as a destination, and a task can limit how much bandwidth DataSync uses.`],wrong:[[`Use an AWS Transfer Family SFTP server that writes to the EFS file system`,`Transfer Family gives partners an SFTP endpoint; it does not pull NFS data on a schedule or limit bandwidth, and the endpoint adds a server that is billed while enabled.`],[`Use an S3 File Gateway so that the NFS server writes its changed files into the share every night`,`A file gateway stores the data in Amazon S3, not in the EFS file system that is the required destination.`],[`Use an AWS Storage Gateway Volume Gateway to present cloud-backed iSCSI volumes to the NFS server`,`Volume Gateway presents iSCSI volumes backed by S3, which neither copies the NFS files nor writes to EFS.`]],slot:2,evidence:[`datasync-what-is|DataSync works with the following AWS storage services: Amazon S3 Amazon EFS Amazon FSx for Windows File Server Amazon FSx for Lustre Amazon FSx for OpenZFS Amazon FSx for NetApp ONTAP`,`datasync-how|For example, you can specify what metadata gets copied, exclude certain files, and limit how much bandwidth DataSync uses, among other options.`,`sgw-volume|Volume Gateway provides cloud-backed storage volumes that you can mount as Internet Small Computer System Interface (iSCSI) devices from your on-premises application servers.`]}),t({id:`haul-hybrid-customs-010`,building:`haul-hybrid-customs`,bullets:[`4.1-K8`],d:2,tags:[`mock-reserve`],stem:`A retailer exchanges purchase orders with its suppliers as business-to-business messages over the AS2 protocol and wants the files stored in Amazon S3. The retailer wants a managed service with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`AWS Transfer Family with an AS2 server that stores the messages in the S3 bucket`,`Transfer Family offers fully managed support for transferring files over AS2 directly into AWS storage services.`],wrong:[[`AWS DataSync with a recurring task between the supplier systems and the bucket`,`DataSync copies data between storage systems and does not act as an AS2 endpoint for suppliers.`],[`AWS Storage Gateway with a Volume Gateway that suppliers attach to`,`Volume Gateway provides iSCSI volumes to on-premises servers and is not an AS2 server for outside partners.`],[`An Amazon EC2 instance running AS2 software that copies each message to the bucket`,`The retailer would install, patch, and scale the software, which adds the overhead it wants to avoid.`]],slot:3,evidence:[`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`]})],f=[t({id:`instance-foundry-001`,building:`instance-foundry`,bullets:[`4.2-K7`,`4.2-S5`],d:1,stem:`A company runs a nightly batch job on Amazon EC2 that transcodes media files. The job is CPU-bound and uses little memory. Which instance family is the MOST cost-effective fit for the job?`,correct:[`Compute optimized instances, which suit batch processing and media transcoding`,`Compute optimized instances are designed for compute-intensive applications and are ideal for batch processing and media transcoding.`],wrong:[[`Memory optimized instances, which suit large data sets processed in memory`,`The job uses little memory, so the company would pay for memory capacity that it does not use.`],[`Storage optimized instances, which suit high sequential access to large data sets on local storage`,`The job is limited by CPU and not by local storage throughput, so the storage capability would go unused.`],[`General purpose instances, which use compute, memory and networking in equal proportions`,`The job needs more compute than memory, so a balanced family pays for memory proportions that the job does not use.`]],slot:3,evidence:[`ec2-co|These instances are ideal for batch processing workloads, media transcoding, high performance web servers, high performance computing (HPC), scientific modeling, dedicated gaming servers, ad server engines, and machine learning inference.`,`ec2-gp|These instances are ideal for applications that use these resources in equal proportions, such as web servers and code repositories.`]}),t({id:`instance-foundry-002`,building:`instance-foundry`,bullets:[`4.2-K7`],d:2,stem:`A company runs development and test web servers on Amazon EC2. The servers sit nearly idle most of the day and show short CPU spikes when developers deploy new builds. Which instance family has the LOWEST cost and meets these needs?`,correct:[`Burstable performance (T) instances, which can burst above a CPU baseline`,`Burstable instances suit development and test environments, and CPU credits cover the short spikes above the baseline.`],wrong:[[`Compute optimized instances, which suit compute-intensive applications`,`The servers are idle most of the day, so the company would pay for sustained high CPU performance it rarely uses.`],[`Memory optimized instances, which suit large data sets processed in memory`,`The servers are not memory-bound, so the company would pay for memory capacity that it does not need.`],[`Accelerated computing instances, which use co-processors for graphics or floating point work`,`The web servers do not need hardware accelerators, so the company would pay for co-processors it never uses.`]],slot:0,evidence:[`ec2-instance-types|Burstable performance (T) instances provide a baseline level of CPU performance with the ability to burst above the baseline.`,`ec2-instance-types|The baseline CPU is designed to meet the needs of the majority of general purpose workloads, such as large-scale micro-services, web servers, small and medium databases, data logging, code repositories, virtual desktops, and development and test environments.`]}),t({id:`instance-foundry-003`,building:`instance-foundry`,bullets:[`4.2-K7`],d:3,stem:`A high-volume website runs on burstable performance instances configured in unlimited mode. CPU utilization stays well above the baseline for most of the day, and the bill keeps showing charges for surplus credits. The site must keep its full CPU performance under sustained load. Which change BEST fits this workload?`,correct:[`Move to a fixed performance instance type that is sized for the sustained load`,`Fixed performance instances sustain full CPU performance for as long as a workload needs it, which avoids surplus credit charges.`],wrong:[[`Switch the burstable instances from unlimited mode to standard mode`,`In standard mode, CPU utilization is lowered to the baseline once accrued credits run low, so the site would be throttled during sustained load.`],[`Move the web servers to memory optimized instances sized for large in-memory data sets`,`Memory optimized instances are designed for large data sets in memory, and the site is limited by CPU and not by memory.`],[`Move the web servers to storage optimized instances with large local storage volumes`,`Storage optimized instances are designed for high sequential access to very large data sets on local storage, which the site does not need.`]],slot:2,evidence:[`ec2-instance-types|If you need consistently high CPU performance for applications such as video encoding, high volume websites, or HPC applications, we recommend that you use fixed performance instances.`,`ec2-t-unlimited|If the average CPU usage over a 24-hour period exceeds the baseline, you incur charges for surplus credits.`,`ec2-t-standard|If the instance is running low on accrued credits, CPU utilization is gradually lowered to the baseline level, so that the instance does not experience a sharp performance drop-off when its accrued CPU credit balance is depleted.`]}),t({id:`instance-foundry-004`,building:`instance-foundry`,bullets:[`4.2-S5`],d:2,stem:`A company runs an in-memory analytics application that loads a 300 GB data set into memory. The instances are in the compute optimized family, CPU use averages 10 percent, and the application keeps running out of memory. The company wants to fix this at the LOWEST cost. Which solution meets these requirements?`,correct:[`Move to memory optimized instances in a size that holds the data set`,`Memory optimized instances are designed for workloads that process large data sets in memory, so the company stops paying for unused CPU.`],wrong:[[`Move to a larger size in the compute optimized family until the data set fits`,`The extra memory comes bundled with CPU the application does not use, so the company pays for compute capacity it never needs.`],[`Move to storage optimized instances with large local storage`,`The data set must be held in memory, and local storage capacity does not fix a shortage of memory.`],[`Move to accelerated computing instances with co-processors`,`The application is limited by memory and not by floating point or graphics work, so the co-processors would go unused.`]],slot:1,evidence:[`ec2-mo|Memory optimized instances are designed to deliver fast performance for workloads that process large data sets in memory.`,`ec2-instance-types|Select an instance type based on the requirements of the application or software that you plan to run on your instance.`]}),t({id:`instance-foundry-005`,building:`instance-foundry`,bullets:[`4.2-S5`],d:1,stem:`A company runs 200 Amazon EC2 instances whose types were chosen by guesswork. It wants recommendations for better-fitting instance types based on actual utilization, with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Opt in to AWS Compute Optimizer and review its recommendations`,`Compute Optimizer analyzes configuration and utilization metrics and gives rightsizing recommendations to reduce cost.`],wrong:[[`Create an AWS Budgets budget for each instance`,`A budget alerts on cost thresholds and does not recommend instance types.`],[`Review Amazon CloudWatch CPU graphs for each instance and choose new types by hand`,`This can work, but the team does the analysis and comparison itself for 200 instances, which is more operational effort than a recommendation service.`],[`Buy a Compute Savings Plan for the current usage`,`A plan lowers the rate paid for the usage and does not change the instance types that were chosen by guesswork.`]],slot:0,evidence:[`compute-optimizer|AWS Compute Optimizer is a service that analyzes your AWS resources' configuration and utilization metrics to provide you with rightsizing recommendations and identify idle resources.`,`ec2-resize|If you want a recommendation for an instance type that is best able to handle your existing workload, you can use AWS Compute Optimizer.`]}),t({id:`instance-foundry-006`,building:`instance-foundry`,bullets:[`4.2-S6`],d:2,stem:`A legacy application runs on an Amazon EC2 instance whose root volume is an instance store volume. Utilization data shows that the instance is much larger than the workload needs, and the company wants to run it on a smaller instance type. Which approach should the company use?`,correct:[`Launch a new instance of the smaller type and migrate the application to it`,`For an instance store-backed instance, the documented procedure is to migrate to a new instance type.`],wrong:[[`Stop the instance and change its instance type to the smaller type`,`Changing the type in place applies to EBS-backed instances with a compatible configuration, and it does not apply to an instance store root volume.`],[`Change the instance type while the instance keeps running`,`Even for an EBS-backed instance the instance must be stopped before its type can be changed, and the in-place change does not apply to instance store root volumes.`],[`Buy a Compute Savings Plan and keep the instance as it is`,`A plan lowers the rate for the usage but does not right-size the instance, so the company would still pay for capacity it does not use.`]],slot:3,evidence:[`ec2-resize|Root volume Compatibility Use these instructions EBS Compatible Change the instance type EBS Not compatible Migrate to a new instance type Instance store Not applicable Migrate to a new instance type`,`ec2-resize-ebs|Considerations You must stop your instance before you can change its instance type.`]}),e({id:`instance-foundry-007`,building:`instance-foundry`,bullets:[`4.2-S5`,`4.2-S6`],d:2,stem:`A company wants rightsizing recommendations for the 60 Amazon EC2 instances that have run in its account for months. The account has not used AWS Compute Optimizer before. Which TWO actions are needed to get usable recommendations with the LEAST effort? (Choose two.)`,correct:[[`Opt in to AWS Compute Optimizer for the account`,`Compute Optimizer analyzes resources only after the account has opted in.`],[`Make sure that the instances have accumulated sufficient metric data`,`Resources must have sufficient metric data before Compute Optimizer can generate recommendations, which the months-old instances have.`]],wrong:[[`Create an AWS Budgets budget for each instance so that recommendations appear`,`Budgets alert on cost and usage and are not a requirement for rightsizing recommendations.`],[`Buy a Savings Plan first so that Compute Optimizer can analyze the usage`,`A commitment is not a requirement for the analysis, and it would commit spend before the instances are right-sized.`],[`Stop all the instances so that their metrics can be exported`,`Stopping instances halts the utilization data that the analysis relies on and interrupts the workloads.`]],slots:[0,3],evidence:[`compute-optimizer|You must opt in to have Compute Optimizer analyze your AWS resources.`,`compute-optimizer|For Compute Optimizer to generate recommendations for these resources, they must meet a specific set of requirements, and must have accumulated sufficient metric data.`]}),t({id:`instance-foundry-008`,building:`instance-foundry`,bullets:[`4.2-S6`],d:3,stem:`A production database server runs on an EBS-backed x86 instance that utilization data shows to be oversized. The company wants a smaller instance type with the data kept in place and the LEAST effort, and it can accept a short planned outage. Which approach meets these requirements?`,correct:[`Stop the instance, change it to a smaller x86 instance type, and start it again`,`An EBS-backed instance with a compatible configuration can have its type changed after it is stopped, and the company pays the rate of the new type.`],wrong:[[`Change the instance to a smaller Arm-based Graviton type without rebuilding anything`,`An AMI is specific to its processor architecture, so the new type must have the same architecture as the current x86 type.`],[`Change the instance type while the instance keeps running`,`The instance must be stopped before its type can be changed, so the change cannot be done while it runs.`],[`Launch a new instance of the smaller type, then copy the database and its data to it`,`This works, but a compatible EBS-backed instance can be changed in place, which takes less effort than a migration.`]],slot:2,evidence:[`ec2-resize-ebs|Considerations You must stop your instance before you can change its instance type.`,`ec2-resize-compat|Architecture AMIs are specific to the architecture of the processor, so you must select an instance type with the same processor architecture as the current instance type.`,`ec2-resize|Root volume Compatibility Use these instructions EBS Compatible Change the instance type EBS Not compatible Migrate to a new instance type Instance store Not applicable Migrate to a new instance type`]}),e({id:`instance-foundry-009`,building:`instance-foundry`,bullets:[`4.2-K7`],d:3,tags:[`mock-reserve`],stem:`A company runs a portable Linux application on x86 Amazon EC2 instances and wants better price performance by using AWS Graviton processors. Which TWO actions are required to move the application? (Choose two.)`,correct:[[`Use an AMI that is built for the Arm processor architecture`,`An AMI is specific to its processor architecture, so Graviton instances need an Arm AMI.`],[`Launch the application on a new instance of a Graviton-based instance type`,`Graviton is a family of processors designed to deliver the best price performance for workloads on EC2, and the application must run on a new instance of a Graviton-based type because an existing x86 instance cannot be changed to an Arm-based type.`]],wrong:[[`Change the instance type of the running x86 instances to a Graviton type`,`The new type must have the same processor architecture as the current type, so an x86 instance cannot be changed to an Arm type.`],[`Keep the existing x86 AMI and select a Graviton-based instance type at launch`,`The x86 AMI is specific to its processor architecture and cannot be used with an Arm-based type.`],[`Move the application to Spot Instances of the same x86 instance family`,`The x86 instance family runs on Intel or AMD processors rather than Graviton, so Spot Instances of it do not meet the goal.`]],slots:[1,4],evidence:[`graviton|AWS Graviton is a family of processors designed to deliver the best price performance for your cloud workloads running in Amazon Elastic Compute Cloud (Amazon EC2).`,`ec2-resize-compat|Architecture AMIs are specific to the architecture of the processor, so you must select an instance type with the same processor architecture as the current instance type.`,`ec2-type-names|a – AMD processors b*00 | gb*00 – Accelerated by NVIDIA Blackwell GPUs g – AWS Graviton processors i – Intel processors`]})],p=[t({id:`ledger-office-001`,building:`ledger-office`,bullets:[`4.1-K1`],d:1,stem:`A research institute stores a large public dataset in an Amazon S3 bucket and shares it with university partners that have their own AWS accounts. The institute wants the partners to pay the request and download costs for their own use of the data. Which solution meets this requirement with the LEAST change to the bucket?`,correct:[`Enable Requester Pays on the bucket and have the partners make authenticated requests`,`With Requester Pays, the requester instead of the bucket owner pays the cost of the request and the data download.`],wrong:[[`Apply a cost allocation tag to the bucket and activate it in the Billing and Cost Management console`,`A tag only labels the bucket costs in reports; the institute would still be charged for the partners' downloads.`],[`Move the bucket to a different storage class and keep the bucket open to anonymous access`,`A storage class changes how storage is billed, and the owner would still pay for the downloads by anonymous users.`],[`Add the partner accounts to the institute's AWS Organizations organization with consolidated billing`,`Consolidated billing combines the member accounts onto one bill paid by the management account, so the institute would pay.`]],slot:0,evidence:[`requester-pays|With Requester Pays buckets, the requester instead of the bucket owner pays the cost of the request and the data download from the bucket.`,`requester-pays|Typically, you configure buckets to be Requester Pays buckets when you want to share data but not incur charges associated with others accessing the data.`]}),t({id:`ledger-office-002`,building:`ledger-office`,bullets:[`4.1-K1`],d:2,stem:`A company shares data from an Amazon S3 bucket that has Requester Pays enabled. A partner's application runs in the partner's account A and assumes an IAM role that belongs to the partner's separate account B before it downloads objects. Which account is charged for the request and the data download?`,correct:[`Account B, the account to which the assumed role belongs`,`When the requester assumes an IAM role before making the request, the account to which the role belongs is charged for the request.`],wrong:[[`Account A, the account where the application runs and made the call`,`The charge follows the account the assumed role belongs to, not the account where the application is running.`],[`The account that owns the bucket, because role-based requests are billed to the owner`,`Requester Pays moves the request and download costs away from the bucket owner, including for role-based requests.`],[`The management account of the bucket owner's organization, which pays for all member accounts`,`Consolidated billing covers charges inside the owner's organization; the partner accounts are the requesters here.`]],slot:1,evidence:[`requester-pays|When the requester assumes an AWS Identity and Access Management (IAM) role before making their request, the account to which the role belongs is charged for the request.`,`requester-pays|The bucket owner always pays the cost of storing data.`]}),e({id:`ledger-office-003`,building:`ledger-office`,bullets:[`4.1-K1`,`4.1-K2`],d:3,stem:`A company publishes a genomics dataset in an Amazon S3 bucket for customers who each have an AWS account. The company wants customers to pay for their own downloads, and wants to report the storage cost of this bucket separately from its other projects in the same account. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Enable Requester Pays on the bucket`,`The requester pays the request and download cost, while the company keeps paying only to store the data.`],[`Tag the bucket with a project key and activate the key as a cost allocation tag`,`Activated cost allocation tags organise resource costs on the cost allocation report, so the bucket can be reported by project.`]],wrong:[[`Make the bucket public so that customers can download without signing in`,`Requester Pays does not allow anonymous access, and downloads by anonymous users would not be charged to anyone but the owner.`],[`Invite the customer accounts into the company's organization to share one bill`,`This puts all charges on the management account and does not separate the bucket's costs by project.`],[`Create a separate AWS account for every customer and copy the dataset into each one`,`This multiplies storage and management effort and does not report this bucket separately from the other projects.`]],slots:[1,3],evidence:[`requester-pays|If you enable Requester Pays on a general purpose bucket, anonymous access to that bucket is not allowed.`,`requester-pays|The bucket owner always pays the cost of storing data.`,`cost-alloc-tags|After you activate cost allocation tags, AWS uses the cost allocation tags to organize your resource costs on your cost allocation report, to make it easier for you to categorize and track your AWS costs.`]}),t({id:`ledger-office-004`,building:`ledger-office`,bullets:[`4.1-K2`],d:2,stem:`A finance team tagged all Amazon EC2 instances with a CostCenter tag, but the tag does not appear as a grouping option in AWS Cost Explorer. The team wants to see costs by cost center with the LEAST effort. Which action meets this requirement?`,correct:[`Activate the CostCenter tag as a cost allocation tag in the Billing and Cost Management console`,`Tags must be activated as cost allocation tags before they can appear in Cost Explorer or on a cost allocation report.`],wrong:[[`Re-apply the CostCenter tag to every instance by using a different tag key name`,`The key is not the problem; a tag with any key name still has to be activated before it shows in Cost Explorer.`],[`Place all of the accounts into an organization and turn on consolidated billing`,`Consolidated billing gives one bill for several accounts but does not activate a tag for cost reporting.`],[`Wait for the tag to appear on its own, because every tag is shown in Cost Explorer automatically`,`Tags do not appear automatically; both AWS-generated and user-defined tags must be activated separately.`]],slot:2,evidence:[`cost-alloc-tags|You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`,`cost-alloc-tags|All tags can take up to 24 hours to appear in the Billing and Cost Management console.`]}),t({id:`ledger-office-005`,building:`ledger-office`,bullets:[`4.1-K2`],d:2,stem:`A company runs twelve AWS accounts that each receive a separate bill. The company wants one bill, wants to combine usage across the accounts so that volume pricing and Reserved Instance discounts are shared, and does not want to pay a fee for the feature. Which solution meets these requirements?`,correct:[`Create an AWS Organizations organization and use consolidated billing from its management account`,`Consolidated billing gives one bill, combines usage across accounts to share discounts, and is offered at no additional cost.`],wrong:[[`Buy Reserved Instances in each account and send each invoice to the finance team by email`,`Separate accounts keep separate bills, and the discounts would not be shared across accounts.`],[`Create a budget in each account and review the budgets together every month`,`AWS Budgets tracks costs and alerts on thresholds; it does not merge bills or share discounts.`],[`Deliver a Cost and Usage Report from each account to one S3 bucket and add the totals`,`The reports give detailed data but the accounts are still billed separately with no shared discounts.`]],slot:3,evidence:[`consolidated-billing|One bill – You get one bill for multiple accounts in the same SOR.`,`consolidated-billing|This shares the volume pricing discounts, Reserved Instance discounts, and Savings Plans.`,`consolidated-billing|No extra fee – Consolidated billing is offered at no additional cost.`]}),t({id:`ledger-office-006`,building:`ledger-office`,bullets:[`4.1-K3`],d:1,stem:`A company wants its finance team to receive an email notification when monthly AWS spending approaches or exceeds a limit that the team defines. The company wants the LEAST operational overhead. Which AWS service should the company use?`,correct:[`AWS Budgets, with a budget that has an alert threshold`,`Budgets lets you set spending limits and receive alerts when costs approach or exceed your defined threshold.`],wrong:[[`AWS Cost Explorer, with a saved report of monthly cost by service`,`Cost Explorer views and analyses costs and usage; it is not the service for setting limits and alerts.`],[`AWS Cost and Usage Report, delivered daily to an Amazon S3 bucket`,`The report publishes detailed billing data to S3 but sends no alert when spending reaches a limit.`],[`Cost allocation tags, activated on every resource in the account`,`Tags organise costs on reports but do not compare spending with a limit or send notifications.`]],slot:0,evidence:[`budgets-managing|Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`,`ce-what-is|AWS Cost Explorer is a tool that enables you to view and analyze your costs and usage.`]}),t({id:`ledger-office-007`,building:`ledger-office`,bullets:[`4.1-K3`],d:2,stem:`A data analyst needs the most detailed AWS billing data, with line items broken down by hour and by product, delivered to a storage location the company owns so that the analyst can query it with SQL in Amazon Athena. Which solution meets these requirements with the LEAST custom work?`,correct:[`Configure an AWS Cost and Usage Report that delivers to an Amazon S3 bucket`,`The report holds the most comprehensive cost and usage data, is published to your own S3 bucket, and can be queried with Athena.`],wrong:[[`Use the main graph in AWS Cost Explorer and export the chart each day to a file`,`Cost Explorer is for viewing and analysing costs, and exported charts do not give hourly line items to query.`],[`Create an AWS Budgets budget for each service and read the budget history`,`A budget tracks spending against limits and does not provide line-item billing data to query.`],[`Tag every resource and read the tag names from the Billing and Cost Management console`,`Tags label resources; they are not a delivered data set that can be queried with SQL.`]],slot:1,evidence:[`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`,`cur-what-is|You can use Cost and Usage Reports to publish your AWS billing reports to an Amazon Simple Storage Service (Amazon S3) bucket that you own.`,`cur-what-is|Using your report You can download your report from the Amazon S3 console, query the report using Amazon Athena, or upload the report into Amazon Redshift or Quick.`]}),e({id:`ledger-office-008`,building:`ledger-office`,bullets:[`4.1-K3`],d:3,stem:`A finance team wants to explore the last year of AWS costs by service in a graph without writing queries, and wants to be told when the utilization of its Reserved Instances falls below a target. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Use AWS Cost Explorer to view and filter costs and usage by service`,`Cost Explorer lets you explore usage and costs with the main graph, with filters and groupings you can change.`],[`Create an AWS Budgets budget that monitors Reserved Instance utilization with an alert`,`Budgets can monitor the aggregate utilization and coverage of Reserved Instances and alert on a threshold.`]],wrong:[[`Deliver an AWS Cost and Usage Report to Amazon S3 and build graphs with queries`,`The report is a detailed data set that needs queries and a charting tool, which the team wants to avoid.`],[`Enable Requester Pays on the Amazon S3 buckets that store the company data`,`Requester Pays shifts request and download charges to requesters; it gives no cost graphs or utilization alerts.`],[`Activate cost allocation tags on all resources and read the tag names each month`,`Tags group costs on reports but do not graph the full year of costs or alert on Reserved Instance utilization.`]],slots:[0,4],evidence:[`ce-what-is|You can explore your usage and costs using the main graph, the Cost Explorer cost and usage reports, or the Cost Explorer RI reports.`,`budgets-managing|You can use AWS Budgets to monitor your aggregate utilization and coverage metrics for your Reserved Instances (RIs) or Savings Plans.`]}),t({id:`ledger-office-009`,building:`ledger-office`,bullets:[`4.1-K2`],d:3,tags:[`mock-reserve`],stem:`A company uses AWS Organizations and applies a Project tag to resources in several member accounts. A finance analyst signs in to a member account but cannot find the Project tag in the cost allocation tags manager of the Billing console, and wants the tag to appear in Cost Explorer for the whole organization. Which solution meets this requirement with the LEAST effort?`,correct:[`Sign in to the management account and activate the Project tag as a cost allocation tag in the Billing console`,`In an organization, only the management account has access to the cost allocation tags manager, and a tag must be activated before it can appear in Cost Explorer.`],wrong:[[`Have an administrator in each member account activate the tag in that account's Billing console`,`Member accounts of an organization have no access to the cost allocation tags manager, so the tag cannot be activated there.`],[`Attach an IAM policy that allows tagging actions to every user in each member account`,`Permission to tag resources does not activate the tag for cost reporting, and the tag is already applied.`],[`Create an AWS Budgets budget for each member account that is filtered on the Project tag`,`A budget does not activate the tag for Cost Explorer grouping, and it adds one budget per account to manage.`]],slot:2,evidence:[`cost-alloc-tags|Only the management account in an organization and single accounts that aren't members of an organization have access to the cost allocation tags manager in the Billing console.`,`cost-alloc-tags|You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`]})],m=[t({id:`nat-toll-001`,building:`nat-toll`,bullets:[`4.4-K4`],d:1,tags:[`trap:nat-gateway-vs-instance`],stem:`A finance analyst compares the cost model of a NAT gateway with that of a NAT instance for the outbound traffic of private subnets. Which statement describes how each option is charged?`,correct:[`A NAT gateway is charged by the number of gateways, the duration of use and the data it processes, while a NAT instance is charged by the number of instances, the duration of use and the instance type and size`,`These are the cost factors that the NAT comparison lists for each option, so a gateway has a data-based component and an instance has an instance-size component.`],wrong:[[`A NAT gateway is charged by its instance type and size, while a NAT instance is charged by the amount of data that it processes`,`This swaps the two models: a NAT gateway has no instance type, and a NAT instance is charged by instance type and size.`],[`Both options are charged only for the hours that they run, with no cost factor for the amount of data or for the instance size`,`A NAT gateway is also charged for each gigabyte of data it processes, and a NAT instance is charged by instance type and size.`],[`A NAT gateway has no charge while it is available but idle, while a NAT instance is charged for each hour that it runs`,`A NAT gateway is charged for each hour that it is available, even when it carries no traffic.`]],slot:0,evidence:[`vpc-nat-comparison|Cost Charged depending on the number of NAT gateways you use, duration of usage, and amount of data that you send through the NAT gateways.`,`vpc-nat-comparison|Charged depending on the number of NAT instances that you use, duration of usage, and instance type and size.`,`vpc-nat-pricing|When you provision a NAT gateway, you are charged for each hour that your NAT gateway is available and each gigabyte of data that it processes.`]}),t({id:`nat-toll-002`,building:`nat-toll`,bullets:[`4.4-K4`],d:2,tags:[`trap:nat-gateway-vs-instance`],stem:`A development VPC needs outbound internet access for a few private instances. The administrators also want to reach those private instances over SSH through the same device and to forward one inbound port to a test server. The team accepts managing the device. Which solution meets these requirements MOST cost-effectively?`,correct:[`A NAT instance on a small Amazon EC2 instance type that is also configured as the bastion server with port forwarding`,`A NAT instance can be used as a bastion server and supports port forwarding by manual configuration, and it is charged by instance type and size.`],wrong:[[`A NAT gateway in a public subnet with a security group attached that allows SSH and the forwarded port from the administrator network`,`A NAT gateway cannot have security groups associated with it, does not support bastion servers, and does not support port forwarding.`],[`A NAT gateway in each Availability Zone with an Elastic IP address that administrators use for SSH access`,`A NAT gateway does not support bastion servers, so administrators could not reach the private instances through it.`],[`A private NAT gateway in the development VPC with a route to the administrators' network`,`A private NAT gateway is for communication with on-premises or overlapping networks, and it does not act as a bastion server.`]],slot:1,evidence:[`vpc-nat-comparison|Use as a bastion server.`,`vpc-nat-comparison|You cannot associate security groups with NAT gateways.`,`vpc-nat-comparison|Charged depending on the number of NAT instances that you use, duration of usage, and instance type and size.`]}),t({id:`nat-toll-003`,building:`nat-toll`,bullets:[`4.4-K4`],d:2,tags:[],stem:`Workloads in private subnets have IPv6 addresses and send large volumes of outbound traffic to IPv6 endpoints on the internet. The traffic goes through NAT gateways. The company wants to remove the NAT gateway charges while the internet must still be unable to start connections to the workloads. Which change is the MOST cost-effective?`,correct:[`Create an egress-only internet gateway and route the IPv6 traffic of the private subnets to it`,`An egress-only internet gateway allows outbound IPv6 traffic only, so the internet cannot start connections, and it has no charge of its own.`],wrong:[[`Move the workloads to public subnets with a route to an internet gateway`,`An internet gateway also lets the internet start connections to the workloads, which the company must prevent.`],[`Keep one public NAT gateway in a single Availability Zone and route the IPv6 traffic of all private subnets to it`,`The gateway is still charged for each hour and for each gigabyte it processes, and the zones depend on one gateway.`],[`Create a private NAT gateway and route the IPv6 traffic of the private subnets to it`,`A private NAT gateway serves on-premises and overlapping networks and does not give the workloads access to the internet.`]],slot:2,evidence:[`vpc-egress-only-igw|An egress-only internet gateway is a horizontally scaled, redundant, and highly available VPC component that allows outbound communication over IPv6 from instances in your VPC to the internet, and prevents the internet from initiating an IPv6 connection with your instances.`,`vpc-egress-only-igw|There is no charge for an egress-only internet gateway, but there are data transfer charges for EC2 instances that use internet gateways.`,`vpc-nat-pricing|When you provision a NAT gateway, you are charged for each hour that your NAT gateway is available and each gigabyte of data that it processes.`,`vpc-nat-scenarios|You can use a private NAT gateway to enable communication from your VPCs to your on-premises network using a pool of allow-listed addresses.`]}),e({id:`nat-toll-004`,building:`nat-toll`,bullets:[`4.4-K4`],d:3,tags:[`trap:gateway-vs-interface-endpoints`],stem:`A company's private subnets send most of their NAT gateway traffic to Amazon S3 and Amazon DynamoDB tables in the same Region. The company wants to lower the NAT gateway data processing cost without adding hourly or data processing charges for a new endpoint. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a gateway VPC endpoint for Amazon S3 and associate it with the private route tables`,`Gateway endpoints for S3 have no additional charge and keep that traffic off the NAT gateway.`],[`Create a gateway VPC endpoint for Amazon DynamoDB and associate it with the private route tables`,`Gateway endpoints for DynamoDB also have no additional charge, so DynamoDB traffic stops being processed by the NAT gateway.`]],wrong:[[`Create interface VPC endpoints for Amazon S3 and Amazon DynamoDB in every Availability Zone`,`Interface endpoints are billed for each hour provisioned in each zone and for every gigabyte processed, which adds charges.`],[`Add a NAT gateway in a second Availability Zone and route half of the private subnets to it`,`A second gateway adds another hourly charge and its data processing charge applies to the same traffic.`],[`Create an interface VPC endpoint for Amazon S3 only and keep the DynamoDB traffic on the NAT gateway`,`The interface endpoint adds hourly and per-gigabyte charges, and the DynamoDB traffic is still processed by the NAT gateway.`]],slots:[0,2],evidence:[`vpce-gateway|Gateway VPC endpoints provide reliable connectivity to Amazon S3 and DynamoDB without requiring an internet gateway or a NAT device for your VPC.`,`vpce-gateway|There is no additional charge for using gateway endpoints.`,`vpce-gateway|Amazon S3 and DynamoDB support both gateway endpoints and interface endpoints.`]}),e({id:`nat-toll-005`,postGuide:[`nat-gateway-secondary-ips`],building:`nat-toll`,bullets:[`4.4-S1`],d:2,tags:[`trap:nat-gateway-vs-instance`],stem:`A production VPC has private subnets in three Availability Zones that all use one NAT gateway in the first zone. The company needs internet access to keep working if one zone fails, and wants to stop paying for traffic that crosses zones to reach the NAT gateway. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a NAT gateway in each Availability Zone that has private subnets`,`A NAT gateway in each zone ensures a zone-independent architecture, so a zone failure does not remove internet access elsewhere.`],[`Point the route table of each private subnet to the NAT gateway in the same Availability Zone`,`Traffic then stays in its own zone, which avoids the cross-zone data transfer to reach a gateway in another zone.`]],wrong:[[`Keep the single NAT gateway and associate additional Elastic IP addresses with it for each zone`,`Extra addresses do not change the zone the gateway runs in, so a failure of that zone still removes internet access for the others.`],[`Associate a security group with each NAT gateway that allows only the traffic of its own zone`,`Security groups cannot be associated with NAT gateways, and they would not change where the traffic is routed.`],[`Add a NAT instance in every zone beside the existing NAT gateway and keep all routes pointing to the gateway`,`The extra instances add cost and administration, and routes that still point to one gateway keep the cross-zone traffic and the dependency.`]],slots:[1,3],evidence:[`vpc-nat-comparison|Create a NAT gateway in each Availability Zone to ensure zone-independent architecture.`,`vpc-nat-pricing|If your AWS resources send or receive a significant volume of traffic across Availability Zones, ensure that the resources are in the same Availability Zone as the NAT gateway.`,`vpc-nat-basics|If you have resources in multiple Availability Zones and they share one NAT gateway, and if the NAT gateway's Availability Zone is down, resources in the other Availability Zones lose internet access.`]}),t({id:`nat-toll-006`,building:`nat-toll`,bullets:[`4.4-S1`],d:1,tags:[],stem:`A company runs a short-lived test environment in a VPC with private subnets in two Availability Zones. The environment needs outbound internet access to pull packages. The team accepts that internet access is lost for the other zone if the zone with the NAT gateway fails, and wants the LOWEST NAT gateway cost. Which design meets these requirements?`,correct:[`One NAT gateway in a single Availability Zone, with the route tables of the private subnets in both zones pointing to it`,`Only one gateway is charged for each hour it is available, and the stated risk, loss of internet access in the other zone when its zone is down, is accepted.`],wrong:[[`One NAT gateway in each Availability Zone, with each private subnet routed to the gateway in its own zone`,`This doubles the hourly charge to remove a failure risk that the team has said it accepts.`],[`One NAT gateway in each Availability Zone plus a NAT instance in each zone as a standby device`,`This adds two more devices to pay for and manage when the team accepts the dependency on one zone.`],[`One Network Load Balancer in front of two NAT gateways in different zones to spread the outbound traffic from the private subnets in both zones`,`A load balancer adds an hourly charge and two gateways cost more than the single gateway the requirement allows.`]],slot:3,evidence:[`vpc-nat-basics|If you have resources in multiple Availability Zones and they share one NAT gateway, and if the NAT gateway's Availability Zone is down, resources in the other Availability Zones lose internet access.`,`vpc-nat-pricing|When you provision a NAT gateway, you are charged for each hour that your NAT gateway is available and each gigabyte of data that it processes.`]}),t({id:`nat-toll-007`,building:`nat-toll`,bullets:[`4.4-S1`],d:2,tags:[],stem:`A company's VPC uses a CIDR range that overlaps with the on-premises network it is connected to. Workloads in private subnets must reach an on-premises system that only accepts traffic from a small pool of allow-listed addresses. The traffic must not go over the internet. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`A private NAT gateway that translates the traffic to the allow-listed address pool toward the on-premises network`,`A private NAT gateway enables communication from the VPC to the on-premises network using a pool of allow-listed addresses, even where CIDR ranges overlap.`],wrong:[[`A public NAT gateway with an Elastic IP address that the on-premises firewall is changed to allow`,`A public NAT gateway sends traffic to the internet, and the traffic is required to stay off the internet.`],[`A NAT instance in a public subnet with a source and destination check turned off and manual address translation for each flow`,`The team would manage and patch the instance itself, which raises overhead compared with a managed gateway.`],[`A new VPC with an internet gateway where each workload gets its own public IP address and a security group`,`Public addresses move the traffic onto the internet and do not provide the allow-listed pool the on-premises system accepts.`]],slot:0,evidence:[`vpc-nat-scenarios|You can use a private NAT gateway to enable communication from your VPCs to your on-premises network using a pool of allow-listed addresses.`,`vpc-nat-scenarios|You can use a private NAT gateway to enable communication between networks even if they have overlapping CIDR ranges.`]}),t({id:`nat-toll-008`,building:`nat-toll`,bullets:[`4.4-S1`],d:3,tags:[],stem:`A company's workloads in private subnets in three Availability Zones must reach an on-premises system that accepts traffic only from an allow-listed address pool. The traffic must not use the internet, and the connection must keep working if one Availability Zone fails. The company wants the NAT gateway design with the LEAST administration that meets these requirements. Which solution should the company choose?`,correct:[`A private NAT gateway in each Availability Zone, with each zone's subnets routed to the gateway in the same zone`,`A private NAT gateway translates traffic to the on-premises network without the internet, and one gateway per zone keeps the other zones working if one zone is down.`],wrong:[[`One private NAT gateway in a single Availability Zone shared by the private subnets of all three zones`,`If that gateway's Availability Zone is down, resources in the other Availability Zones lose the connection.`],[`A public NAT gateway in each zone with an Elastic IP address that the on-premises firewall is changed to allow`,`A public NAT gateway sends the traffic toward the internet, and the traffic must not use the internet.`],[`Two NAT instances in an Auto Scaling group with a script that updates the route tables after a failure`,`The company would patch and operate the instances and the script, which is more administration than a managed gateway.`]],slot:1,evidence:[`vpc-nat-scenarios|You can use a private NAT gateway to enable communication from your VPCs to your on-premises network using a pool of allow-listed addresses.`,`vpc-nat-basics|If you have resources in multiple Availability Zones and they share one NAT gateway, and if the NAT gateway's Availability Zone is down, resources in the other Availability Zones lose internet access.`,`vpc-nat-basics|To improve resiliency, create a NAT gateway in each Availability Zone, and configure your routing to ensure that resources use the NAT gateway in the same Availability Zone.`]}),t({id:`nat-toll-009`,building:`nat-toll`,bullets:[`4.4-S1`],d:2,tags:[`mock-reserve`],stem:`A company runs a development environment with private subnets in three Availability Zones. The instances only download operating system patches from the internet and must stay in private subnets. A short loss of this internet access if one Availability Zone fails is acceptable. The company wants the LOWEST cost for the NAT design. Which solution meets these requirements?`,correct:[`One public NAT gateway in a public subnet, with the route tables of all the private subnets pointing to it`,`A single gateway serves all the private subnets and avoids the hourly charge of a gateway in every zone, and the loss of access during a zone failure is acceptable.`],wrong:[[`A public NAT gateway in every Availability Zone, with each zone's private subnets routed to its own gateway`,`This improves resiliency, but each gateway is charged for every hour it is available, which is not the lowest cost for a development environment.`],[`Move the instances to public subnets and give each instance a public IP address so that no NAT gateway is used`,`The instances must stay in private subnets, and public addresses expose them to the internet.`],[`An egress-only internet gateway attached to the VPC and referenced in the private route tables`,`It allows outbound traffic over IPv6 only, so it does not give the IPv4 instances access to the internet.`]],slot:2,evidence:[`vpc-nat-basics|If you have resources in multiple Availability Zones and they share one NAT gateway, and if the NAT gateway's Availability Zone is down, resources in the other Availability Zones lose internet access.`,`vpc-nat-pricing|When you provision a NAT gateway, you are charged for each hour that your NAT gateway is available and each gigabyte of data that it processes.`,`vpc-egress-only-igw|An egress-only internet gateway is for use with IPv6 traffic only.`]}),t({id:`nat-toll-010`,building:`nat-toll`,bullets:[`4.4-S1`],d:3,tags:[],postGuide:[`nat-gateway-secondary-ips`],postGuideKey:[`nat-gateway-secondary-ips`],stem:`Application servers in private subnets send a very large number of simultaneous connections through one public NAT gateway to the same partner API endpoint, which is a single destination IP address and port. Connection attempts start to fail at peak load, while the gateway's bandwidth stays far below its limit. The servers must stay in private subnets. Which change raises the number of simultaneous connections to that one destination?`,correct:[`Associate additional IPv4 addresses with the NAT gateway`,`Each IPv4 address supports a fixed number of simultaneous connections to each unique destination, and the limit can be raised by associating more IPv4 addresses with the NAT gateway.`],wrong:[[`Choose a larger size for the NAT gateway so that it has more bandwidth`,`A NAT gateway has no sizes and already scales its bandwidth automatically; bandwidth is not the limit that is being reached.`],[`Attach a security group to the NAT gateway that allows more connections`,`Security groups cannot be associated with NAT gateways, and they do not set a connection limit.`],[`Replace the public NAT gateway with a private NAT gateway`,`A private NAT gateway is for communication with on-premises or overlapping networks, so the servers would lose internet access to the partner API.`]],slot:3,evidence:[`vpc-nat-basics|Each IPv4 address can support up to 55,000 simultaneous connections to each unique destination.`,`vpc-nat-basics|You can increase this limit by associating up to 8 IPv4 addresses to your NAT gateways (1 primary IPv4 address and 7 secondary IPv4 addresses).`,`vpc-nat-basics|A NAT gateway supports 5 Gbps of bandwidth and automatically scales up to 100 Gbps.`,`vpc-nat-comparison|You cannot associate security groups with NAT gateways.`,`vpc-nat-scenarios|You can use a private NAT gateway to enable communication from your VPCs to your on-premises network using a pool of allow-listed addresses.`]}),t({id:`nat-toll-011`,building:`nat-toll`,bullets:[`4.4-S1`],d:3,tags:[],stem:`A VPC has one public NAT gateway in a single subnet that carries the outbound traffic of thousands of instances. Monitoring shows dropped packets during traffic peaks, while connection counts to each destination are low. The instances must stay in private subnets and must keep using NAT. Which design change prevents the packet loss?`,correct:[`Split the instances into multiple subnets and create a separate NAT gateway for each subnet`,`A NAT gateway drops packets beyond its packet-rate limit, and splitting the resources into multiple subnets with a NAT gateway in each subnet is the documented way to prevent the loss.`],wrong:[[`Choose a larger size for the existing NAT gateway`,`A NAT gateway has no sizes; it scales automatically up to a limit, and beyond that limit it drops packets.`],[`Attach a security group to the NAT gateway with rules that allow more traffic`,`Security groups cannot be associated with NAT gateways, and they do not raise any packet limit.`],[`Move the instances to public subnets with public IP addresses so that they bypass the NAT gateway`,`The instances must stay in private subnets, and moving them to public subnets gives up that requirement.`]],slot:0,evidence:[`vpc-nat-basics|A NAT gateway can process one million packets per second and automatically scales up to 10 million packets per second.`,`vpc-nat-basics|Beyond this limit, a NAT gateway will drop packets.`,`vpc-nat-basics|To prevent packet loss, split your resources into multiple subnets and create a separate NAT gateway for each subnet.`,`vpc-nat-comparison|You cannot associate security groups with NAT gateways.`]})],h=[t({id:`network-cost-audit-001`,building:`network-cost-audit`,bullets:[`4.4-K1`],d:1,stem:`A company has 14 AWS accounts that were opened by separate teams and are paid separately. Finance wants one bill for all of the accounts and a way to track the charges across them, with no additional fee. Which solution meets these requirements with the LEAST effort?`,correct:[`Add the accounts to an organization in AWS Organizations and use consolidated billing`,`Consolidated billing gives one bill for multiple accounts, lets the management account track charges across them, and has no extra fee.`],wrong:[[`Create an AWS Budgets budget in every account and send the alerts to one finance mailbox`,`Budgets alert on spending but do not combine the accounts into one bill.`],[`Export a Cost Explorer report from every account each month and combine the files in a spreadsheet`,`This is manual work each month and the accounts would still be billed separately.`],[`Run a Trusted Advisor cost optimization check in every account and total the savings by hand`,`Trusted Advisor recommends savings; it does not consolidate the bills of several accounts.`]],slot:0,evidence:[`consolidated-billing|Every organization in AWS Organizations has a management account that pays the charges of all the member accounts.`,`consolidated-billing|One bill – You get one bill for multiple accounts in the same SOR.`,`consolidated-billing|No extra fee – Consolidated billing is offered at no additional cost.`]}),t({id:`network-cost-audit-002`,building:`network-cost-audit`,bullets:[`4.4-K1`],d:2,stem:`A company uses AWS Organizations with 30 member accounts. Data transfer charges rose sharply last month, and the finance team must find which member account spent the most on Amazon EC2 without signing in to each account. Which solution meets this requirement with the LEAST effort?`,correct:[`In the management account, use AWS Cost Explorer with the Linked Account and Service filters`,`Cost Explorer in the management account can filter by linked account and service to identify the member account that spent the most.`],wrong:[[`Sign in to every member account and read the Billing page of each one in turn`,`This takes 30 separate sign-ins and manual comparison, which is the effort the team wants to avoid.`],[`Create an AWS Budgets budget in the management account with a spending alert threshold`,`A budget alerts when costs reach a threshold; it does not rank the member accounts by what they spent.`],[`Run the Trusted Advisor cost optimization checks in the management account`,`These checks look for idle and unused resources; they do not break down spending by member account.`]],slot:1,evidence:[`ce-filtering|For example, you can use the Linked Account and Services filters to identify the member account that spent the most money on Amazon EC2.`,`consolidated-billing|Easy tracking – You can track the charges across multiple accounts and download the combined cost and usage data.`]}),e({id:`network-cost-audit-003`,building:`network-cost-audit`,bullets:[`4.4-K1`,`4.4-K2`],d:2,stem:`Three teams share one account and one VPC. Each team has tagged its NAT gateways and load balancers with a team tag. Finance wants a monthly breakdown of these network costs by team in the Billing and Cost Management console. Which TWO actions meet these requirements with the LEAST effort? (Choose two.)`,correct:[[`Activate the team tag as a cost allocation tag`,`A tag must be activated before it can appear in Cost Explorer or on a cost allocation report.`],[`Group the costs by the team tag in AWS Cost Explorer`,`Cost Explorer can filter and group costs by tag, which gives the cost per team.`]],wrong:[[`Turn on consolidated billing for the account`,`Consolidated billing combines the bills of several accounts and does not split the costs of one account by team.`],[`Enable VPC Flow Logs on the VPC and publish them to Amazon S3`,`Flow logs record IP traffic information and do not report the cost of each team.`],[`Create an AWS Budgets budget that sends an alert to the finance team every month`,`A budget sends alerts at a threshold and does not produce a cost breakdown by team.`]],slots:[0,3],evidence:[`cost-alloc-tags|You must activate both types of tags separately before they can appear in Cost Explorer or on a cost allocation report.`,`ce-filtering|With Cost Explorer, you can filter how you view your AWS costs by one or more of the following values: API operation Availability Zone (AZ) Billing entity Charge type Include all Instance type Legal entity Linked account Platform Product attribute Purchase option Region Resources Service Tag Tenancy Usage type Usage type group`]}),t({id:`network-cost-audit-004`,building:`network-cost-audit`,bullets:[`4.4-K2`,`4.4-S5`],d:2,stem:`A company runs a workload in three Availability Zones in one Region, and the data transfer charges are higher than expected. The team wants to see in which Availability Zone most of the traffic is and which usage types drive the cost, using an existing AWS tool with the LEAST effort. Which solution meets these requirements?`,correct:[`Open AWS Cost Explorer and filter and group the costs by Availability Zone and usage type`,`Cost Explorer shows which Availability Zone most of the traffic is in and can be refined with filters and grouping, such as usage type.`],wrong:[[`Set up AWS Budgets with a cost threshold for each Availability Zone`,`A budget alerts when a threshold is reached; it does not show which zone or usage type causes the cost.`],[`Turn on the Cost and Usage Report and write queries over the files to total the cost per zone`,`This can give the data but needs setup and query work, while Cost Explorer already shows it in the console.`],[`Review the Trusted Advisor idle resource checks for the three Availability Zones`,`These checks find idle resources and do not break the data transfer cost down by zone or usage type.`]],slot:2,evidence:[`ce-filtering|You can use Cost Explorer to see which service you use the most, which Availability Zone (AZ) most of your traffic is in, and which member account uses AWS the most.`,`ce-filtering|You can continue refining your cost analysis by using multiple filters, grouping your data by filter type, and choosing Advanced Options tab options.`]}),t({id:`network-cost-audit-005`,building:`network-cost-audit`,bullets:[`4.4-K2`],d:1,stem:`A company wants an email warning when its forecasted monthly spending on AWS is going to exceed a fixed amount, so that it can act before the month ends. Which AWS tool meets this requirement with the LEAST effort?`,correct:[`AWS Budgets, with a cost budget and a notification for forecasted spend`,`A cost budget sets a spending limit and can alert on actual or forecasted spend, sending notifications by email or an SNS topic.`],wrong:[[`AWS Cost Explorer, by opening its charts at the end of each week`,`Cost Explorer is for viewing and analyzing costs and does not send alerts at a threshold.`],[`AWS Cost and Usage Report, delivered daily to an Amazon S3 bucket`,`The report delivers detailed cost data files and does not send a warning when a limit is forecast to be passed.`],[`AWS Trusted Advisor, by reading the cost optimization checks each month`,`Trusted Advisor recommends savings and does not warn about a spending limit being forecast to be exceeded.`]],slot:3,evidence:[`budgets-managing|Cost budgets: Set spending limits for services and receive alerts when costs approach or exceed your defined threshold.`,`budgets-managing|You can choose to be alerted for both actual (after accruing) and forecasted (before accruing) spends.`]}),t({id:`network-cost-audit-006`,building:`network-cost-audit`,bullets:[`4.4-K2`],d:3,stem:`Analysts at a company must find out which usage types, such as data transfer between Availability Zones and NAT gateway data processing, drive the network charges. They need every line item of the AWS costs, and they want to answer the question with SQL queries. The company does not want to run or manage a database cluster for this. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an AWS Cost and Usage Report that delivers to an Amazon S3 bucket, and query it with Amazon Athena`,`The report holds line items by product and usage type in a bucket the company owns, and Athena runs SQL on those files with no cluster to manage.`],wrong:[[`Create an AWS Cost and Usage Report and load it into an Amazon Redshift provisioned cluster that the company manages`,`This works, but it needs a cluster to run and manage, which the company wants to avoid.`],[`Use AWS Cost Explorer and group the costs by usage type each month`,`Cost Explorer is an interactive console view and does not give analysts every line item to query with SQL.`],[`Create an AWS Budgets cost budget for each usage type with notifications to an Amazon SNS topic`,`A budget tracks spending against a limit and sends alerts; it does not provide line items to query.`]],slot:0,evidence:[`cur-what-is|Each report contains line items for each unique combination of AWS products, usage type, and operation that you use in your AWS account.`,`cur-what-is|You can download your report from the Amazon S3 console, query the report using Amazon Athena, or upload the report into Amazon Redshift or Quick.`,`cur-what-is|AWS Cost and Usage Reports (AWS CUR) contains the most comprehensive set of cost and usage data available.`]}),t({id:`network-cost-audit-007`,building:`network-cost-audit`,bullets:[`4.4-S5`],d:2,stem:`A company is reviewing an existing workload that has been running for two years. The team suspects that some NAT gateways, VPC interface endpoints and Elastic IP addresses no longer carry traffic or are not attached to anything, and it wants to find them with the LEAST effort. The company has a Business Support plan. Which solution meets these requirements?`,correct:[`Review the AWS Trusted Advisor cost optimization checks for idle and unassociated network resources`,`Trusted Advisor has cost checks for idle NAT gateways, inactive VPC interface endpoints and unassociated Elastic IP addresses.`],wrong:[[`Enable VPC Flow Logs for the whole VPC and analyze the records for resources with no traffic`,`Flow logs add logging charges and analysis work, while a Trusted Advisor check already reports these resources.`],[`Create a cost budget in AWS Budgets for each resource type and wait for an alert`,`A budget alerts on spending thresholds and does not list resources that are idle or unattached.`],[`Group the costs by Availability Zone in AWS Cost Explorer and delete the most expensive resources`,`Cost Explorer shows spending by zone and does not identify which resources are idle, so busy resources could be deleted.`]],slot:1,evidence:[`trusted-advisor-cost-checks|A NAT Gateway is considered to be inactive if no data (0 bytes) was processed in the last 30 days.`,`trusted-advisor-cost-checks|A VPC interface endpoint is considered to be inactive if it has no data processed in the last 30 days.`,`trusted-advisor-cost-checks|Checks for Elastic IP addresses (EIPs) that are not associated with a running Amazon Elastic Compute Cloud (Amazon EC2) instance.`]}),e({id:`network-cost-audit-008`,building:`network-cost-audit`,bullets:[`4.4-S5`],d:3,stem:`A company reviews a workload whose single NAT gateway has high data processing charges. The team wants to find out which traffic flows go through the NAT gateway and how much data it sends out, using services that capture traffic information. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Enable VPC Flow Logs for the VPC and analyze the records for traffic through the NAT gateway`,`Flow logs capture information about the IP traffic going to and from network interfaces in the VPC, which shows the flows.`],[`Review the BytesOutToDestination metric of the NAT gateway in Amazon CloudWatch`,`This metric is the number of bytes sent out through the NAT gateway to the destination, which shows how much data leaves.`]],wrong:[[`Review the idle NAT gateway check in AWS Trusted Advisor`,`The check finds NAT gateways that are idle, and this gateway is busy, so the check does not show which flows use it.`],[`Create an AWS Cost and Usage Report and total the NAT gateway charge`,`The report gives the cost line items but contains no information about which flows the traffic belongs to.`],[`Set an AWS Budgets cost budget for the NAT gateway with an email alert`,`A budget warns about spend at a threshold and does not reveal which flows or how much data pass through.`]],slots:[1,4],evidence:[`vpc-flow-logs|VPC Flow Logs is a feature that enables you to capture information about the IP traffic going to and from network interfaces in your VPC.`,`vpc-nat-metrics|BytesOutToDestination The number of bytes sent out through the NAT gateway to the destination.`]}),t({id:`network-cost-audit-009`,building:`network-cost-audit`,bullets:[`4.4-K2`],d:2,tags:[`mock-reserve`],stem:`A company has seasonal traffic, so its spending on data transfer changes a lot from month to month and no fixed limit fits. The company wants to be alerted when spending departs from its normal pattern, without setting a fixed monthly spending limit. Which AWS feature meets this requirement with the LEAST effort?`,correct:[`AWS Cost Anomaly Detection, with an alert subscription`,`It uses machine learning models to detect anomalous spend patterns, taking weekly or monthly seasonality into account, so no fixed monthly limit is needed.`],wrong:[[`AWS Budgets, with a cost budget set to a fixed monthly amount`,`A fixed amount does not fit seasonal spending, so it would alert falsely in busy months and miss spikes in quiet ones.`],[`AWS Cost and Usage Report, delivered to Amazon S3 and reviewed each week`,`The report delivers data files and does not alert on spending that departs from a normal pattern.`],[`AWS Cost Explorer, by filtering the data transfer costs every morning`,`Cost Explorer is a manual view and does not send alerts when spending changes.`]],slot:2,evidence:[`cost-anomaly|AWS Cost Anomaly Detection is a feature that uses machine learning models to detect and alert on anomalous spend patterns in your deployed AWS services.`,`cost-anomaly|You can evaluate your spend patterns using machine learning methods to minimize false positive alerts.`,`cost-anomaly|For example, you can evaluate weekly or monthly seasonality and natural growth.`]})],g=[t({id:`retention-records-001`,building:`retention-records`,bullets:[`4.3-K4`],d:1,stem:`A development team runs an Amazon RDS for MySQL DB instance that is rebuilt from scripts every night. Nobody ever restores it, and the team wants to stop paying for backup storage for this instance. Which change meets this requirement with the LEAST effort?`,correct:[`Set the backup retention period of the DB instance to 0`,`A backup retention period of 0 disables automated backups, so the instance no longer creates backup storage.`],wrong:[[`Set the backup retention period of the DB instance to one day`,`One day still creates automated backups every day, so backup storage continues.`],[`Take a manual snapshot of the DB instance every night and keep only the latest one`,`Manual snapshots are extra work and still occupy backup storage until someone deletes them.`],[`Create an AWS Backup plan that backs up the DB instance every night with a short lifecycle`,`This adds a second set of backups and storage instead of removing the backup storage the team is paying for.`]],slot:0,evidence:[`rds-backup-retention|You can set the backup retention period of a DB instance to between 0 and 35 days.`,`rds-backup-retention|Setting the backup retention period to 0 disables automated backups.`]}),t({id:`retention-records-002`,building:`retention-records`,bullets:[`4.3-K4`],d:2,stem:`An Amazon RDS for PostgreSQL DB instance has a backup retention period of seven days, yet the backup storage cost keeps growing. The team finds three years of monthly manual snapshots that nobody needs. Which action reduces the cost with the LEAST effort?`,correct:[`Delete the manual snapshots that are no longer needed`,`Manual snapshots are not subject to the backup retention period and do not expire, so they stay until someone deletes them.`],wrong:[[`Lower the backup retention period of the DB instance to one day`,`The retention period applies to automated backups, so the manual snapshots would stay and keep costing money.`],[`Wait for the snapshots to expire when they pass the retention period`,`Snapshots do not expire, so they would remain and continue to count toward backup storage.`],[`Turn off automated backups on the DB instance by setting the retention period to 0`,`This removes the automated backups the team still needs for point-in-time recovery and leaves the old manual snapshots in place.`]],slot:1,evidence:[`rds-snapshot-create|Unlike automated backups, manual snapshots aren't subject to the backup retention period.`,`rds-snapshot-create|Snapshots don't expire.`,`rds-automated-backups|Your Amazon RDS backup storage for each AWS Region is composed of the automated backups and manual DB snapshots for that Region.`]}),t({id:`retention-records-003`,building:`retention-records`,bullets:[`4.3-K4`],d:2,stem:`A regulation requires a company to keep daily backups of an Amazon RDS for MySQL database for 90 days. The company wants to meet the rule with the LEAST operational overhead and no custom scripts. Which solution meets these requirements?`,correct:[`Create an AWS Backup plan with a daily rule that deletes each backup after 90 days and assign the DB instance to it`,`A backup plan retains backups for its resources according to the plan, and it is not limited to the retention range of the DB instance.`],wrong:[[`Set the backup retention period of the DB instance to 90 days`,`The retention period of a DB instance can be set only between 0 and 35 days, so 90 days is not possible.`],[`Set the backup retention period to 35 days and accept the shorter retention`,`This keeps backups for 35 days, which does not meet the 90 days the regulation requires.`],[`Run an AWS Lambda function every day that creates a manual snapshot and another that deletes old ones`,`This needs custom code to write and operate, which the company wants to avoid.`]],slot:2,evidence:[`rds-backup-retention|You can set the backup retention period of a DB instance to between 0 and 35 days.`,`backup-plans|You can assign resources to backup plans, and AWS Backup automatically backs up and retains backups for those resources according to the backup plan.`,`backup-what-is|Amazon Relational Database Service (Amazon RDS) Amazon RDS database instances (including all database engines); Multi-Availability Zone clusters`]}),t({id:`retention-records-004`,building:`retention-records`,bullets:[`4.3-K4`],d:3,stem:`A company is retiring an Amazon RDS for MariaDB DB instance that has a backup retention period of 14 days. If a problem with the final data is found, the company wants to be able to restore the database, for 14 days after it is deleted, to any point in time up to the deletion, and it does not want to pay for backups beyond that. Which approach meets these requirements MOST cost-effectively?`,correct:[`Delete the DB instance and choose to retain automated backups`,`Retained automated backups are saved for the full retention period, so restores are possible for 14 days and then the backups end.`],wrong:[[`Delete the DB instance and have Amazon RDS create a final DB snapshot, then keep the snapshot`,`A snapshot is a single point in time and does not expire, so it cannot restore to any point up to the deletion and keeps costing money after 14 days.`],[`Create a read replica of the DB instance before deleting it, and keep the replica running for 14 days`,`A replica is a running DB instance that is billed while it exists, and it holds only the current data, not earlier points in time.`],[`Raise the retention period to 35 days before deleting the DB instance and choose to retain automated backups`,`The backups would then be kept for 35 days, which is longer than the 14 days the company wants to pay for.`]],slot:3,evidence:[`rds-automated-backups|If you choose to retain automated backups when you delete a DB instance, the automated backups are saved for the full retention period.`,`rds-automated-backups|If you don't choose Retain automated backups when you delete a DB instance, all automated backups are deleted with the DB instance.`,`rds-automated-backups|If necessary, you can recover your DB instance to any point in time during the backup retention period.`,`rds-automated-backups|Manual snapshots are not deleted when an instance is deleted.`]}),t({id:`retention-records-005`,building:`retention-records`,bullets:[`4.3-S1`],d:1,stem:`A company runs an Amazon RDS for PostgreSQL DB instance. After a bad deployment it must be able to restore the database to any moment during the last seven days, and it wants the LOWEST backup cost and effort. Which solution meets these requirements?`,correct:[`Keep automated backups with a seven-day retention period and use point-in-time recovery`,`RDS uploads transaction logs to Amazon S3 every five minutes, so any moment in the retention period can be restored without extra snapshots.`],wrong:[[`Run a script that takes a manual snapshot every hour and deletes the ones older than seven days`,`Hourly snapshots only restore to the top of each hour, need a script to run, and store many more backups.`],[`Create an AWS Backup rule that takes one backup every day and keeps each for seven days`,`A daily backup restores only to the time of each backup, so up to a day of changes could be lost.`],[`Enable a Multi-AZ deployment so that the standby holds the earlier state of the database`,`A standby copies changes as they happen and protects availability; it does not keep earlier states for restoring to a past time.`]],slot:3,evidence:[`rds-pitr|RDS uploads transaction logs for DB instances to Amazon S3 every five minutes.`,`rds-automated-backups|If necessary, you can recover your DB instance to any point in time during the backup retention period.`]}),t({id:`retention-records-006`,building:`retention-records`,postGuide:[`backup-hourly-frequency`],bullets:[`4.3-S1`],d:2,stem:`A company uses an AWS Backup rule that backs up an Amazon DynamoDB table every hour and keeps each backup for 30 days. The business has confirmed that it can lose at most 24 hours of data, and the 30-day retention is required. The company wants to cut backup storage cost. Which change meets the requirements MOST cost-effectively?`,correct:[`Change the backup frequency of the rule to once a day and keep the 30-day retention`,`A daily backup still meets the 24-hour data-loss limit and creates far fewer backups to store for 30 days.`],wrong:[[`Keep the hourly frequency and reduce the retention of each backup to one day`,`This breaks the required 30-day retention.`],[`Keep the hourly rule and lock the backup vault in compliance mode`,`A vault lock prevents deletion of backups and adds no savings; the number of stored backups stays the same.`],[`Change the backup frequency to once every 30 days so that only one backup is stored`,`A backup every 30 days could lose up to 30 days of data, which breaks the 24-hour limit.`]],slot:0,evidence:[`dr-options|How often you run your backup will determine your achievable recovery point (which should align to meet your RPO).`,`backup-create-plan|In the backup frequency menu, choose how often you want this plan to create a backup.`]}),e({id:`retention-records-007`,building:`retention-records`,bullets:[`4.3-K4`,`4.3-S1`],d:3,stem:`A company runs a production Amazon RDS for MariaDB DB instance. The company must be able to restore to any point in time in the last 14 days and must keep one copy of the database from each quarter-end for two years. The company wants the LOWEST backup storage cost. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Set the backup retention period to 14 days and use point-in-time recovery for the recent restores`,`Automated backups with transaction logs cover any moment in the last 14 days without keeping backups for longer than needed.`],[`Take a manual snapshot at each quarter-end and delete each snapshot when it is two years old`,`Manual snapshots are not subject to the retention period, so they stay for the two years until they are deleted.`]],wrong:[[`Set the backup retention period to 35 days so that the quarter-end copies are covered`,`This pays to store 21 more days of automated backups and still cannot keep copies for two years.`],[`Take a manual snapshot every hour and delete each one after 14 days`,`Hourly snapshots store many more backups than needed because point-in-time recovery already covers the last 14 days.`],[`Set the backup retention period to 0 and rely on the manual snapshots only`,`This disables automated backups, so restores to any point in time in the last 14 days are no longer possible.`]],slots:[2,4],evidence:[`rds-backup-retention|You can set the backup retention period of a DB instance to between 0 and 35 days.`,`rds-snapshot-create|Unlike automated backups, manual snapshots aren't subject to the backup retention period.`,`rds-pitr|RDS uploads transaction logs for DB instances to Amazon S3 every five minutes.`]}),t({id:`retention-records-008`,building:`retention-records`,bullets:[`4.3-K4`,`4.3-S1`],d:2,stem:`A company stores Amazon RDS backups in an AWS Backup vault. Some recovery points have their retention set to "Always", but the policy requires keeping backups for one year. The company is about to lock the vault in compliance mode, as its policy requires, and wants to avoid unintended storage costs. What should the company do BEFORE locking the vault?`,correct:[`Change the retention of those recovery points to one year, then lock the vault`,`Recovery points set to Always are retained forever once the lock's grace time expires, so the retention must be set first to stop the storage cost.`],wrong:[[`Lock the vault now and leave the retention at Always, since the lock enforces the one-year rule`,`Once the grace time expires, recovery points set to Always are retained forever and cannot be altered or deleted, so storage costs would never stop.`],[`Lock the vault in governance mode instead and let administrators delete the backups later`,`The policy requires compliance mode, which governance mode does not provide, and switching modes would not correct the retention setting.`],[`Delete the backup plan after the vault is locked so that no new recovery points are created`,`Deleting the plan stops new backups but does not remove the existing recovery points or change their retention.`]],slot:1,evidence:[`backup-vault-lock|For example, ensure there are no recovery points with a retention period set to "Always"—once the grace time expires, these recovery points will be retained forever and cannot be altered or deleted.`,`backup-vault-lock|During grace time, you can still remove the vault lock and change the lock configuration.`]}),t({id:`retention-records-009`,building:`retention-records`,bullets:[`4.3-K4`],d:2,tags:[`mock-reserve`],stem:`A team runs a short-lived test Amazon Aurora MySQL-Compatible cluster and wants to keep automated backup storage as low as possible. Which backup retention setting meets this requirement?`,correct:[`Set the backup retention period of the DB cluster to the minimum of one day`,`Aurora accepts a backup retention period from 1 to 35 days, so one day is the shortest period it keeps.`],wrong:[[`Set the backup retention period of the DB cluster to 0 days`,`For an Aurora DB cluster the retention period is 1 to 35 days, so a value of 0 is not available.`],[`Set the backup retention period of the DB cluster to 35 days`,`This keeps the longest period of backups, which is the opposite of the lowest storage.`],[`Leave the retention as it is and delete the automated backups by hand each night`,`This relies on manual work and the automated backups are still created for the retention period.`]],slot:0,evidence:[`aurora-backups|You can specify a backup retention period from 1–35 days when you create or modify or restore a DB cluster.`]})],_=[t({id:`route-tariff-001`,building:`route-tariff`,bullets:[`4.4-K6`],d:1,tags:[`trap:peering-tgw-privatelink`],stem:`A company has an application VPC and a shared-tools VPC in the same Region and the same account. Instances in the two VPCs must talk to each other over private IP addresses. No other network will join in the future. Which solution is the LOWEST cost?`,correct:[`A VPC peering connection between the two VPCs with routes added to both route tables`,`There is no charge to create a VPC peering connection, and the instances communicate using private IP addresses.`],wrong:[[`An AWS Transit Gateway with one attachment for each VPC and routes in both route tables`,`A transit gateway is charged hourly for each attachment and for the traffic it processes, which a two-VPC design does not need.`],[`An interface VPC endpoint in the application VPC for a service published from the shared-tools VPC`,`An interface endpoint is billed for each hour it is provisioned and each gigabyte processed, and it exposes one service, not the networks.`],[`Two NAT gateways that send the traffic between the VPCs through public IP addresses`,`This leaves the private path, and each NAT gateway is charged for every hour and for every gigabyte it processes.`]],slot:0,evidence:[`peering-what-is|There is no charge to create a VPC peering connection.`,`tgw-what-is|You are charged hourly for each attachment on a transit gateway, and you are charged for the amount of traffic processed on the transit gateway.`,`vpce-interface|You are billed for hourly usage and data processing charges.`]}),t({id:`route-tariff-002`,building:`route-tariff`,bullets:[`4.4-K6`],d:2,tags:[`placement-eligible`,`trap:peering-tgw-privatelink`],stem:`A company has 14 VPCs in one Region and one on-premises network connected by AWS Direct Connect. Every VPC must reach every other VPC and the on-premises network. The network team wants one place to manage routing and does not want to maintain a connection for each pair. Which solution is the MOST cost-effective at this size?`,correct:[`Attach all 14 VPCs and the Direct Connect connection to one AWS Transit Gateway`,`A transit gateway is a network transit hub for VPCs and on-premises networks, replacing many pairwise connections with one attachment per network.`],wrong:[[`Create a VPC peering connection between each pair of VPCs and route the on-premises network through one of them`,`Transitive peering relationships are not supported, so on-premises traffic cannot pass through one VPC, and the pairs multiply.`],[`Publish each VPC's services with AWS PrivateLink and create an interface endpoint in every other VPC`,`Interface endpoints are billed hourly in each zone plus per gigabyte, and they do not provide network-wide routing to on-premises.`],[`Create a Site-to-Site VPN connection from the on-premises network to each of the 14 VPCs`,`Each connection is charged per connection-hour plus data transfer, and the VPCs still could not reach each other through them.`]],slot:1,evidence:[`tgw-what-is|AWS Transit Gateway is a network transit hub used to interconnect virtual private clouds (VPCs) and on-premises networks.`,`peering-basics|You can create multiple VPC peering connections for each VPC that you own, but transitive peering relationships are not supported.`,`vpn-pricing|You also incur standard AWS data transfer charges for all data transferred via the VPN connection.`]}),e({id:`route-tariff-003`,building:`route-tariff`,bullets:[`4.4-K6`,`4.4-S3`],d:2,tags:[`placement-eligible`,`trap:peering-tgw-privatelink`],stem:`A test environment keeps a database in VPC A in one Region. Reporting instances in a peered VPC B in the same Region query it thousands of times per hour from a different Availability Zone. A batch analytics tier in a peered VPC C in a second Region also queries it heavily. The bill shows data transfer charges on both peering connections. There is no residency or recovery reason for the layout, and the environment does not need to survive a zone failure. Which TWO actions lower these charges the MOST? (Choose two.)`,correct:[[`Launch the reporting instances in the same Availability Zone as the database instances`,`Data transfer over a peering connection that stays within an Availability Zone is free, even between accounts.`],[`Move the batch analytics tier into the Region of the database`,`Charges apply for transfer over peering connections that cross Regions, so keeping the tier in the same Region removes those charges.`]],wrong:[[`Replace the peering connection with an AWS Transit Gateway that has an attachment for each VPC`,`A transit gateway is charged hourly for each attachment and for the traffic processed, which adds charges.`],[`Move the database VPC to a third Region so that neither tier shares a Region with it`,`Charges apply for transfer over peering connections that cross Regions, so this adds cost.`],[`Create an interface VPC endpoint in each zone for the database and send the queries through it`,`Interface endpoints are billed hourly in each zone plus for every gigabyte processed, which adds charges.`]],slots:[2,3],evidence:[`peering-what-is|All data transfer over a VPC peering connection that stays within an Availability Zone is free, even if it's between different accounts.`,`peering-what-is|Charges apply for data transfer over VPC peering connections that cross Availability Zones and Regions.`,`tgw-what-is|You are charged hourly for each attachment on a transit gateway, and you are charged for the amount of traffic processed on the transit gateway.`]}),t({id:`route-tariff-004`,building:`route-tariff`,bullets:[`4.4-S3`],d:3,tags:[`placement-eligible`,`trap:gateway-vs-interface-endpoints`],stem:`An analytics cluster in private subnets in one Region reads several terabytes a day from an Amazon S3 bucket that is in a different Region. The reads pass through a NAT gateway, and its per-gigabyte processing charge is high. The data is read many times after it is written. Which solution is the MOST cost-effective?`,correct:[`Replicate the data to a bucket in the cluster's Region and read it through a gateway VPC endpoint for Amazon S3`,`A gateway endpoint has no additional charge, and it can carry S3 traffic for a bucket in the same Region, which removes the NAT gateway from the reads.`],wrong:[[`Create a gateway VPC endpoint for Amazon S3 and keep reading from the bucket in the other Region`,`Traffic destined for S3 in a different Region goes to the internet gateway because prefix lists are specific to a Region, so the NAT path stays.`],[`Create a NAT gateway in every Availability Zone of the cluster and spread the reads across them`,`More gateways add hourly charges, and every gigabyte of the reads is still processed by a NAT gateway.`],[`Create an interface VPC endpoint for Amazon S3 in the cluster's Region and keep reading from the bucket in the other Region`,`An interface endpoint is billed for each hour in each zone and for each gigabyte processed, and the reads still cross Regions.`]],slot:2,evidence:[`vpce-gateway|Traffic that's destined for the service (Amazon S3 or DynamoDB) in a different Region goes to the internet gateway because prefix lists are specific to a Region.`,`vpce-gateway|There is no additional charge for using gateway endpoints.`,`vpce-gateway|Gateway VPC endpoints provide reliable connectivity to Amazon S3 and DynamoDB without requiring an internet gateway or a NAT device for your VPC.`,`s3-replication-requirements|For example, inter-Region data transfer charges vary depending on the Regions that you choose.`,`privatelink-pricing|You will be billed for each hour that your VPC endpoint remains provisioned in each Availability Zone, irrespective of the state of its association with the service (learn more).`]}),t({id:`route-tariff-005`,building:`route-tariff`,bullets:[`4.4-S3`],d:2,tags:[`placement-eligible`],stem:`A company runs its application servers in one Region and its relational database in a second Region because of a past acquisition. Each page view makes many database calls over an inter-Region VPC peering connection, and data transfer charges grow with traffic. There is no residency or disaster recovery reason for the split. Which change is the MOST cost-effective?`,correct:[`Move the application servers into the same Region as the database so the calls no longer cross Regions`,`Charges apply for data transfer over peering connections that cross Regions, so keeping the chatty tier next to its database removes them.`],wrong:[[`Add a transit gateway in each Region, peer the two transit gateways and attach both VPCs`,`A transit gateway is charged hourly for each attachment and for the traffic it processes, on top of the cross-Region traffic.`],[`Move the database to a DB instance class with more network bandwidth`,`More bandwidth does not change the charges, because the calls still cross Regions.`],[`Replace the peering connection with a Site-to-Site VPN connection between the two Regions`,`The standard data transfer charges still apply to the traffic through the VPN connection, and the VPN connection adds its own charges.`]],slot:3,evidence:[`peering-what-is|Charges apply for data transfer over VPC peering connections that cross Availability Zones and Regions.`,`tgw-what-is|You are charged hourly for each attachment on a transit gateway, and you are charged for the amount of traffic processed on the transit gateway.`,`vpn-pricing|You also incur standard AWS data transfer charges for all data transferred via the VPN connection.`]}),t({id:`route-tariff-006`,building:`route-tariff`,bullets:[`4.4-S4`],d:2,tags:[`placement-eligible`,`trap:cloudfront-vs-global-accelerator`],stem:`A publisher serves popular product images from an Amazon S3 bucket directly to users around the world. The same images are requested repeatedly, and the company wants to reduce request load and data transfer cost on the origin and improve latency. Which solution is the MOST cost-effective?`,correct:[`Put an Amazon CloudFront distribution in front of the bucket and serve the repeated requests from edge locations`,`Cached content is served from edge locations, so fewer requests reach the origin, and transfer from AWS origins to CloudFront is waived.`],wrong:[[`Enable Amazon S3 Transfer Acceleration on the bucket and have users download through the accelerate endpoint`,`Transfer Acceleration can add data transfer charges and does not serve repeated requests from a cache, so every request still reaches the bucket.`],[`Replicate the bucket to several Regions and have each user choose the nearest bucket through a separate URL`,`This multiplies storage and replication, and every request still reaches an origin bucket instead of an edge cache.`],[`Create an Amazon Route 53 latency record for each of the replicated buckets in the other Regions`,`Latency routing only sends users to a Region, so it needs replicas to exist and caches nothing at the edge.`]],slot:0,evidence:[`cloudfront-pricing|you'll see fewer requests hitting your origin servers, databases, and other AWS services that charge based on usage—reducing your costs.`,`cloudfront-pricing|Data transfer between CloudFront and your AWS origins is automatically waived when serving traffic through CloudFront, giving you a monthly price for both CloudFront delivery and your AWS origin’s data transfer costs to CloudFront.`,`s3-transfer-acceleration|When you use Transfer Acceleration, additional data transfer charges might apply.`]}),e({id:`route-tariff-007`,building:`route-tariff`,bullets:[`4.4-S4`,`4.4-K7`],d:3,tags:[`placement-eligible`],stem:`A company serves a static website from Amazon S3 through Amazon CloudFront at its root domain, example.com, using Amazon Route 53. It ships new versions of its scripts and images every week and wants to keep origin load and per-use charges as low as possible. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a Route 53 alias record at the root domain that points to the CloudFront distribution`,`An alias record can be created at the zone apex, and Route 53 does not charge for alias queries to AWS resources.`],[`Put a version identifier in file names and use a long cache duration`,`A long cache duration reduces origin load, and with versioning there is no wait for expiry and no invalidation to pay for.`]],wrong:[[`Create a CNAME record at the root domain that points to the CloudFront distribution`,`A CNAME cannot be created at the zone apex, and Route 53 charges for CNAME queries.`],[`Invalidate every path in the distribution each time a version is released`,`Invalidation has a charge that versioned file names avoid, and it empties the cache that reduces the origin load.`],[`Set the cache duration to zero so that every request checks the origin for the latest version`,`Every request would then reach the origin, which raises its load and usage charges.`]],slots:[0,4],evidence:[`route53-alias|Unlike a CNAME record, you can create an alias record at the top node of a DNS namespace, also known as the zone apex.`,`route53-alias|Route 53 doesn't charge for alias queries to AWS resources.`,`cloudfront-versioning|With versioning, you don't have to wait for an object to expire before CloudFront begins to serve a new version of it, and you don't have to pay for object invalidation.`,`cloudfront-expiration|A longer duration also reduces the load on your origin.`]}),t({id:`route-tariff-008`,building:`route-tariff`,bullets:[`4.4-S4`],d:2,tags:[`placement-eligible`],stem:`A company delivers downloads through Amazon CloudFront. Almost all users are in North America and Europe, and the company accepts slightly higher latency for the few users elsewhere. The distribution uses the default settings. The company wants to lower the CloudFront cost with the LEAST effort. Which solution meets these requirements?`,correct:[`Change the distribution to a price class that serves objects from only the CloudFront Regions where most users are`,`The price class setting lets you choose the maximum price you want to pay, instead of the default of serving from edge locations in all Regions.`],wrong:[[`Enable CloudFront Origin Shield for the origin of the distribution`,`Origin Shield adds a caching layer in front of the origin with its own charge per 10,000 requests, and it does not limit the edge locations that serve the users.`],[`Create a second distribution for each continent and publish a separate domain name for each of them`,`Several distributions need extra management, and a price class on one distribution already limits the locations used.`],[`Turn off caching on the distribution so that edge locations do not hold copies of the downloads`,`Caching reduces requests to the origin, so turning it off increases origin usage instead of lowering cost.`]],slot:1,evidence:[`cloudfront-settings|Choose the price class that corresponds with the maximum price that you want to pay for CloudFront service.`,`cloudfront-settings|By default, CloudFront serves your objects from edge locations in all CloudFront Regions.`,`cloudfront-origin-shield|For more information about the charge per 10,000 requests for Origin Shield, see CloudFront Pricing.`]}),t({id:`route-tariff-009`,building:`route-tariff`,bullets:[`4.4-K7`],d:1,tags:[],stem:`A company hosts its public site in an Amazon S3 bucket configured for static hosting and wants the root domain, example.com, to resolve to it using Amazon Route 53. The company also wants to avoid per-query charges for these DNS lookups. Which record type meets these requirements?`,correct:[`An alias record at the zone apex that points to the AWS resource`,`An alias record can sit at the zone apex and route traffic to selected AWS resources such as S3 buckets, and alias queries to AWS resources are not charged.`],wrong:[[`A CNAME record at the zone apex that points to the S3 website endpoint name`,`A CNAME cannot be created at the zone apex, and Route 53 charges for CNAME queries.`],[`An A record that lists the current IP addresses of the S3 endpoint, updated by hand`,`The addresses are not managed by the company, so a hand-maintained list breaks and adds work.`],[`A weighted record that sends all of the weight to a CNAME for the www subdomain`,`This still depends on a CNAME for the lookups, and CNAME queries are charged.`]],slot:2,evidence:[`route53-alias|Alias records let you route traffic to selected AWS resources, such as CloudFront distributions and Amazon S3 buckets.`,`route53-alias|Route 53 doesn't charge for alias queries to AWS resources.`,`route53-alias|Route 53 charges for CNAME queries.`]}),t({id:`route-tariff-010`,building:`route-tariff`,bullets:[`4.4-K7`,`4.4-S3`],d:3,tags:[`placement-eligible`,`trap:cloudfront-vs-global-accelerator`],stem:`A company runs the same API in two Regions, each behind an Application Load Balancer. Users are worldwide and should reach the Region with the best latency. The clients use DNS names, do not need static IP addresses, and can tolerate DNS-based failover. The company wants the LOWEST additional networking cost. Which solution meets these requirements?`,correct:[`Amazon Route 53 latency alias records for the two load balancers, with health checks for failover`,`Latency routing sends users to the Region with the best latency, and alias records that point to load balancers do not incur a DNS query charge or an accelerator fee.`],wrong:[[`An AWS Global Accelerator accelerator with the two load balancers as the endpoints of one listener`,`An accelerator is charged a fixed hourly fee plus a premium over standard data transfer, for static IP benefits the clients do not need.`],[`Amazon Route 53 failover routing with the first Region as primary and the second as the standby`,`Failover routing sends all users to the primary Region, so users near the second Region do not get the best latency.`],[`Amazon Route 53 weighted records with equal weights for the two load balancers`,`Weighted routing splits traffic in the proportions specified and does not consider the latency of the user.`]],slot:3,evidence:[`route53-routing|Latency routing policy – Use when you have resources in multiple AWS Regions and you want to route traffic to the Region that provides the best latency.`,`route53-routing|Failover routing policy – Use when you want to configure active-passive failover.`,`route53-pricing|Alias A/AAAA records that are mapped to the following AWS services do not incur a charge: Elastic Load Balancers`,`ga-pricing|For every accelerator that is provisioned (both enabled and disabled), you are charged a fixed hourly fee and an incremental charge over your standard Data Transfer rates, also called a Data Transfer-Premium fee (DT-Premium).`,`route53-routing|Weighted routing policy – Use to route traffic to multiple resources in proportions that you specify.`]}),t({id:`route-tariff-011`,building:`route-tariff`,bullets:[`4.4-S3`,`4.4-S4`],d:2,tags:[`mock-reserve`,`trap:cloudfront-vs-global-accelerator`],stem:`A company serves a catalog of mostly unchanging product pages and images from an Application Load Balancer to users in many countries through an AWS Global Accelerator accelerator. The clients do not need fixed IP addresses and nothing else depends on the accelerator. Most of the bill comes from requests that reach the load balancer and the application behind it, and most of those requests fetch the same pages. The company wants to cut the cost of the delivery path. Which change is the MOST cost-effective?`,correct:[`Replace the accelerator with an Amazon CloudFront distribution that caches the catalog and uses the load balancer as its origin`,`Edge caching means fewer requests reach the origin, and the fixed hourly fee and transfer premium of the accelerator are no longer paid.`],wrong:[[`Keep the accelerator and add a second accelerator in front of the load balancer for the busiest countries`,`Every accelerator is charged a fixed hourly fee plus a premium over standard data transfer, so cost rises.`],[`Keep the accelerator and add a Network Load Balancer behind it to cache the pages for repeat requests`,`A load balancer does not cache content, and it adds an hourly charge and capacity-unit charges.`],[`Replace the accelerator with an Amazon Route 53 latency record that points at the load balancer in one Region for all the countries`,`Latency routing only chooses which Region answers the request, so the repeated pages still reach the origin on every request and the origin charges that dominate the bill continue.`]],slot:1,evidence:[`ga-pricing|For every accelerator that is provisioned (both enabled and disabled), you are charged a fixed hourly fee and an incremental charge over your standard Data Transfer rates, also called a Data Transfer-Premium fee (DT-Premium).`,`cloudfront-pricing|you'll see fewer requests hitting your origin servers, databases, and other AWS services that charge based on usage—reducing your costs.`,`route53-latency|If your application is hosted in multiple AWS Regions, you can improve performance for your users by serving their requests from the AWS Region with the lowest latency.`]})],v=[t({id:`service-selection-bureau-001`,building:`service-selection-bureau`,bullets:[`4.3-K9`,`4.3-S3`],d:1,tags:[`placement-eligible`],stem:`An online retailer needs a store for shopping-cart contents. Each cart is read and written by a customer ID key, with no joins or complex queries. Traffic is unpredictable, and the team wants the lowest cost and the fewest servers to manage. Which database is the MOST cost-effective?`,correct:[`Amazon DynamoDB, a serverless key-value NoSQL database`,`AWS suggests DynamoDB for key-value workloads such as shopping carts, and as a serverless database it has no DB instance to size, run or pay for while idle.`],wrong:[[`Amazon RDS for MySQL as a Multi-AZ DB instance sized for the peak load`,`The DB instance and its standby run and are billed all the time, and the team would size and manage them.`],[`An Amazon Aurora cluster with one writer instance and two reader instances`,`The three instances are billed while they run, and the cart lookups need no relational features.`],[`An Amazon Redshift cluster that loads the cart data every hour`,`Redshift is a data warehouse for analytical queries, not a store for key-value reads and writes.`]],slot:0,evidence:[`database-decision|Amazon DynamoDB Key-value Use for workloads such as session stores or shopping carts.`,`dynamodb-what-is|Amazon DynamoDB is a serverless, fully managed, distributed NoSQL database with single-digit millisecond performance at any scale.`]}),t({id:`service-selection-bureau-002`,postGuide:[`dynamodb-price-cut-2024`],building:`service-selection-bureau`,bullets:[`4.3-S3`],d:2,tags:[`placement-eligible`],stem:`A ticketing API stores its data in an Amazon DynamoDB table that handles a high, steady request rate around the clock. Traffic grows slowly, and finance can forecast the required capacity for months ahead. The company wants the lowest cost and predictable billing. Which configuration is the MOST cost-effective?`,correct:[`Provisioned capacity mode on the Standard table class, with DynamoDB auto scaling to follow the slow growth`,`AWS points to provisioned capacity for steady workloads with predictable growth, and the charge for provisioned capacity gives cost predictability.`],wrong:[[`On-demand capacity mode on the Standard table class so that the table adapts to each request and each read or write is paid for as it is made`,`On-demand mode is built for workloads whose traffic needs no capacity planning, but this workload is steady and forecastable.`],[`Provisioned capacity mode sized for the busiest day of the year and left unchanged all year`,`Provisioned capacity is charged by the hour whether it is used or not, so the unused capacity is paid for.`],[`Provisioned capacity mode on the Standard-IA table class to lower the cost of the table`,`Standard-IA raises throughput costs and suits tables where storage is the dominant cost, but here throughput dominates.`]],slot:1,evidence:[`dynamodb-capacity|You can choose to use provisioned capacity if you have steady workloads with predictable growth, and if you can reliably forecast capacity requirements for your application.`,`dynamodb-capacity|You'll be charged based on the hourly read and write capacity you have provisioned, not how much of that provisioned capacity you actually consumed.`,`dynamodb-table-classes|The DynamoDB Standard table class offers lower throughput costs than DynamoDB Standard-IA and is the most cost-effective option for tables where throughput is the dominant cost.`]}),t({id:`service-selection-bureau-003`,building:`service-selection-bureau`,bullets:[`4.3-S3`],d:1,tags:[`placement-eligible`],stem:`A development team uses an Amazon DynamoDB table that receives requests for only a few hours each week, and nobody can predict when. The company does not want to pay for throughput capacity while the table is idle. Which capacity mode meets this requirement?`,correct:[`On-demand capacity mode`,`With on-demand mode there is no charge for throughput while the table gets zero traffic, and each request is paid for only when it is made.`],wrong:[[`Provisioned capacity mode with a fixed number of read and write capacity units`,`Provisioned capacity is charged by the hour whether it is used or not, so the idle weeks are paid for.`],[`Provisioned capacity mode with auto scaling and a minimum capacity above zero`,`The minimum capacity is provisioned and charged hourly even while no requests arrive.`],[`An Amazon RDS for MySQL DB instance that stays running between the busy hours`,`A running DB instance is billed for its instance hours whether anyone sends requests or not.`]],slot:2,evidence:[`dynamodb-ondemand|If you are driving zero traffic to your table, then with on-demand, you are not charged for any throughput.`,`dynamodb-capacity|You'll be charged based on the hourly read and write capacity you have provisioned, not how much of that provisioned capacity you actually consumed.`]}),t({id:`service-selection-bureau-004`,postGuide:[`aurora-serverless-v2-scale-to-zero`],postGuideKey:[`aurora-serverless-v2-scale-to-zero`],building:`service-selection-bureau`,bullets:[`4.3-S3`],d:3,tags:[`placement-eligible`,`trap:aurora-vs-rds`],stem:`A company runs a PostgreSQL-based reporting application that is busy on weekdays, light in the evenings, and unused overnight and on weekends. Peaks are unpredictable. The application uses joins across many tables, so it needs a relational database. The company wants the database bill to follow actual use. Which solution is the MOST cost-effective?`,correct:[`Aurora PostgreSQL with Aurora Serverless and a minimum capacity of zero ACUs, so that it pauses when idle`,`Aurora Serverless adjusts capacity to demand, and a zero minimum capacity lets it scale down to zero ACUs when nobody uses the database.`],wrong:[[`Amazon RDS for PostgreSQL as a Multi-AZ DB instance sized for the weekday peak with a reserved DB instance`,`The peak-sized instance and standby are paid for through the idle evenings, nights and weekends.`],[`Aurora PostgreSQL with Aurora Serverless and a nonzero minimum capacity so the database never pauses`,`With a nonzero minimum the database never pauses, so the minimum capacity is paid for overnight and on weekends.`],[`Amazon DynamoDB in on-demand mode with the report queries rewritten as scans`,`The application needs joins across many tables, which a key-value NoSQL database does not provide, so the application would have to be redesigned.`]],slot:3,evidence:[`aurora-serverless-how|Scaling to Zero In recent Aurora MySQL and Aurora PostgreSQL versions, Aurora serverless writers and readers can scale all the way down to zero ACUs.`,`aurora-serverless-how|You can choose whether to allow this behavior by specifying a zero or nonzero value for the minimum capacity.`,`aurora-serverless|Aurora serverless is an on-demand, autoscaling configuration for Amazon Aurora.`]}),t({id:`service-selection-bureau-005`,postGuide:[`aurora-serverless-v2-scale-to-zero`],building:`service-selection-bureau`,bullets:[`4.3-S3`],d:3,tags:[`placement-eligible`,`trap:savings-plans-ri-spot`],stem:`A payment-processing application uses a relational database on Amazon RDS for MySQL. The database runs at high, steady utilization around the clock, and the company expects the same instance size for the next three years. Which approach is the MOST cost-effective?`,correct:[`Run a provisioned RDS for MySQL DB instance and buy a reserved DB instance for the term`,`Reserved DB instances give a significant discount compared to on-demand DB instance pricing, and steady usage keeps the reserved capacity fully used.`],wrong:[[`Move to Aurora Serverless with a minimum capacity of zero ACUs so that it pauses when idle`,`The database is never idle, so there is no unused compute to avoid paying for, and a steady load gains nothing from pausing.`],[`Move the data to Amazon DynamoDB in on-demand mode and rewrite the application`,`The application is relational, so it would need a rewrite, and a steady high load is not the idle-capacity case on-demand mode is built for.`],[`Keep the DB instance on on-demand pricing and add an AWS Budgets alert for the monthly cost`,`The steady usage would stay at on-demand rates, and a budget alert warns about spend but does not lower it.`]],slot:0,evidence:[`rds-reserved|Reserved DB instances provide you with a significant discount compared to on-demand DB instance pricing.`,`aurora-serverless|Thus, Aurora serverless can help you to stay within budget and avoid paying for computer resources that you don't use.`]}),t({id:`service-selection-bureau-006`,building:`service-selection-bureau`,bullets:[`4.3-K9`,`4.3-S4`],d:2,stem:`A company keeps a fact table with several billion rows on a large Amazon RDS for PostgreSQL DB instance. Analysts run queries that each read only three columns of the table. The data is loaded in batches overnight, and there are no single-row updates. The DB instance is moved to a larger size every quarter just for these queries. Which change is the MOST cost-effective?`,correct:[`Move the table to an Amazon Redshift data warehouse, which stores table data in columns`,`Columnar storage cuts disk I/O and the data loaded from disk for analytic queries, and Redshift is the AWS option for analyzing massive amounts of data.`],wrong:[[`Move the DB instance to the next larger instance class again to speed up the queries`,`The workload would keep paying for ever larger instances to read whole rows for three columns.`],[`Move the table to Amazon DynamoDB and run the analytical queries as table scans`,`DynamoDB is suited to key-value access, and scanning billions of items for column queries is not an analytic design.`],[`Put an Amazon ElastiCache cluster in front of the database to cache the query results`,`A cache stores results and does not change how the large table is stored, so analysts running new queries still hit the database.`]],slot:1,evidence:[`redshift-columnar|Columnar storage for database tables is an important factor in optimizing analytic query performance, because it drastically reduces the overall disk I/O requirements.`,`redshift-columnar|It reduces the amount of data you need to load from disk.`,`database-decision|If you need to store and analyze massive amounts of data quickly and efficiently (a requirement that is typically met by an OLAP application), AWS offers Amazon Redshift.`]}),t({id:`service-selection-bureau-007`,building:`service-selection-bureau`,bullets:[`4.3-S4`],d:3,tags:[`placement-eligible`],stem:`A company records a high volume of sensor events in Amazon DynamoDB. Every write goes to the current month. The current month is read often, the previous month rarely, and older months almost never, but all data must stay available for occasional historical queries. Most of the stored bytes are in older months, while almost all of the read and write throughput is on the current month. Which design is the MOST cost-effective?`,correct:[`Use one table per month, keep the current month on the Standard table class, and switch older months to Standard-IA`,`The active table keeps cheaper throughput, while older tables that are rarely read move to the class that lowers storage cost.`],wrong:[[`Keep one table for all months and switch that whole table to the Standard-IA table class`,`The current month, which takes almost all the throughput, would pay the higher throughput rates of Standard-IA.`],[`Keep one table on the Standard class and turn on auto scaling for the write and read capacity of the single table that holds every month`,`Auto scaling follows throughput and does nothing about the storage cost of the old months.`],[`Move all sensor events into a Multi-AZ Amazon RDS DB instance and keep every month in one table`,`The company would pay for a DB instance and its standby and give up the serverless table, with no cut in storage cost.`]],slot:2,evidence:[`dynamodb-time-series|Keep the current (active) period on the DynamoDB Standard table class.`,`dynamodb-time-series|Switch a period's table to Standard-IA after it is no longer actively written to and is accessed infrequently, but you still need to retain its data`,`dynamodb-time-series|Create one table per period, provisioned with the required read and write capacity and the required indexes.`]}),t({id:`service-selection-bureau-008`,building:`service-selection-bureau`,bullets:[`4.3-S4`],d:2,stem:`A company keeps clickstream logs as large CSV files in Amazon S3. Analysts use Amazon Athena for queries that read only a few columns, and the queries are slow. The company wants faster queries without running a database cluster. Which change is the MOST cost-effective?`,correct:[`Convert the data to Apache Parquet with an Athena CTAS query and query the Parquet table`,`Parquet is a columnar format optimized for fast retrieval in analytical applications, and Athena stays serverless, so you still pay only for the queries you run.`],wrong:[[`Load the CSV files into a provisioned Amazon Redshift cluster and query them there`,`A provisioned Redshift cluster is one you create and manage yourself, and the company wants to avoid running a database cluster.`],[`Load the CSV files into an Amazon RDS for MySQL DB instance and query them there`,`A DB instance class sets the capacity of the DB instance, which the company would size and pay for, and a DB instance is not one of the listed ways to convert CSV into a columnar format.`],[`Store the CSV files in Amazon EFS and query the file system from Athena`,`Athena queries data directly in Amazon S3, so storing the files in EFS adds a service and leaves the CSV data in its original format.`]],slot:3,evidence:[`athena-columnar|Apache Parquet and ORC are columnar storage formats that are optimized for fast retrieval of data and used in AWS analytical applications.`,`athena-columnar|To convert your existing raw data from other storage formats to Parquet or ORC, you can run CREATE TABLE AS SELECT (CTAS) queries in Athena and specify a data storage format as Parquet or ORC, or use the AWS Glue Crawler.`,`athena-what-is|Athena SQL and Apache Spark on Amazon Athena are serverless, so there is no infrastructure to set up or manage, and you pay only for the queries you run.`,`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`,`redshift-what-is|If you prefer to manage your Amazon Redshift resources manually, you can create provisioned clusters for your data querying needs.`,`rds-instance-class|The DB instance class determines the computation and memory capacity of an Amazon RDS DB instance.`,`rds-what-is|When you use Amazon RDS, you can choose to use on-demand DB instances or reserved DB instances.`,`athena-columnar|Options for easily converting source data such as JSON or CSV into a columnar format include using CREATE TABLE AS queries or running jobs in AWS Glue.`]}),e({id:`service-selection-bureau-009`,building:`service-selection-bureau`,bullets:[`4.3-K9`,`4.3-S4`],d:3,tags:[`placement-eligible`],stem:`A company is choosing databases for three workloads. A session store looks up records by session ID at very high request rates with unpredictable spikes. A month-end reporting system runs analytical queries over billions of rows of historical sales. A payroll system needs transactions and joins across many related tables. Which TWO choices are the MOST cost-effective? (Choose two.)`,correct:[[`Store the sessions in Amazon DynamoDB`,`AWS suggests DynamoDB for key-value workloads such as session stores, and its serverless design suits unpredictable spikes.`],[`Run the month-end reporting on Amazon Redshift`,`Redshift is the AWS option for storing and analyzing massive amounts of data, with columnar storage for analytic queries.`]],wrong:[[`Store the sessions in Amazon Redshift`,`Redshift is an analytic warehouse, not a store for high-rate key lookups.`],[`Run the month-end reporting on Amazon DynamoDB`,`DynamoDB suits key-value access, not analytical queries over billions of rows.`],[`Run the payroll system on Amazon DynamoDB`,`The payroll system needs joins across many related tables, which suit a relational database.`]],slots:[0,3],evidence:[`database-decision|Amazon DynamoDB Key-value Use for workloads such as session stores or shopping carts.`,`database-decision|If you need to store and analyze massive amounts of data quickly and efficiently (a requirement that is typically met by an OLAP application), AWS offers Amazon Redshift.`,`database-decision|There are two high-level categories of AWS OLTP databases—relational and non-relational.`]}),e({id:`service-selection-bureau-010`,postGuide:[`dynamodb-price-cut-2024`],building:`service-selection-bureau`,bullets:[`4.3-S3`],d:3,tags:[`placement-eligible`],stem:`An Amazon DynamoDB table holds years of order history. The table currently uses on-demand capacity mode. Reads and writes are low and steady, the capacity needs can be forecast, and storage has become the dominant cost of the table. Which TWO changes can lower the cost of the table? (Choose two.)`,correct:[[`Change the table to the DynamoDB Standard-IA table class`,`Standard-IA is optimized for tables where storage is the dominant cost, such as infrequently accessed order history.`],[`Use provisioned capacity mode with auto scaling sized from the forecast`,`AWS says provisioned capacity may be better for steady, predictable throughput that you can forecast, and you are charged for the capacity you provision rather than what the table consumes.`]],wrong:[[`Keep the Standard table class and add a replica table in a second Region`,`A replica table is a second table in another Region, and you pay for the resources your application uses on each replica table, so it adds cost instead of lowering it.`],[`Copy the order history into a Multi-AZ Amazon RDS DB instance`,`A Multi-AZ DB instance deployment has one standby DB instance that provides failover support, but doesn't serve read traffic. Copying the history there adds a second store and does not change the table's table class or capacity mode.`],[`Keep the Standard table class and keep the table in on-demand mode`,`The table already uses on-demand mode, so this is no change, and it does not use the capacity forecast or the steady traffic.`]],slots:[1,2],evidence:[`dynamodb-table-classes|The DynamoDB Standard-Infrequent Access (DynamoDB Standard-IA) table class is optimized for tables where storage is the dominant cost.`,`dynamodb-capacity|You can choose to use provisioned capacity if you have steady workloads with predictable growth, and if you can reliably forecast capacity requirements for your application.`,`dynamodb-pricing|Provisioned capacity may be better if you: Have existing applications with steady and predictable throughput patterns`,`dynamodb-pricing|Can forecast capacity requirements`,`dynamodb-pricing|You’ll be charged based on the hourly read and write capacity provisioned, and not how much your application has consumed.`,`dynamodb-pricing|Global tables: Now assume you choose to create a disaster recovery replica table in the US West (Oregon) Region.`,`dynamodb-pricing|When using global tables, you pay only for the resources your application uses on each replica table.`,`rds-multi-az|A Multi-AZ DB instance deployment has one standby DB instance that provides failover support, but doesn't serve read traffic.`,`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`,`rds-what-is|When you use Amazon RDS, you can choose to use on-demand DB instances or reserved DB instances.`]}),t({id:`service-selection-bureau-011`,building:`service-selection-bureau`,bullets:[`4.3-K9`,`4.3-S3`],d:2,tags:[`mock-reserve`],stem:`A SaaS company gives each of its many customers a separate small relational database on its own provisioned instance. Most customers use their database only briefly and at unpredictable times each day. The company wants to keep the relational engine and lower the cost of idle capacity. Which solution is the MOST cost-effective?`,correct:[`Move the databases to Aurora Serverless so that capacity follows the use of each customer`,`Aurora serverless adjusts capacity automatically to demand and is valuable for multitenant databases with highly variable workloads, avoiding paying for unused compute.`],wrong:[[`Keep one provisioned Multi-AZ RDS DB instance per customer and add more storage as each database grows over time`,`Each instance and its standby is still billed through the many idle hours.`],[`Buy three-year reserved DB instances for every customer database`,`A commitment is paid for whether or not the rarely used databases run, so the idle capacity remains.`],[`Move every customer to its own Amazon DynamoDB table and rewrite the application`,`The company wants to keep the relational engine, and the move would force a rewrite.`]],slot:0,evidence:[`aurora-serverless|This type of automation is especially valuable for multitenant databases, distributed databases, development and test systems, and other environments with highly variable and unpredictable workloads.`,`aurora-serverless|Thus, Aurora serverless can help you to stay within budget and avoid paying for computer resources that you don't use.`]}),t({id:`service-selection-bureau-012`,building:`service-selection-bureau`,bullets:[`4.3-S4`],d:2,tags:[`mock-reserve`],stem:`A company stores device telemetry in an Amazon DynamoDB table with a timestamp in each item. Only the most recent 30 days of data are ever used, and the table keeps growing. The company wants old items removed automatically at the lowest cost. Which solution meets these requirements?`,correct:[`Turn on time to live (TTL) for the table and store an expiration time in each item`,`DynamoDB deletes expired items automatically without consuming write throughput, so no delete requests are paid for.`],wrong:[[`Run a nightly script that scans the table and deletes the old items with delete requests`,`The scan and the deletes consume read and write capacity that the company pays for.`],[`Switch the table to the Standard-IA table class and keep all the items`,`The old items would stay and keep growing the table, and only their storage rate would change.`],[`Copy the old items into a Multi-AZ Amazon RDS DB instance each night and delete them from the table`,`The company would run and pay for a DB instance and still need delete requests for the old items.`]],slot:1,evidence:[`dynamodb-ttl|DynamoDB automatically deletes expired items within a few days of their expiration time, without consuming write throughput.`]})],y=[t({id:`storage-market-001`,building:`storage-market`,bullets:[`4.1-K4`],d:1,tags:[`trap:ebs-efs-fsx`],stem:`A company is lifting and shifting an enterprise application that runs on Windows servers and stores its data on SMB file shares. The company wants fully managed file storage with the LEAST operational overhead. Which storage service should the company use?`,correct:[`Amazon FSx for Windows File Server`,`It provides fully managed Windows file servers on a native Windows file system, with SMB access to the file shares.`],wrong:[[`Amazon EFS, mounted on the Windows servers`,`EFS is an NFS file system, and using it with Windows-based Amazon EC2 instances is not supported.`],[`Amazon EBS volumes, attached to one Windows server and shared by the other servers`,`An EBS volume is block storage attached to an instance and is not a shared SMB file service.`],[`Amazon S3, accessed as a network drive by the application`,`S3 is object storage reached through an API, not an SMB file share for the existing application.`]],slot:0,evidence:[`fsx-windows|Amazon FSx for Windows File Server provides fully managed Microsoft Windows file servers, backed by a fully native Windows file system.`,`fsx-windows|FSx for Windows File Server has the features, performance, and compatibility to easily lift and shift enterprise applications to the AWS Cloud.`,`efs-what-is|Amazon EFS supports the Network File System version 4 (NFSv4.1 and NFSv4.0) protocol, so the applications and tools that you use today work seamlessly with Amazon EFS.`]}),t({id:`storage-market-002`,building:`storage-market`,bullets:[`4.1-K4`,`4.1-K11`],d:2,tags:[`placement-eligible`],stem:`A company serves a read-heavy marketing website of HTML, images, and video from three Amazon EC2 web servers that each use a large Amazon EBS volume. Traffic varies a lot, and the company wants to stop paying for idle servers and provisioned volumes while keeping the site available. Which storage choice is MOST cost-effective?`,correct:[`Store the site content in Amazon S3 and serve it with S3 static website hosting`,`Object storage is well suited to read-heavy workloads such as web hosting, and serverless storage can act as a static website, which removes the need for web servers.`],wrong:[[`Move the content to an Amazon EFS file system that all three servers mount`,`The servers and the provisioned compute would keep running, so the company would still pay for idle web servers.`],[`Enlarge each Amazon EBS volume and add a fourth server for peak traffic`,`This adds more provisioned volumes and servers, which is the opposite of removing idle capacity.`],[`Create an Amazon FSx for Lustre file system and serve the site from it`,`Lustre is built for workloads where speed matters, such as HPC, not for serving a website, so the web servers would still deliver the content.`]],slot:1,evidence:[`storage-decision|Object storage provides easy access to data through an application programming interface (API) over the internet and is well-suited to read-heavy workloads (such as streaming applications and services).`,`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`,`storage-decision|Read-heavy workloads such as content distribution, web hosting, big data analytics, and ML workflows.`,`waf-perf-dp|For example, serverless storage services can act as static websites (removing the need for web servers) and event services can host code.`,`fsx-lustre|You use Lustre for workloads where speed matters, such as machine learning, high performance computing (HPC), video processing, and financial modeling.`]}),t({id:`storage-market-003`,postGuide:[`efs-archive-class`],postGuideKey:[`efs-archive-class`],building:`storage-market`,bullets:[`4.1-K9`],d:2,tags:[`placement-eligible`,`trap:ebs-efs-fsx`],stem:`A company shares 80 TB of project files with Linux servers over NFS. Most files are not touched for months and are read only a few times a year. The applications cannot be changed and must keep using the NFS mount. Which solution is MOST cost-effective?`,correct:[`Use Amazon EFS with lifecycle management that moves files not accessed for a period to the Archive storage class`,`Archive is lower-cost storage for file data accessed only a few times a year, and the applications keep their NFS mount.`],wrong:[[`Move the files to Amazon S3 and rewrite the applications to call the S3 API`,`The applications cannot be changed, and S3 is accessed through an API rather than an NFS mount.`],[`Attach a Cold HDD (sc1) volume to each server and copy the files to every volume`,`An EBS volume is attached to one instance, so the files would no longer be shared between servers.`],[`Use Amazon FSx for Lustre and keep all files in its file system`,`It is aimed at speed-critical workloads such as HPC and does not apply to rarely read project files.`]],slot:2,evidence:[`storage-decision|For cold, rarely accessed file data, use the Amazon EFS Archive storage class.`,`storage-decision|This class provides lower-cost storage for data that you access only a few times a year.`,`efs-lifecycle|Transition time is based on when the files were last accessed in the Standard storage class.`]}),t({id:`storage-market-004`,postGuide:[`efs-archive-class`],building:`storage-market`,bullets:[`4.1-K9`,`4.1-S10`],d:3,tags:[`placement-eligible`],stem:`A mobile app downloads 250 TB of photos through an HTTPS service that reads them from an Amazon EFS file system. No one mounts the file system apart from that service, and the developers can change the service to read the photos through the Amazon S3 API. Photos go cold for weeks and then become popular again, and nobody can predict which ones. The company wants storage cost to follow the access pattern without retrieval fees. Which solution meets these requirements MOST cost-effectively?`,correct:[`Move the photos to Amazon S3 with the S3 Intelligent-Tiering storage class`,`S3 Intelligent-Tiering is the ideal storage class when you want to optimize storage costs for data that has unknown or changing access patterns, and it moves objects between tiers with no retrieval fees.`],wrong:[[`Keep the photos on Amazon EFS and use lifecycle management to move them to Archive`,`By default, files that are not accessed for 90 days move to Archive and remain there when they are accessed, so the storage cost does not follow an unpredictable pattern automatically.`],[`Copy the photos to a large General Purpose SSD (gp3) volume and resize it as the library grows`,`A gp3 volume is block storage attached to an instance, and with Amazon EBS you pay only for what you provision, so the cost follows the size you provision rather than the access pattern.`],[`Move the photos to Amazon S3 with the S3 Standard-IA storage class`,`Standard-IA is designed for long-lived, infrequently accessed data, so it does not adapt automatically as photos become popular again, and Amazon S3 charges a retrieval fee for these objects.`]],slot:3,evidence:[`storage-decision|For example, use Amazon S3 Intelligent-Tiering for object data, or the FSx Intelligent-Tiering storage class for Amazon FSx for OpenZFS and Amazon FSx for Lustre workloads.`,`s3-storage-classes|There are no retrieval fees for S3 Intelligent-Tiering.`,`s3-storage-classes|S3 Intelligent-Tiering is the ideal storage class when you want to optimize storage costs for data that has unknown or changing access patterns.`,`ebs-what-is|With Amazon EBS, you pay only for what you provision.`,`efs-lifecycle|By default, files are not moved back to the Standard storage class, and they remain in the IA or Archive storage class when they are accessed.`,`s3-storage-classes|Amazon S3 charges a retrieval fee for these objects, so they are most suitable for infrequently accessed data.`,`s3-storage-classes|The S3 Standard-IA and S3 One Zone-IA storage classes are designed for long-lived and infrequently accessed data.`,`s3-storage-classes|S3 Intelligent-Tiering (INTELLIGENT_TIERING) is an Amazon S3 storage class that's designed to optimize storage costs by automatically moving data to the most cost-effective access tier`,`efs-lifecycle|By default, files that are not accessed in the Standard storage class for 90 days are transitioned in to the Archive storage class.`,`ebs-what-is|Amazon Elastic Block Store (Amazon EBS) provides scalable, high-performance block storage`,`ebs-what-is|After you attach a volume to an instance, you can use it in the same way you would use a local hard drive attached to a computer, for example to store files or to install applications.`]}),t({id:`storage-market-005`,building:`storage-market`,bullets:[`4.1-K11`],d:1,tags:[`trap:ebs-efs-fsx`],stem:`A company runs a self-managed relational database on a single Amazon EC2 instance. The database needs low-latency, durable storage that is attached directly to that one instance. Which type of storage and service should the company choose?`,correct:[`Block storage with Amazon EBS`,`Block storage is high-performance storage direct-attached to a compute instance, suited to databases on single instances.`],wrong:[[`Object storage with Amazon S3`,`S3 is reached through an API over the internet and is not direct-attached low-latency storage for database files.`],[`File storage with Amazon EFS`,`EFS is a shared NFS file system, which adds network file access that a database on one instance does not need.`],[`File storage with Amazon FSx for Lustre`,`It is meant for speed-critical workloads such as HPC and machine learning, not for the disk of a single database server.`]],slot:0,evidence:[`storage-decision|Block storage offers high-performance storage that is direct-attached to a compute instance with low-latency access, making it suitable for applications that require fast and consistent I/O operations.`,`storage-decision|Storage services or tools Block Applications requiring low-latency, high-performance durable storage attached to single Amazon EC2 instances or containers, such as databases and general-purpose local instance storage.`]}),t({id:`storage-market-006`,building:`storage-market`,bullets:[`4.1-S10`],d:2,tags:[`placement-eligible`],stem:`A company's on-premises network-attached storage is almost full. Its applications access the files over industry-standard file protocols, and the company does not want to buy more on-premises storage or change the applications. Which solution is the MOST cost-effective?`,correct:[`Deploy an Amazon S3 File Gateway on premises so that the applications keep a file protocol while data is stored in S3`,`An S3 File Gateway integrates with existing applications through standard file protocols and is a cost-effective alternative to on-premises storage.`],wrong:[[`Move the files to Amazon S3 and rewrite the applications to call the S3 API`,`The applications must not change, and S3 itself is accessed through an API, not through a file protocol.`],[`Attach Amazon EBS volumes to the on-premises servers`,`EBS volumes are storage that you attach to Amazon EC2 instances, not to servers in a data center.`],[`Create an Amazon FSx for Lustre file system and point the applications at it over the internet`,`It is built for speed-critical workloads such as HPC, not as a drop-in for general on-premises file storage.`]],slot:1,evidence:[`sgw-file-s3|A S3 File Gateway simplifies file storage in Amazon S3, integrates to existing applications through industry-standard file system protocols, and provides a cost-effective alternative to on-premises storage.`,`ebs-what-is|Amazon EBS volumes — These are storage volumes that you attach to Amazon EC2 instances.`]}),e({id:`storage-market-007`,building:`storage-market`,bullets:[`4.1-K4`],d:3,tags:[`placement-eligible`],stem:`A machine learning team keeps 300 TB of training data in Amazon S3. A cluster of Amazon EC2 instances needs to read that data through a high-speed shared file system during multi-day training runs, and the results must end up back in the bucket. The team wants the LEAST operational overhead. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create an Amazon FSx for Lustre file system linked to the S3 bucket`,`Lustre is for workloads where speed matters, such as machine learning, and a linked bucket's objects are presented as files.`],[`Export the results from the file system to the S3 bucket by using an FSx for Lustre data repository export`,`Results are written to the linked data repository by using automatic export or export data repository tasks, so they end up in the bucket.`]],wrong:[[`Copy the full data set to a General Purpose SSD (gp3) volume on each training instance`,`This duplicates 300 TB on every instance, and the instances would not share a single file system.`],[`Create an Amazon EFS file system and copy the data from S3 before every run`,`EFS is not aimed at speed-critical machine learning work, and the copy before each run adds manual steps.`],[`Have each instance download the objects to its own disk with the S3 API before training`,`This copies the data per instance and gives no shared, high-speed file system.`]],slots:[0,3],evidence:[`fsx-lustre|You use Lustre for workloads where speed matters, such as machine learning, high performance computing (HPC), video processing, and financial modeling.`,`fsx-lustre|When linked to an Amazon S3 bucket, an FSx for Lustre file system transparently presents S3 objects as files.`,`fsx-lustre|The file system also makes it possible for you to write file system data back to S3.`,`fsx-lustre-dra|At the same time, you can write results to your data repositories by using automatic export or export data repository tasks.`]}),t({id:`storage-market-008`,building:`storage-market`,bullets:[`4.1-K4`,`4.1-S10`],d:2,tags:[`placement-eligible`,`trap:ebs-efs-fsx`],stem:`A company is migrating NetApp file servers to AWS. Linux applications reach the data over NFS and Windows applications reach the same data over SMB at the same time, and the company wants to keep NetApp ONTAP features with the LEAST operational overhead. Which storage solution meets these requirements?`,correct:[`Amazon FSx for NetApp ONTAP`,`It is a fully managed service built on the ONTAP file system and supports NFS and SMB, including concurrent multi-protocol access to the same data.`],wrong:[[`Amazon EFS`,`EFS supports NFS, and using it with Microsoft Windows-based Amazon EC2 instances is not supported, so the SMB clients are not served.`],[`Amazon FSx for Windows File Server`,`It serves SMB file shares and does not give the NFS clients concurrent access or the NetApp ONTAP features.`],[`Amazon S3 with the applications changed to use the S3 API`,`Both application sets would need to be rewritten, and S3 is not an NFS and SMB file system with ONTAP features.`]],slot:2,evidence:[`storage-decision|Amazon FSx for NetApp ONTAP supports both NFS and SMB protocols, including concurrent multi-protocol access to the same data.`,`fsx-ontap|Amazon FSx for NetApp ONTAP is a fully managed service that provides highly reliable, scalable, high-performing, and feature-rich file storage built on NetApp's popular ONTAP file system.`]}),e({id:`storage-market-009`,building:`storage-market`,bullets:[`4.1-K9`],d:3,tags:[`placement-eligible`],stem:`A content team shares a Linux file system over NFS. Its throughput needs grow with the amount of data stored, and most files are not read for months. The company wants the LOWEST cost without changing the applications. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Use Bursting throughput on an Amazon EFS file system`,`Bursting throughput is recommended for workloads that require throughput that scales with the amount of storage, and it avoids the charge for throughput enabled on a Provisioned file system.`],[`Turn on EFS lifecycle management to move unused files to the Infrequent Access (IA) storage class`,`Files that are not accessed move to the lower-cost IA class, which is cost-optimized for data that is accessed only a few times each quarter.`]],wrong:[[`Use Provisioned throughput set to the peak the team expects`,`You are charged for the throughput enabled for the file system, even when the peak is rarely reached.`],[`Keep every file in the Standard storage class so that all reads are served from one class`,`Rarely read files would stay in the Standard class instead of moving to the IA class, which is cost-optimized for data accessed only a few times each quarter.`],[`Move the files to Amazon S3 and have the applications call the S3 API`,`The applications must not change, and calling the Amazon S3 API would change them.`]],slots:[2,4],evidence:[`efs-performance|Bursting throughput – Use Bursting throughput when you want throughput that scales with the amount of storage in your file system.`,`efs-performance|Bursting throughput is recommended for workloads that require throughput that scales with the amount of storage in your file system.`,`efs-performance|For file systems using Provisioned throughput, you are charged for the amount of throughput enabled for the file system.`,`efs-lifecycle|Transition into IA – Instructs lifecycle management when to move files in to the Infrequent Access (IA) storage class, which is cost-optimized for data that is accessed only a few times each quarter.`]}),t({id:`storage-market-010`,building:`storage-market`,bullets:[`4.1-K11`,`4.1-S10`],d:2,tags:[`placement-eligible`,`trap:ebs-efs-fsx`],stem:`A company runs Linux containers as Amazon ECS tasks on AWS Fargate in two Availability Zones. Every task must read and write the same persistent set of files through a mounted file system, and the company wants no storage capacity to provision and the LEAST operational overhead. Which storage solution meets these requirements?`,correct:[`Amazon EFS, mounted as a volume by the tasks`,`EFS provides shared, persistent file storage for Amazon ECS tasks that grows and shrinks automatically, and it needs no capacity provisioning.`],wrong:[[`An Amazon EBS volume attached to each task`,`An EBS volume is block storage attached to a task, so the tasks would not share one file system, and its capacity is still provisioned.`],[`Amazon S3, with the tasks writing objects through the API`,`The tasks need a file system mount, and S3 is object storage reached through an API.`],[`The temporary storage of each task, copied between tasks by a script`,`It is not shared between tasks and does not give persistent storage, and the script adds operational work.`]],slot:3,evidence:[`ecs-data-volumes|Amazon EFS volumes provide simple, scalable, and persistent shared file storage for use with your Amazon ECS tasks that grows and shrinks automatically as you add and remove files.`,`efs-what-is|Amazon Elastic File System (Amazon EFS) provides serverless, fully elastic file storage so that you can share file data without provisioning or managing storage capacity and performance.`]}),t({id:`storage-market-011`,building:`storage-market`,bullets:[`4.1-K9`,`4.1-S10`],d:2,tags:[`mock-reserve`],stem:`A company runs Linux application servers in several Availability Zones that must share one file system over NFS. Files are hot for a few weeks and then are rarely read. The company does not want to move files between tiers by hand. Which solution is the MOST cost-effective?`,correct:[`A Regional Amazon EFS file system with lifecycle management to the IA storage class`,`EFS is shared across Availability Zones, and lifecycle management moves files to the lower-cost IA class automatically, with no manual tiering.`],wrong:[[`An Amazon EBS Provisioned IOPS SSD volume with Multi-Attach enabled and extra size`,`Multi-Attach works only for instances in the same Availability Zone, and the volume keeps all data on costly storage with no automatic tiering.`],[`An Amazon FSx for Windows File Server file system`,`It serves SMB file shares for Windows workloads and does not fit Linux servers that use NFS.`],[`A Cold HDD (sc1) volume attached to one instance and shared by a script`,`A single volume is not a shared file system across zones, and it needs a size chosen up front.`]],slot:1,evidence:[`efs-what-is|Regional file systems (recommended) store data redundantly across multiple geographically separated Availability Zones within the same AWS Region.`,`efs-lifecycle|Transition into IA – Instructs lifecycle management when to move files in to the Infrequent Access (IA) storage class, which is cost-optimized for data that is accessed only a few times each quarter.`,`ebs-multi-attach|Amazon EBS Multi-Attach enables you to attach a single Provisioned IOPS SSD (io1 or io2) volume to multiple instances that are in the same Availability Zone.`]}),t({id:`storage-market-012`,building:`storage-market`,bullets:[`4.1-S10`],d:3,tags:[`mock-reserve`],stem:`A company keeps 200 TB of columnar data files on General Purpose SSD (gp3) volumes attached to a fleet of Amazon EC2 instances that run SQL queries for analysts. Analysts run ad hoc queries a few times a week, and the files do not need to be mounted by any application. The company wants to stop paying for volumes and instances that sit idle between queries. Which solution is the MOST cost-effective?`,correct:[`Store the files in Amazon S3 and query them in place with Amazon Athena`,`Athena queries data directly in S3 with standard SQL and is serverless, so nothing sits idle between queries.`],wrong:[[`Move the files to an Amazon EFS file system and mount it on the query instances`,`The query instances would keep running and idle between queries, and the files do not need a file system mount.`],[`Create an Amazon FSx for Lustre file system for the query fleet`,`It is built for speed-critical workloads, and both the file system and the fleet would still sit idle between queries.`],[`Change the volumes to Provisioned IOPS SSD (io2) to speed up the queries`,`It targets sustained IOPS and keeps the provisioned capacity and instances that are the cost problem.`]],slot:2,evidence:[`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`,`athena-what-is|Athena SQL and Apache Spark on Amazon Athena are serverless, so there is no infrastructure to set up or manage, and you pay only for the queries you run.`]})],b=[t({id:`throttle-lb-gate-001`,building:`throttle-lb-gate`,bullets:[`4.4-K3`],d:2,tags:[`placement-eligible`,`trap:alb-nlb-gwlb`],stem:`A company runs twelve small HTTP web services in one VPC. Each service has its own Application Load Balancer, and each balancer receives very little traffic. Requests can be told apart by the URL path. The company wants to cut load balancer costs without changing the services. Which solution is the MOST cost-effective?`,correct:[`Keep one Application Load Balancer and add listener rules that route each URL path to a target group for its service`,`An Application Load Balancer can route requests to different target groups based on the content of the traffic, so one balancer replaces twelve and only one hourly charge remains.`],wrong:[[`Replace each Application Load Balancer with a Network Load Balancer and register the same instances as targets`,`A Network Load Balancer is also charged for each hour it runs, so twelve balancers remain, and it does not route by URL path.`],[`Place a Gateway Load Balancer in front of the twelve Application Load Balancers to share the traffic between them across zones`,`Twelve Application Load Balancers would still run and be billed every hour, and a Gateway Load Balancer adds a thirteenth billed balancer.`],[`Reduce the number of registered targets behind each Application Load Balancer so that fewer capacity units are used`,`Each balancer is still charged for every hour or partial hour it is running, so twelve hourly charges remain whatever the target count.`]],slot:0,evidence:[`alb-intro|You can configure listener rules to route requests to different target groups based on the content of the application traffic.`,`elb-pricing|You are charged for each hour or partial hour that an Application Load Balancer is running.`]}),t({id:`throttle-lb-gate-002`,building:`throttle-lb-gate`,bullets:[`4.4-K3`],d:1,tags:[],stem:`A company has many test environments that have been shut down over the past year, but the load balancers that served them were never deleted. The company has a Business Support plan. A cloud engineer needs a built-in way to find load balancers that receive no traffic so that they can be removed. Which solution meets this requirement with the LEAST effort?`,correct:[`Review the Idle Load Balancers check in the cost optimization category of AWS Trusted Advisor`,`Trusted Advisor has a cost optimization check named Idle Load Balancers, and an idle load balancer is still running and so still accrues the hourly charge.`],wrong:[[`Create an AWS Budgets budget and wait for it to list the load balancers that have no traffic`,`A budget alerts on spend or usage thresholds; it does not list individual load balancers that are idle.`],[`Tag every load balancer with an owner and activate the tag as a cost allocation tag in billing`,`Cost allocation tags group costs by owner, but they do not show which load balancers receive no traffic.`],[`Move the accounts into one AWS Organizations organization so that the bills are combined`,`Consolidated billing combines the invoices of the accounts; it does not identify load balancers without traffic.`]],slot:2,evidence:[`trusted-advisor-cost-checks|Checks your Elastic Load Balancing configuration for load balancers that are idle.`,`trusted-advisor-cost-checks|Any load balancer that is configured accrues charges.`,`elb-pricing|You are charged for each hour or partial hour that an Application Load Balancer is running.`]}),t({id:`throttle-lb-gate-003`,building:`throttle-lb-gate`,bullets:[`4.4-K3`],d:3,tags:[`placement-eligible`,`trap:alb-nlb-gwlb`],stem:`A company runs a TCP-based messaging service behind a Network Load Balancer that spans three Availability Zones. Cross-zone load balancing was enabled when the service launched, and the bill shows charges for data transfer between Availability Zones. Each zone already hosts the same number of identical targets, and the company must keep the service available if one zone fails. Which change is the MOST cost-effective?`,correct:[`Disable cross-zone load balancing and keep an equal number of targets registered in each of the three zones`,`With cross-zone load balancing disabled, each node sends traffic only to targets in its own zone, which removes the cross-zone transfer charge, and the other zones still serve traffic if one fails.`],wrong:[[`Keep cross-zone load balancing enabled and register targets in only one Availability Zone to shorten the paths`,`A single zone of targets would make the service unavailable when that zone fails, which breaks the availability requirement.`],[`Replace the Network Load Balancer with a Gateway Load Balancer that has cross-zone load balancing enabled`,`A Gateway Load Balancer is built for traffic inspection appliances, and enabling cross-zone there would not remove the cross-zone charges.`],[`Enable cross-zone load balancing on a second Network Load Balancer and split the clients between the two balancers`,`A second balancer adds another hourly charge and still sends traffic across zones, so the transfer charges remain.`]],slot:1,evidence:[`elb-faqs|Yes, you will be charged for regional data transfer between Availability Zones with Network Load Balancer when cross-zone load balancing is enabled.`,`elb-how-it-works|When cross-zone load balancing is disabled, each load balancer node distributes traffic only across the registered targets in its Availability Zone.`]}),e({id:`throttle-lb-gate-004`,building:`throttle-lb-gate`,bullets:[`4.4-K3`],d:3,tags:[`placement-eligible`],stem:`A company runs 40 Application Load Balancers across its accounts. About half belong to projects that ended, and the rest each serve one small service with low traffic on the same domain. The company wants to lower the load balancer bill while keeping the live services available. Which TWO actions should the company take? (Choose two.)`,correct:[[`Delete the load balancers that the Idle Load Balancers check in Trusted Advisor reports`,`A load balancer that is not used still runs, and is therefore still charged for each hour it exists, so deleting the idle ones removes those charges.`],[`Consolidate the small live services behind a single Application Load Balancer that uses listener rules`,`Listener rules route requests to different target groups by content, so several services can share one hourly charge.`]],wrong:[[`Disable cross-zone load balancing on each Application Load Balancer to avoid data transfer charges between zones`,`AWS does not charge for the regional data transfer caused by cross-zone load balancing on an Application Load Balancer, so disabling it saves nothing on the bill.`],[`Replace each remaining Application Load Balancer with its own Gateway Load Balancer`,`A Gateway Load Balancer is billed per hour and per capacity unit as well, so the hourly charges remain and the traffic type is wrong.`],[`Create a second Application Load Balancer in every project to take part of the traffic`,`Each extra balancer adds a further hourly charge, which raises the bill instead of lowering it.`]],slots:[0,3],evidence:[`trusted-advisor-cost-checks|Checks your Elastic Load Balancing configuration for load balancers that are idle.`,`trusted-advisor-cost-checks|Any load balancer that is configured accrues charges.`,`alb-intro|You can configure listener rules to route requests to different target groups based on the content of the application traffic.`,`elb-faqs|Since cross-zone load balancing is always on with Application Load Balancer, you are not charged for this type of regional data transfer.`]}),t({id:`throttle-lb-gate-005`,building:`throttle-lb-gate`,bullets:[`4.4-K3`],d:2,tags:[`trap:alb-nlb-gwlb`],stem:`A company serves a web application through an Application Load Balancer in three Availability Zones. The zones hold different numbers of targets. A manager asks the team to turn off cross-zone load balancing on the Application Load Balancer to avoid charges for data transfer between zones. What is the MOST cost-effective recommendation?`,correct:[`Keep cross-zone load balancing as it is, because AWS does not charge for the regional data transfer it causes on an Application Load Balancer`,`There is no cross-zone charge to avoid, so turning it off would save nothing and would unbalance the zones that hold different numbers of targets.`],wrong:[[`Disable cross-zone load balancing on the target group so that each node serves only the targets in its own zone and keeps the data local`,`It can be disabled at the target group level, but there is no cross-zone charge to avoid, and with uneven target counts some targets would be overloaded.`],[`Switch to a Network Load Balancer, because it never charges for traffic that crosses Availability Zones`,`A Network Load Balancer charges for regional data transfer between zones when cross-zone load balancing is enabled.`],[`Move all targets into a single Availability Zone and keep the balancer in the other two zones`,`This makes the application depend on one zone and does not address a charge that the Application Load Balancer does not have.`]],slot:3,evidence:[`elb-faqs|Since cross-zone load balancing is always on with Application Load Balancer, you are not charged for this type of regional data transfer.`,`elb-how-it-works|With Application Load Balancers, cross-zone load balancing is always enabled at the load balancer level.`]}),t({id:`throttle-lb-gate-006`,building:`throttle-lb-gate`,bullets:[`4.4-S6`],d:2,tags:[`placement-eligible`],stem:`A company sells access to a data API through Amazon API Gateway. Each paying customer must be held to the request rate in its own plan, and one heavy customer must not slow the others. The company wants the solution with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Publish a REST API and attach usage plans with API keys so that each customer gets its own throttling target`,`A usage plan specifies who can access the API stages and sets the target request rate at which throttling starts, which limits each client separately.`],wrong:[[`Publish an HTTP API and set a default route throttling limit that applies to all callers of the stage`,`HTTP APIs have no per-client rate limiting, so one limit on the stage cannot hold each customer to its own plan.`],[`Publish a REST API and give each customer its own Lambda function with a different reserved concurrency`,`Reserved concurrency caps a function, not a customer, and running a function per customer adds management work.`],[`Ask AWS Support to raise the account-level throttle so that no customer can ever reach the limit`,`Account-level throttling is applied to all APIs in the account per Region and cannot hold each customer to a separate rate.`]],slot:0,evidence:[`apigw-http-vs-rest|Choose REST APIs if you need API management capabilities such as API keys and per-client rate limiting.`,`apigw-usage-plans|A usage plan specifies who can access one or more deployed API stages and methods—and optionally sets the target request rate to start throttling requests.`]}),t({id:`throttle-lb-gate-007`,postGuide:[`lambda-sqs-maximum-concurrency`],postGuideKey:[`lambda-sqs-maximum-concurrency`],building:`throttle-lb-gate`,bullets:[`4.4-S6`],d:2,tags:[`placement-eligible`],stem:`A retailer's checkout API on Amazon API Gateway invokes an AWS Lambda function that writes orders to a relational database with a limited number of connections. Marketing campaigns send short bursts of orders that overload the database. Orders must not be rejected, but they can be processed a few minutes later. The company wants to protect the database at the LOWEST additional cost. Which solution meets these requirements?`,correct:[`Send the orders to an Amazon SQS queue and set a maximum concurrency on the queue's Lambda event source`,`The queue holds the burst and the maximum concurrency limits how many function instances write at once, at no charge for the setting.`],wrong:[[`Configure throttling rate and burst limits on the API Gateway stage so that excess requests are rejected`,`Throttled requests are rejected, and the company needs every order to be accepted and processed later.`],[`Configure provisioned concurrency on the Lambda function so that it can absorb the burst of orders`,`Provisioned concurrency incurs additional charges and lets more function instances connect to the database instead of limiting them.`],[`Scale the database to a larger instance class so that it can accept the connections of the burst`,`A larger instance increases the cost permanently to serve bursts that are short and can be delayed.`]],slot:1,evidence:[`lambda-sqs-scaling|The maximum concurrency setting limits the number of concurrent instances of the function that an Amazon SQS event source can invoke.`,`lambda-sqs-scaling|There is no charge for configuring maximum concurrency on an Amazon SQS event source.`,`sqs-what-is|Scalability – Amazon SQS can process each buffered request independently, scaling transparently to handle any load increases or spikes without any provisioning instructions.`,`lambda-provisioned|Configuring provisioned concurrency incurs additional charges to your AWS account.`]}),t({id:`throttle-lb-gate-008`,building:`throttle-lb-gate`,bullets:[`4.4-S6`],d:2,tags:[`placement-eligible`],stem:`An account runs a critical order-processing Lambda function and a nightly report Lambda function. When the report function scales out, it uses so much of the account concurrency that order processing is throttled. The company wants to protect order processing at NO additional charge. Which solution meets this requirement?`,correct:[`Configure reserved concurrency on the report function to cap how many instances it can run at the same time`,`Reserved concurrency sets the maximum number of concurrent instances for the function and there is no charge for configuring it.`],wrong:[[`Configure provisioned concurrency on the order function so that it keeps a number of warm instances`,`Provisioned concurrency incurs charges, which fails the no-additional-charge requirement.`],[`Place the report function behind a REST API with caching enabled so that repeated calls are answered from the cache`,`Caching only reduces calls to an endpoint, and the nightly report would still be able to scale out and use up the concurrency.`],[`Increase the memory setting of the order function so that each invocation finishes sooner than before`,`This changes the cost of each invocation and does not stop the report function from consuming the shared concurrency.`]],slot:2,evidence:[`lambda-reserved|Reserved concurrency – This sets both the maximum and minimum number of concurrent instances allocated to your Event Function.`,`lambda-concurrency|There is no charge for configuring reserved concurrency for an Event Function.`,`lambda-concurrency|Configuring provisioned concurrency incurs charges to your AWS account.`]}),e({id:`throttle-lb-gate-009`,building:`throttle-lb-gate`,bullets:[`4.4-S6`],d:3,tags:[`placement-eligible`],stem:`A company exposes a product-catalog API on Amazon API Gateway. The same product requests arrive thousands of times each hour and each one reads from a database that charges by usage. Large customers also send more requests than their contracts allow. The company wants to lower backend usage and enforce each contract rate. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Use a REST API and enable API caching for the product requests so that repeats are answered by API Gateway`,`Caching reduces the number of calls made to the endpoint, so the usage-priced database is read less often.`],[`Create usage plans that give each large customer an API key and a contract request rate`,`A usage plan can begin throttling requests to the APIs based on defined limits, so each customer is held to its contract rate.`]],wrong:[[`Move the API to an HTTP API because it is offered at a lower price and includes caching`,`HTTP APIs are priced lower because they have minimal features, and caching and per-client limits are not available for them.`],[`Enable provisioned concurrency on the backend function so that it answers repeated requests faster`,`Provisioned concurrency adds charges and does not stop repeated requests from reaching the database.`],[`Increase the stage-level throttle for all callers so that large customers are never refused`,`Raising a limit for every caller works against enforcing a contract rate and sends more requests to the backend.`]],slots:[1,4],evidence:[`apigw-caching|With caching, you can reduce the number of calls made to your endpoint and also improve the latency of requests to your API.`,`apigw-usage-plans|You can configure usage plans and API keys to allow customers to access selected APIs, and begin throttling requests to those APIs based on defined limits and quotas.`,`apigw-http-vs-rest|REST APIs support more features than HTTP APIs, while HTTP APIs are designed with minimal features so that they can be offered at a lower price.`]}),t({id:`throttle-lb-gate-010`,building:`throttle-lb-gate`,bullets:[`4.4-S6`],d:1,tags:[`placement-eligible`],stem:`A startup needs a public API in front of a Lambda function for its own web client. It needs no API keys, per-client limits, caching or developer portal, and it wants the LOWEST price for the API layer. Which solution meets these requirements?`,correct:[`Amazon API Gateway HTTP API with a Lambda integration and default stage throttling`,`HTTP APIs are designed with minimal features so that they can be offered at a lower price, and these requirements need none of the extra REST features.`],wrong:[[`Amazon API Gateway REST API with a usage plan, API keys and API caching enabled`,`A REST API supports more features that the startup does not need, so it is not the lowest price for this workload.`],[`An Application Load Balancer with a Lambda function registered as a target in a target group`,`The balancer adds an hourly charge and a capacity-unit charge on top of the function costs for features the startup does not need.`],[`Amazon API Gateway REST API with a Lambda proxy integration and none of the extra features turned on`,`A REST API supports more features than an HTTP API, while HTTP APIs are designed with minimal features so that they can be offered at a lower price.`]],slot:0,evidence:[`apigw-http-vs-rest|REST APIs support more features than HTTP APIs, while HTTP APIs are designed with minimal features so that they can be offered at a lower price.`,`apigw-http-vs-rest|Features REST API HTTP API Custom domains Yes Yes API keys Yes No Per-client rate limiting Yes No Per-client usage throttling Yes No Developer portal Yes No`]}),t({id:`throttle-lb-gate-011`,building:`throttle-lb-gate`,bullets:[`4.4-K3`],d:2,tags:[`mock-reserve`,`trap:alb-nlb-gwlb`],stem:`A company inspects all inbound traffic with virtual firewall appliances in two Availability Zones behind a Gateway Load Balancer. Each zone has the same number of appliances. The company wants to avoid avoidable charges for data transfer between zones while keeping both zones in use. Which configuration is the MOST cost-effective?`,correct:[`Keep the default setting of cross-zone load balancing disabled and run the same number of appliances in each zone`,`Cross-zone load balancing is disabled by default for Gateway Load Balancers, so each node uses the appliances in its own zone and traffic stays in the zone.`],wrong:[[`Enable cross-zone load balancing so that every node can reach appliances in all zones at any time`,`Enabled cross-zone load balancing distributes traffic across zones, which is the behaviour that creates the zone-to-zone transfer.`],[`Replace the Gateway Load Balancer with a Network Load Balancer that has cross-zone load balancing enabled`,`Cross-zone data transfer on a Network Load Balancer is charged as well, and it does not forward traffic transparently to the appliances.`],[`Register all appliances in one zone and route the other zone through a second Gateway Load Balancer`,`A second balancer adds hourly and capacity-unit charges and still moves traffic between zones.`]],slot:1,evidence:[`elb-how-it-works|With Network Load Balancers and Gateway Load Balancers, cross-zone load balancing is disabled by default.`,`elb-faqs|Yes, you will be charged for data transfer between Availability Zones with Gateway Load Balancer when cross-zone load balancing is enabled.`,`elb-how-it-works|When cross-zone load balancing is disabled, each load balancer node distributes traffic only across the registered targets in its Availability Zone.`]}),t({id:`throttle-lb-gate-012`,building:`throttle-lb-gate`,bullets:[`4.4-S6`],d:2,tags:[`mock-reserve`],stem:`A company has one REST API on Amazon API Gateway with a read-heavy method and an expensive report method that starts a long database query. The company wants the report method to allow far fewer requests per second than the rest of the API, without creating a second API. Which solution is the SIMPLEST?`,correct:[`Set a lower method-level throttling target for the report method and keep the stage-level target for the other methods`,`API Gateway lets an API developer set target limits for individual API stages or methods, so one method can be restricted on its own.`],wrong:[[`Lower the account-level throttle so that every API in the account receives fewer requests per second`,`The account-level limit applies to all APIs in the account per Region and would also slow the read-heavy method.`],[`Create a second REST API for the report method and give the new API a lower throttle than the first one for the callers of the report`,`A second API adds management work, and the requirement was to avoid creating a second API.`],[`Enable provisioned concurrency on the report function so that the long database query is served sooner`,`Provisioned concurrency incurs additional charges and pre-initializes execution environments, so it does not limit how many report requests can arrive.`]],slot:3,evidence:[`apigw-throttling|As an API developer, you can set the target limits for individual API stages or methods to improve overall performance across all APIs in your account.`,`apigw-throttling|Specifically, API Gateway examines the rate and a burst of request submissions against all APIs in your account, per Region.`,`lambda-provisioned|Configuring provisioned concurrency incurs additional charges to your AWS account.`,`lambda-concurrency|Provisioned concurrency is the number of pre-initialized execution environments that you want to allocate to your Event Function.`]})],x=[t({id:`transit-tariff-001`,building:`transit-tariff`,bullets:[`4.4-K5`],d:1,tags:[`trap:direct-connect-vs-vpn`],stem:`A company has 300 employees who work from home and need secure access to resources in a VPC and in the company data centre from their laptops. The company wants a managed service that avoids deploying and maintaining its own remote access VPN servers. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`AWS Client VPN, so that each employee connects with an OpenVPN-based VPN client`,`Client VPN is a managed client-based VPN service for users, and it removes the burden of deploying and maintaining third-party remote access VPN solutions.`],wrong:[[`AWS Direct Connect with a hosted connection ordered through a Direct Connect Partner`,`Direct Connect links a network to AWS; it does not give individual employees at home a way to connect.`],[`AWS Site-to-Site VPN with a customer gateway device installed in each employee's home`,`Site-to-Site VPN connects whole networks and would need a device configured at every home, which is heavy to operate.`],[`An Amazon EC2 instance running third-party VPN software in a public subnet of the VPC`,`The company would have to deploy, patch and maintain the server itself, which is the overhead it wants to avoid.`]],slot:0,evidence:[`client-vpn|AWS Client VPN is a managed client-based VPN service that enables you to securely access your AWS resources and resources in your on-premises network.`,`client-vpn|Managed service — Eliminates the operational burden of deploying and maintaining third-party remote access VPN solutions through complete AWS management.`]}),t({id:`transit-tariff-002`,building:`transit-tariff`,bullets:[`4.4-K5`,`4.4-S2`],d:2,tags:[`trap:direct-connect-vs-vpn`],stem:`A company opens a branch office and needs encrypted connectivity between the office network and its VPC within a few days. The expected traffic is low and the company already has an internet connection at the office. The company wants the LOWEST cost for this connection. Which solution meets these requirements?`,correct:[`An AWS Site-to-Site VPN connection over the existing internet connection with both tunnels configured`,`A Site-to-Site VPN creates an IPsec connection over the internet with no physical port to order, charged per connection-hour plus data transfer.`],wrong:[[`An AWS Direct Connect dedicated connection ordered for the branch office with a port in a nearby location`,`AWS can take up to 72 business hours just to provision a port, the cross-connect is separate, and port hours are charged for low traffic.`],[`An AWS Direct Connect hosted connection that a partner provisions with a private virtual interface`,`A partner has to provision the connection, which takes longer than a few days, and it does not encrypt the traffic by default.`],[`An AWS Client VPN endpoint with a client installed on every device in the branch office`,`Client VPN is for individual users accessing resources, not for connecting a whole office network to a VPC.`]],slot:1,evidence:[`connectivity-vpn|Amazon VPC provides the option of creating an IPsec VPN connection between your remote networks and Amazon VPC over the internet`,`vpn-pricing|You also incur standard AWS data transfer charges for all data transferred via the VPN connection.`,`dx-classic-connection|It can take up to 72 business hours for AWS to review your request and provision a port for your connection.`]}),t({id:`transit-tariff-003`,building:`transit-tariff`,bullets:[`4.4-S2`],d:1,tags:[`trap:direct-connect-vs-vpn`],stem:`A media company moves large volumes of video from its data centre to Amazon S3 every day, all year, and the transfers need consistent network performance. The traffic currently uses internet-based connections and the company wants to reduce network costs over time. Which solution is the MOST cost-effective for this steady workload?`,correct:[`Provision an AWS Direct Connect connection and send the data through a public virtual interface to Amazon S3`,`Direct Connect can reduce network costs, increase bandwidth throughput and provide a more consistent network experience than internet-based connections.`],wrong:[[`Keep using internet connections and add an AWS Site-to-Site VPN with two tunnels for the transfers from the data centre`,`A VPN still runs over the internet, so it does not provide the consistent network performance the workload needs.`],[`Add an AWS Client VPN endpoint and have the transfer servers connect to it as individual clients`,`Client VPN is for remote users, it travels over the internet, and it does not lower the cost of steady bulk transfers.`],[`Open more internet circuits at the data centre and spread the transfers across all of them`,`This adds circuits to pay for and still gives the variable network experience of internet-based connections.`]],slot:2,evidence:[`connectivity-dx|Direct Connect can reduce network costs, increase bandwidth throughput, and provide a more consistent network experience than internet-based connections.`,`dx-what-is|you can create virtual interfaces directly to public AWS services (for example, to Amazon S3) or to Amazon VPC, bypassing internet service providers in your network path.`]}),e({id:`transit-tariff-004`,building:`transit-tariff`,bullets:[`4.4-K5`,`4.4-S2`],d:3,tags:[`trap:direct-connect-vs-vpn`],stem:`A company has one AWS Direct Connect connection from its data centre to a VPC in one Region. It is adding VPCs in two other Regions and wants private access from the data centre to all three VPCs over the existing connection. The company wants the LOWEST additional cost and does not want to order connections in the other Regions. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a Direct Connect gateway and a private virtual interface from the existing connection to it`,`A Direct Connect gateway is a globally available resource, and you can connect to any Region globally using it.`],[`Associate the virtual private gateway of each VPC with the Direct Connect gateway`,`A Direct Connect gateway can be associated with a virtual private gateway, so one connection serves the VPCs in all three Regions.`]],wrong:[[`Order a Direct Connect connection in each of the two other Regions`,`Each extra connection adds port charges and a new circuit, which the company wants to avoid.`],[`Create a Site-to-Site VPN connection from the data centre to each new VPC over the internet`,`The traffic would not use the existing Direct Connect connection, and each VPN connection adds its own hourly charge.`],[`Peer the new VPCs with the first VPC and route the data centre traffic through that VPC`,`Resources in a peered VPC cannot use the Direct Connect connection of another VPC to reach the corporate network.`]],slots:[0,4],evidence:[`dx-gateway|A Direct Connect gateway is a globally available resource.`,`dx-gateway|You can connect to any Region globally using a Direct Connect gateway.`,`dx-gateway|You associate a Direct Connect gateway with any of the following: A Transit Gateway when you have multiple VPCs in the same Region A virtual private gateway An AWS Cloud WAN core network`,`peering-basics|If VPC A has an Direct Connect connection to a corporate network, resources in VPC B can't use the Direct Connect connection to communicate with the corporate network.`]}),t({id:`transit-tariff-005`,building:`transit-tariff`,bullets:[`4.4-S2`,`4.4-S7`],d:2,tags:[`trap:direct-connect-vs-vpn`],stem:`A retailer needs a private, dedicated link from its data centre to AWS for about 200 Mbps of steady traffic. It does not expect to need much more for years, and it wants to avoid paying for far more port capacity than it uses. Which solution is the MOST cost-effective?`,correct:[`An AWS Direct Connect hosted connection at 200 Mbps provisioned by an AWS Direct Connect Partner`,`Hosted connections offer speeds below 1 Gbps, including 200 Mbps, and port hour pricing depends on capacity, so the port is sized to the load.`],wrong:[[`An AWS Direct Connect dedicated connection at 1 Gbps requested through the console`,`The lowest dedicated speed is 1 Gbps, five times the need, and port hour pricing is determined by capacity.`],[`An AWS Direct Connect dedicated connection at 10 Gbps so the link never has to be replaced as traffic grows`,`Ten gigabits is far more capacity than the need, and port hour pricing depends on capacity and connection type.`],[`An AWS Client VPN endpoint sized for 200 Mbps with client software on the data centre servers`,`Client VPN is a user-access service over the internet, so it is not a dedicated link for the data centre.`]],slot:3,evidence:[`dx-hosted|Port speed For hosted connections, the possible values are 50 Mbps, 100 Mbps, 200 Mbps, 300 Mbps, 400 Mbps, 500 Mbps, 1 Gbps, 2 Gbps, 5 Gbps, 10 Gbps, and 25 Gbps.`,`dx-dedicated|Port speed The possible values are 1 Gbps, 10 Gbps, 100 Gbps, and 400 Gbps.`,`dx-what-is|Port hour pricing is determined by capacity and connection type (dedicated connection or hosted connection).`]}),e({id:`transit-tariff-006`,building:`transit-tariff`,bullets:[`4.4-S7`],d:2,tags:[`trap:direct-connect-vs-vpn`],stem:`A company's Site-to-Site VPN connection to a VPC cannot carry the peak traffic of one standard tunnel. The company does not want to order Direct Connect and wants to increase VPN bandwidth by using several tunnels at once. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Attach the VPN connections to an AWS Transit Gateway`,`On a transit gateway, ECMP can aggregate multiple VPN tunnels to get higher VPN bandwidth.`],[`Configure the VPN connections for dynamic routing`,`ECMP requires dynamic routing and is not supported on VPN connections that use static routing.`]],wrong:[[`Configure the VPN connections with static routes so that every tunnel is always in use`,`ECMP is not supported on VPN connections that use static routing, so the tunnels would not be aggregated.`],[`Replace the VPN with an AWS Client VPN endpoint and connect each server as a client`,`Client VPN is for individual users, and it does not combine tunnels between two networks.`],[`Order a 50 Mbps hosted Direct Connect connection and move the peak traffic onto it`,`A 50 Mbps connection offers far less than one VPN tunnel and would not raise the available bandwidth.`]],slots:[1,2],evidence:[`vpn-quotas|For Site-to-Site VPN connections on a transit gateway, you can use ECMP to get higher VPN bandwidth by aggregating multiple VPN tunnels.`,`vpn-quotas|To use ECMP, the VPN connection must be configured for dynamic routing.`,`vpn-quotas|ECMP is not supported on VPN connections that use static routing.`]}),t({id:`transit-tariff-007`,postGuide:[`direct-connect-400g`],building:`transit-tariff`,bullets:[`4.4-S7`],d:2,tags:[],stem:`A company is ordering a dedicated AWS Direct Connect connection. Measured traffic is about 3 Gbps now and is forecast to reach 8 Gbps within the first year. The company wants to avoid creating and configuring a new connection later, and does not want more port capacity than the forecast needs. Which port speed is the MOST cost-effective choice?`,correct:[`10 Gbps, because a dedicated port speed cannot be changed after the request and 10 Gbps covers the forecast`,`The port speed cannot be changed after the request, and 10 Gbps is the smallest dedicated speed that covers the eight gigabit forecast.`],wrong:[[`1 Gbps now, and then increase the port speed of the same connection when the traffic grows within the next year`,`The port speed cannot be changed after the connection request, and 1 Gbps is already below the current traffic.`],[`100 Gbps, so that the connection never has to change whatever happens to the traffic`,`100 Gbps is far more capacity than the forecast, and port hour pricing is determined by capacity.`],[`400 Gbps, so that the company can later divide the capacity between its business units`,`400 Gbps greatly exceeds the forecast, and port hour pricing is determined by capacity and connection type.`]],slot:0,evidence:[`dx-dedicated|Port speed The possible values are 1 Gbps, 10 Gbps, 100 Gbps, and 400 Gbps.`,`dx-dedicated|You can't change the port speed after you create the connection request.`,`dx-what-is|Port hour pricing is determined by capacity and connection type (dedicated connection or hosted connection).`]}),t({id:`transit-tariff-008`,building:`transit-tariff`,bullets:[`4.4-S7`],d:3,tags:[`trap:direct-connect-vs-vpn`],stem:`A company needs about 15 Gbps of steady Direct Connect capacity at one location, managed as a single connection. The company orders only dedicated connections and does not want to pay for much more port capacity than it needs. Which solution is the MOST cost-effective?`,correct:[`A link aggregation group of two 10 Gbps dedicated connections at the same Direct Connect endpoint`,`A LAG combines connections of the same speed into one managed connection, and two 10 Gbps ports cover the need with far less capacity than a 100 Gbps port.`],wrong:[[`A single 100 Gbps dedicated connection`,`This is far more capacity than 15 Gbps, and port hour pricing is determined by capacity.`],[`A link aggregation group of four 1 Gbps dedicated connections`,`Four 1 Gbps ports give only 4 Gbps, which is below the need.`],[`A link aggregation group of one 10 Gbps dedicated connection and one 5 Gbps hosted connection`,`All connections in a LAG must be dedicated and must use the same bandwidth.`]],slot:0,evidence:[`dx-lags|A link aggregation group (LAG) is a logical interface that uses the Link Aggregation Control Protocol (LACP) to aggregate multiple connections at a single Direct Connect endpoint, allowing you to treat them as a single, managed connection.`,`dx-lags|All connections in the LAG must use the same bandwidth.`,`dx-lags|All connections must be dedicated connections and have a port speed of 1 Gbps, 10 Gbps, 100 Gbps, or 400 Gbps.`,`dx-what-is|Port hour pricing is determined by capacity and connection type (dedicated connection or hosted connection).`]}),t({id:`transit-tariff-009`,building:`transit-tariff`,bullets:[`4.4-S2`],d:2,tags:[`mock-reserve`,`trap:direct-connect-vs-vpn`],stem:`A company uses an AWS Direct Connect connection as its primary path to AWS. If the connection fails, the business can work with lower speeds and an internet path for a few hours. The company wants a backup path at the LOWEST cost. Which solution meets these requirements?`,correct:[`An AWS Site-to-Site VPN connection over the internet configured as a backup to the Direct Connect connection`,`A Site-to-Site VPN is an IPsec connection over the internet with no physical port, charged per connection-hour plus data transfer.`],wrong:[[`A second Direct Connect connection on separate devices in a different location for maximum resiliency for the company`,`This gives the highest resiliency but adds port charges and more cost than a backup that can run at lower speeds.`],[`An AWS Client VPN endpoint that the application servers use as a failover path to the VPC`,`Client VPN is a client-based service for users and is not designed as a network-to-network backup path.`],[`A larger port speed on the existing Direct Connect connection so that it is less likely to fail`,`A larger port does not protect against a device, connectivity or location failure and increases port charges.`]],slot:2,evidence:[`dx-faqs|If you have configured a backup IPsec VPN connection instead, all VPC traffic will failover to the VPN connection automatically.`,`dx-resiliency|You can achieve maximum resiliency for critical workloads by using separate connections that terminate on separate devices in more than one location`,`connectivity-vpn|Amazon VPC provides the option of creating an IPsec VPN connection between your remote networks and Amazon VPC over the internet`,`vpn-pricing|You also incur standard AWS data transfer charges for all data transferred via the VPN connection.`]})],S=Object.values(Object.assign({"../../content/questions/treasury/backup-archive.ts":n,"../../content/questions/treasury/block-warehouse.ts":r,"../../content/questions/treasury/capacity-meter.ts":i,"../../content/questions/treasury/cold-cellar.ts":a,"../../content/questions/treasury/counting-house.ts":o,"../../content/questions/treasury/db-cost-desk.ts":s,"../../content/questions/treasury/distribution-office.ts":c,"../../content/questions/treasury/elastic-mint.ts":l,"../../content/questions/treasury/engine-exchange.ts":u,"../../content/questions/treasury/haul-hybrid-customs.ts":d,"../../content/questions/treasury/instance-foundry.ts":f,"../../content/questions/treasury/ledger-office.ts":p,"../../content/questions/treasury/nat-toll.ts":m,"../../content/questions/treasury/network-cost-audit.ts":h,"../../content/questions/treasury/retention-records.ts":g,"../../content/questions/treasury/route-tariff.ts":_,"../../content/questions/treasury/service-selection-bureau.ts":v,"../../content/questions/treasury/storage-market.ts":y,"../../content/questions/treasury/throttle-lb-gate.ts":b,"../../content/questions/treasury/transit-tariff.ts":x})).flat();export{S as questions};